/* Atlas : montagnes et volcans, îles, déserts, continents — généré par tools/atlas-build-themes.mjs. Chiffres : Wikidata (CC0). Textes : Vikidia / Wikipédia (CC BY-SA 4.0), lien par fiche. */
window.MQ_ATLAS_T=window.MQ_ATLAS_T||{};Object.assign(window.MQ_ATLAS_T,{
"montagnes":{"agung":{"n":"Agung","t":"sommet","bref":["L'Agung ou mont Agung, en balinais : ᬕᬸᬦᬸᬂ ᬆᬕᬸᬂ, en indonésien Gunung Agung, littéralement en français « montagne suprême » ou « montagne sacrée », est un volcan d'Indonésie situé sur l'île de Bali dont il constitue le point culminant avec 2 995, 3 031 ou 3 142 mètres d'altitude. Stratovolcan conique aux pentes régulières et escarpées, il est couronné par un cratère. Pour les Balinais hindouistes, il est considéré comme le fils du Semeru de Java qui est lui-même le fils du mont Meru de l'hindouisme."],"src":"https://fr.wikipedia.org/wiki/Agung","sw":"w","q":"Q158470","pays":["ID"],"c":["asie"]},"alpes":{"n":"Alpes","t":"sommet","bref":["Les Alpes sont une chaîne de montagnes du Sud de l'Europe. Elles traversent l'Italie, la France, Monaco, la Suisse, le Liechtenstein, l'Autriche, l'Allemagne et la Slovénie. Le plus haut sommet est le Mont Blanc avec 4 809 mètres d'altitude. Les Alpes déroulent leurs crêtes sur près de 1 250 km depuis Vado Ligure (Italie) jusqu'à Höflein an der Donau (Autriche), sur les bords du Danube. La largeur maximale de la chaîne est de 246 km, formant ainsi une épaisse barrière naturelle, toutefois facilement pénétrable et franchissable grâce aux nombreuses vallées fluviales et aux nombreux cols. L'homme y a aussi aménagé de nombreux tunnels (ferroviaires comme le tunnel du Saint-Gothard ou routiers comme le tunnel du Mont-Blanc). Il y a beaucoup de glaciers dans les Alpes."],"src":"https://fr.vikidia.org/wiki/Alpes","sw":"v","q":"Q1286","pays":["DE","AT","CH","FR","IT","SI","MC","LI","HU"],"c":["europe"]},"alpes-dinariques":{"n":"Alpes dinariques","t":"sommet","bref":["Les Alpes dinariques ou Dinarides sont un massif montagneux des Balkans occidentaux qui doivent leur nom au mont Dinara. Elles s'élèvent entre le bassin du moyen Danube au nord-est et la mer Adriatique au sud-ouest, en plusieurs chaînes montagneuses orientées principalement selon un axe nord-ouest - sud-est, de la Slovénie au nord de l'Albanie où culmine leur plus haut sommet, à 2 692 mètres d'altitude : le Maja e Jezercës. Elles couvrent au total six pays reconnus internationalement, auxquels peut s'ajouter le Kosovo. La plus grande ville est Sarajevo, capitale de la Bosnie-Herzégovine. Trois climats distincts influencent le massif : méditerranéen à l'ouest, montagnard au centre, où le relief est le plus élevé, et continental à l'est."],"src":"https://fr.wikipedia.org/wiki/Alpes_dinariques","sw":"w","q":"Q189915","pays":["RS","HR","BA","SI","ME","AL","XK"],"c":["europe"]},"alpes-du-sud":{"n":"Alpes du Sud","t":"sommet","bref":["Les Alpes du Sud (en anglais : Southern Alps, en maori de Nouvelle-Zélande : Kā Tiritiri o te Moana, littéralement « les crêtes de la mer », car leurs sommets enneigés font penser à des vagues sur la mer), aussi appelées Alpes néo-zélandaises, sont une chaîne de montagnes située sur la partie occidentale de l'île du Sud en Nouvelle-Zélande. Elles forment une limite naturelle dans le sens de la longueur de l'île du Sud. L'Aoraki/Mont Cook (Aoraki est le nom en langue māori jumelé avec le nom du navigateur britannique) est le point culminant à 3 724 m d'altitude. Seize autres sommets de la chaîne s'élèvent à plus de 3 000 m d'altitude.","Les parcs nationaux occupent une part importante du massif, les principaux étant : le parc national de Westland Tai Poutini, le parc national du mont Aspiring et le parc national Aoraki/Mount Cook. Les Alpes du Sud comptent aussi quelque 360 glaciers. Le glacier Tasman, le plus vaste d'entre eux, s'étend sur 29 kilomètres."],"src":"https://fr.wikipedia.org/wiki/Alpes_du_Sud_(Nouvelle-Z%C3%A9lande)","sw":"w","q":"Q206650","pays":["NZ"],"c":["oceanie"]},"alpes-scandinaves":{"n":"Alpes scandinaves","t":"sommet","bref":["Les Alpes scandinaves ou Scandes sont une chaîne de montagnes s'étendant tout le long de la côte ouest de la péninsule Scandinave. Elles couvrent l'essentiel de la Norvège, le Nord-Ouest et l'Ouest de la Suède ainsi qu'une toute petite partie de l'Extrême-Nord de la Finlande. Il s'agit d'une des plus importantes chaînes de montagnes d'Europe, s'étirant du sud-ouest au nord-est sur 1 700 km, avec une largeur maximale de 300 km. La chaîne possède deux zones de haute altitude, une dans le Sud de la Norvège, autour du Jotunheimen où se trouve le Galdhøpiggen (2 469 m), point culminant de la chaîne et du pays concerné, et une autre dans le Nord de la Suède, avec le Kebnekaise (2 102 m), point culminant du pays — le point culminant de Finlande se trouve aussi dans la chaîne : il s'agit du Halti (1 328 m)."],"src":"https://fr.wikipedia.org/wiki/Alpes_scandinaves","sw":"w","q":"Q186547","pays":["SE","FI","NO"],"c":["europe"]},"altai":{"n":"Altaï","t":"sommet","bref":["L'Altaï (ou les montagnes dorées) est une chaîne de montagnes située en Asie centrale et qui s'étend sur quatre États : le Kazakhstan, la Russie, la Chine et la Mongolie. Ce système montagneux a une longueur d'environ 2 000 km. Cette mesure inclut aussi l'Altaï mongol et l'Altaï de Gobi."],"src":"https://fr.vikidia.org/wiki/Alta%C3%AF","sw":"v","q":"Q5955","pays":["KZ","RU","MN","CN"],"c":["asie","europe"]},"annapurna":{"n":"Annapurna","t":"sommet","massif":"Himalaya","bref":["L'Annapurna est un massif de montagnes de l'Himalaya au Népal, comprenant six principaux sommets dont le plus haut, l'Annapurna I, culmine à 8 091 mètres, ce qui en fait le dixième plus haut sommet du monde."],"src":"https://fr.wikipedia.org/wiki/Annapurna","sw":"w","q":"Q159621","pays":["NP"],"c":["asie"]},"anti-liban":{"n":"Anti-Liban","t":"sommet","bref":["L'Anti-Liban (en arabe : سلسلة جبال لبنان الشرقية, Djabal al-Charqi), est une chaîne de montagnes située principalement au Liban et en Syrie, autour de la frontière entre les deux pays, ainsi qu'au plateau du Golan contrôlé par Israël. C'est une région peu habitée dominée par un climat aride sur une large partie de sa surface, mais qui abrite des températures plus froides à ses sommets."],"src":"https://fr.vikidia.org/wiki/Anti-Liban","sw":"v","q":"Q243276","pays":["LB","SY","IL"],"c":["asie"]},"aoraki-mont-cook":{"n":"Aoraki/Mont Cook","t":"sommet","massif":"Alpes du Sud","bref":["L'Aoraki/Mont Cook est le plus haut sommet de la Nouvelle-Zélande, Aoraki signifiant en maori « perceur de nuages ». Il se situe dans les Alpes du Sud, plus précisément dans la région de Canterbury, et culmine à 3 724 mètres d'altitude. Il est bordé par les glaciers Hooker à l'ouest et Tasman à l'est, ce dernier étant le plus long de Nouvelle-Zélande. Les rivages de la mer de Tasman ne sont qu'à 34 km."],"src":"https://fr.vikidia.org/wiki/Aoraki%2FMont_Cook","sw":"v","q":"Q5059","pays":["NZ"],"c":["oceanie"]},"apennins":{"n":"Apennins","t":"sommet","bref":["Les Apennins (ou l'Apennin, au singulier) sont une chaîne de montagnes située en Italie et traversant celle-ci dans toute sa longueur. Le sommet culminant de cette chaîne est le Corno Grande (2 914 m) dans le parc Gran Sasso. Par temps clair, il y est possible de voir deux mers à la fois."],"src":"https://fr.vikidia.org/wiki/Apennins","sw":"v","q":"Q1285","pays":["IT","SM"],"c":["europe"]},"appalaches":{"n":"Appalaches","t":"sommet","bref":["Les Appalaches sont une chaîne de montagnes de l'Est des États-Unis et du Canada. Elles s'étendent de Terre-Neuve jusqu'en Alabama. Les Appalaches culminent en Caroline du Nord, au mont Mitchell, avec 2 037 m d'altitude."],"src":"https://fr.vikidia.org/wiki/Appalaches","sw":"v","q":"Q93332","pays":["US","CA","FR"],"c":["amerique-nord","europe"]},"aragats":{"n":"Aragats","t":"sommet","massif":"haut plateau arménien","bref":["L'Aragats, en arménien : Արագած, en russe : Арагац, aussi appelé mont Aragats, Alagey, Aragatz ou encore Aragey, est un volcan éteint d'Arménie. Avec 4 095 mètres d'altitude, il constitue le point culminant de l'Arménie et du Petit Caucase et domine le haut-plateau arménien qui s'étend à ses pieds."],"src":"https://fr.wikipedia.org/wiki/Aragats","sw":"w","q":"Q203568","pays":["AM"],"c":["asie"]},"ascraeus-mons":{"n":"Ascraeus Mons","t":"sommet","bref":["Ascraeus Mons est un volcan bouclier situé sur la planète Mars par 11,8° N et 255,5° E, dans le quadrangle de Tharsis. Large de 460 km, il culmine à 14 km en moyenne au-dessus du renflement de Tharsis et à 18 225 m d'altitude au-dessus du niveau de référence martien, ce qui en fait le deuxième sommet de Mars. Les flancs de ce volcan présentent une inclinaison moyenne de 7°."],"src":"https://fr.wikipedia.org/wiki/Ascraeus_Mons","sw":"w","q":"Q499164"},"askja":{"n":"Askja","t":"sommet","massif":"Dyngjufjöll","bref":["L'Askja est un emboîtement de caldeiras en Islande, éponyme d'un système volcanique appartenant au graben médian et composé de ces caldeiras, la plus interne étant occupée par un lac, l'Öskjuvatn, du massif volcanique qui les entoure, les Dyngjufjöll, reste d'un ancien volcan précédant la caldeira, ainsi que de volcans boucliers, de cratères et de fissures volcaniques s'étirant dans une direction nord-sud sur une centaine de kilomètres de longueur. La dernière éruption de l'Askja remonte à la fin 1961 mais sa plus puissante des temps historiques, responsable de la formation de la caldeira remplie par l'Öskjuvatn, s'est déroulée en 1875."],"src":"https://fr.wikipedia.org/wiki/Askja","sw":"w","q":"Q211665","pays":["IS"],"c":["europe"]},"atlas":{"n":"Atlas","t":"sommet","bref":["L'Atlas est une chaîne de montagnes située en Afrique du Nord et s'étendant sur trois pays : le Maroc, l'Algérie et la Tunisie.","Il atteint 4 167 mètres d'altitude au djebel Toubkal (le plus haut point des montagnes de l'Atlas)."],"src":"https://fr.vikidia.org/wiki/Atlas_(cha%C3%AEne_de_montagnes)","sw":"v","q":"Q130135","pays":["MA","DZ","TN"],"c":["afrique"]},"avatchinski":{"n":"Avatchinski","t":"sommet","massif":"chaîne Centrale","bref":["L'Avatchinski, appelé également Avatcha, Gorelaïa sopka, Monastyr, Saria ou encore Souatchou, en russe Avatchinskaïa sopka (Авачинская сопка), est un volcan actif de Russie situé dans le sud de la péninsule du Kamtchatka dans le kraï du même nom."],"src":"https://fr.wikipedia.org/wiki/Avatchinski","sw":"w","q":"Q791652","pays":["RU"],"c":["asie","europe"]},"bar-arbunga":{"n":"Bárðarbunga","t":"sommet","bref":["Le Bárðarbunga, toponyme islandais signifiant littéralement en français « bosse de Bárður », aussi appelé Bárðarbunga-Veiðivötn du nom d'une fissure volcanique associée au volcan central, est un volcan d'Islande situé sous le Vatnajökull, la plus grande calotte glaciaire du pays. Second plus haut volcan d'Islande, il est voisin du Grímsvötn, un autre volcan sous-glaciaire connu pour ses jökulhlaups."],"src":"https://fr.wikipedia.org/wiki/B%C3%A1r%C3%B0arbunga","sw":"w","q":"Q1018862","pays":["IS"],"c":["europe"]},"bazarduzu":{"n":"Bazardüzü","t":"sommet","massif":"Grand Caucase","bref":["Le mont Bazardüzü (en azéri : Bazardüzü Dağı ; en russe : Базардюзю, Bazardiouziou) est une montagne du Grand Caucase située sur la frontière entre la Russie (Daghestan) et l'Azerbaïdjan. Il culmine à 4 466 m d'altitude et constitue le plus haut sommet d'Azerbaïdjan. Le point le plus méridional de la Russie est également situé à proximité."],"src":"https://fr.wikipedia.org/wiki/Bazard%C3%BCz%C3%BC","sw":"w","q":"Q725591","pays":["AZ","RU"],"c":["asie","europe"]},"beerenberg":{"n":"Beerenberg","t":"sommet","massif":"dorsale médio-atlantique","bref":["Le Beerenberg (nom néerlandais pour « Montagne des ours ») est un volcan de l'île Jan Mayen située entre la mer du Groenland (océan Arctique) au nord-ouest et la mer de Norvège (océan Atlantique) au sud-est."],"src":"https://fr.wikipedia.org/wiki/Beerenberg","sw":"w","q":"Q814113","pays":["NO"],"c":["europe"]},"ben-nevis":{"n":"Ben Nevis","t":"sommet","massif":"Monts Grampians","bref":["Le Ben Nevis (prononcé en anglais : /bɛn ˈnɛvɪs/ ; en gaélique écossais : Beinn Nibheis, prononcé : /pe(ɲ) ˈɲivɪʃ/) est le point culminant des îles Britanniques avec 1 345 mètres d'altitude. Situé près de Fort William en Écosse, il fait partie des monts Grampians dans les Highlands. Gravi pour la première fois en 1771, il est coiffé par les ruines d'un observatoire construit et utilisé à la fin du XIXe siècle pour effectuer des observations météorologiques qui sont restées très importantes dans la compréhension du climat en Grande-Bretagne. Celui qui sévit au sommet, extrêmement rude, lui vaut d'ailleurs son nom, Nibheis signifiant « malveillant » en gaélique écossais."],"src":"https://fr.wikipedia.org/wiki/Ben_Nevis","sw":"w","q":"Q104674","pays":["GB"],"c":["europe"]},"broad-peak":{"n":"Broad Peak","t":"sommet","massif":"Gasherbrum","bref":["Le Broad Peak est un sommet culminant à 8 051 mètres d'altitude, à la frontière entre la Chine et le Pakistan, dans le Karakoram. Il constitue le douzième plus haut sommet du monde. Sa première ascension a été réussie le 9 juin 1957 par les Autrichiens Hermann Buhl, Kurt Diemberger, Marcus Schmuck et Fritz Wintersteller. Leur itinéraire, par l'éperon ouest puis le final par l'arête nord, est devenu la voie normale empruntée par la quasi-totalité des alpinistes, les autres voies étant rarement répétées."],"src":"https://fr.wikipedia.org/wiki/Broad_Peak","sw":"w","q":"Q180996","pays":["PK","CN"],"c":["asie"]},"carpates":{"n":"Carpates","t":"sommet","bref":["Les Carpates sont une importante chaîne de montagnes de l'Europe centrale. En fait, elles prolongent les Alpes, et forment un grand arc qui débute aux portes de Bratislava, en Slovaquie. Dans ce pays se trouve le sommet de la chaîne (le Gerlachovsky štít). La chaîne de montagnes déborde sur le territoire de la République tchèque, traverse ensuite le Sud de la Pologne, puis l'Ukraine et la Roumanie, avant de se terminer en Serbie. Les Carpates ont une surface de 209 000 km2 dont 53 % se situent en Roumanie et 17 % en Slovaquie.","Le mot « Carpates » provient du mot albanais « karpë » qui veut dire « rocher »."],"src":"https://fr.vikidia.org/wiki/Carpates","sw":"v","q":"Q1288","pays":["RS","UA","AT","CZ","SK","PL","HU","RO"],"c":["europe"]},"caucase":{"n":"Caucase","t":"sommet","bref":["La géographie du Caucase peut être schématisée par une chaîne de montagnes rectiligne, qui ne prend une certaine hauteur qu'à environ 300 km du détroit de Kertch et culmine, dans sa partie centrale, avec de vastes massifs volcaniques englacés."],"src":"https://fr.wikipedia.org/wiki/G%C3%A9ographie_du_Caucase","sw":"w","q":"Q5477","pays":["RU"],"c":["asie","europe"]},"cervin":{"n":"Cervin","t":"sommet","massif":"Alpes pennines","bref":["Le mont Cervin, appelé Matterhorn en allemand, Matterhòre en greschòneytitsch (un dialecte de l'alémanique) et Monte Cervino en italien, est un sommet alpin de 4 478 mètres d'altitude, situé dans les Alpes pennines à la frontière italo-suisse, entre le canton du Valais (en Suisse), et la vallée d'Aoste (en Italie).","L'image du mont Cervin est emblématique de la Suisse, surtout pour son aspect pyramidal et la vue que l'on en a depuis le Gornergrat, un sommet voisin du village de Zermatt et accessible par voie ferrée. En effet, le Gornergratbahn, un chemin de fer à crémaillère, fait le bonheur de très nombreux touristes, été comme hiver. Depuis le point de vue de la gare terminale du Gornergratbahn, le 6 mars ou le 6 octobre, on peut voir par temps clair le soleil se coucher juste derrière le Cervin."],"src":"https://fr.vikidia.org/wiki/Mont_Cervin","sw":"v","q":"Q1374","pays":["CH","IT"],"c":["europe"]},"chaine-des-cascades":{"n":"chaîne des Cascades","t":"sommet","alt":4392,"massif":"chaînes côtières du Pacifique","bref":["La chaîne des Cascades, en anglais Cascade Range, est une suite montagneuse qui prend naissance au Canada, sur la rive sud du fleuve Fraser, en Colombie-Britannique, et se poursuit aux États-Unis dans les États de Washington et de l'Oregon pour se terminer en Californie dans les environs du pic Lassen. La chaîne a une longueur de 1 210 kilomètres et est orientée nord-sud."],"src":"https://fr.vikidia.org/wiki/Cha%C3%AEne_des_Cascades","sw":"v","q":"Q4558","pays":["US","CA"],"c":["amerique-nord"]},"chaine-pontique":{"n":"chaîne pontique","t":"sommet","bref":["La chaîne pontique (en géorgien : პონტოს მთები ; en turc Kuzey Anadolu Dağlari ou Karadeniz Dağlari), aussi appelée Alpes pontiques, est un massif montagneux situé dans le nord de la Turquie (il tire son nom de la région du Pont), et dont l'extrémité orientale atteint le sud-ouest de la Géorgie. La chaîne s'étire approximativement d'ouest en est sur 500 km, surplombant la côte méridionale de la mer Noire. Son sommet le plus élevé est le Kaçkar Dağı (ou mont Cauron jusqu'au XIe siècle) qui s'élève à 3 942 m. La faille nord-anatolienne et la faille anatolienne du nord-est courent le long de la chaîne.","Les montagnes sont principalement couvertes de forêts denses, composées majoritairement de conifères et formant une écorégion spécifique. L'étroite plaine côtière entre les sommets de la chaîne et la mer, ainsi que les nombreuses vallées qui l'arrosent, ont été autrefois le cœur du royaume du Pont et de l'empire de Trébizonde ; elle abrite une forêt tempérée humide. Le plateau anatolien, au sud de la chaîne, connaît un climat continental bien plus sec."],"src":"https://fr.wikipedia.org/wiki/Cha%C3%AEne_pontique","sw":"w","q":"Q519263","pays":["TR"],"c":["asie","europe"]},"chaine-transantarctique":{"n":"chaîne Transantarctique","t":"sommet","bref":["La chaîne Transantarctique, ou monts Transantarctiques, est une longue chaîne de montagnes située en Antarctique. Elle traverse une grande partie du continent, de la terre Victoria à la mer de Weddell, en séparant sa partie orientale d'une part de sa partie occidentale et de la côte ouest de la mer de Ross d'autre part. Elle est entrecoupée par de nombreux glaciers alimentés par l'inlandsis Est-Antarctique et s'épanchant depuis le plateau Antarctique. Elle culmine à 4 528 mètres d'altitude au mont Kirkpatrick et possède vingt sommets d'au moins 4 000 mètres d'altitude."],"src":"https://fr.wikipedia.org/wiki/Cha%C3%AEne_Transantarctique","sw":"w","q":"Q319671"},"chaiten":{"n":"Chaitén","t":"sommet","massif":"Cordillère de Patagonie","bref":["Le Chaitén est un volcan du sud du Chili constitué d'une caldeira dans laquelle s'inscrit un dôme de lave. Peu élevé comparativement aux volcans voisins Michinmahuida et Corcovado, il est dépourvu de glacier. Alors considéré comme éteint, il entre en éruption à partir de mai 2008 et détruit la ville voisine de Chaitén, forçant ses habitants à évacuer dans une nouvelle ville construite un peu plus loin."],"src":"https://fr.wikipedia.org/wiki/Chait%C3%A9n_(volcan)","sw":"w","q":"Q152380","pays":["CL"],"c":["amerique-sud"]},"champs-phlegreens":{"n":"Champs Phlégréens","t":"sommet","bref":["Pouzzoles (en italien Pozzuoli) est une ville de 82 000 habitants, située en bord de mer, à l'ouest de Naples, en Campanie (Italie).","Cette ancienne cité grecque, devenue par la suite une importante colonie romaine, s'est établie sur la zone volcanique des champs Phlégréens, une immmense caldeira formée voici 36 000 ans puis dans un deuxième temps il y a 15 000 ans à la suite de l'éruption d'un supervolcan."],"src":"https://fr.vikidia.org/wiki/Pouzzoles","sw":"v","q":"Q755123","pays":["IT"],"c":["europe"]},"chimborazo":{"n":"Chimborazo","t":"sommet","massif":"cordillère des Andes","bref":["Le Chimborazo est un volcan d’Équateur culminant à 6 263 m d’altitude et situé près de Riobamba, à environ 180 km au sud de Quito. C’est le plus haut sommet des Andes équatoriennes, qui domine une région de 50 000 km2, sa base faisant 20 km de diamètre.","Il est surnommé Taita Chimborazo, c’est-à-dire Papa Chimborazo, la mère associée étant Mama Tungurahua."],"src":"https://fr.wikipedia.org/wiki/Chimborazo_(volcan)","sw":"w","q":"Q14081","pays":["EC"],"c":["amerique-sud"]},"chiveloutch":{"n":"Chiveloutch","t":"sommet","massif":"Chaîne Orientale","bref":["Le Chiveloutch ou Cheveloutch, en cyrillique Шивелуч ou Шевелуч, est un volcan de Russie situé dans la péninsule du Kamtchatka. C'est l'un des volcans les plus grands et les plus actifs de cette région de Russie."],"src":"https://fr.wikipedia.org/wiki/Chiveloutch","sw":"w","q":"Q48877","pays":["RU"],"c":["asie","europe"]},"cho-oyu":{"n":"Cho Oyu","t":"sommet","massif":"Mahalangur Himal","bref":["Le Cho Oyu est un sommet culminant à 8 188 mètres d'altitude, à la frontière entre le Tibet, en Chine, et le Népal, dans l'Himalaya. Il constitue le sixième sommet le plus élevé du monde. Sa première ascension a été réussie le 19 octobre 1954, un an et demi après celle de l'Everest situé à moins de trente kilomètres, par Herbert Tichy, Josef Jöchler et Pasang Dawa Lama. L'itinéraire qu'ils ont gravi, se terminant sur la face nord-ouest et peu technique, est devenu la voie normale empruntée par la quasi-totalité des alpinistes, malgré une grande diversité de voies ouvertes dans la seconde moitié du XXe siècle. Les versants nord et sud font respectivement partie de la réserve naturelle du Qomolangma et du parc national de Sagarmatha."],"src":"https://fr.wikipedia.org/wiki/Cho_Oyu","sw":"w","q":"Q170089","pays":["NP","CN"],"c":["asie"]},"copahue":{"n":"Copahue","t":"sommet","massif":"cordillère des Andes","bref":["Le Copahue est un stratovolcan situé à la frontière entre l'Argentine et le Chili."],"src":"https://fr.wikipedia.org/wiki/Copahue","sw":"w","q":"Q312930","pays":["AR","CL"],"c":["amerique-sud"]},"cordillere-australienne":{"n":"Cordillère australienne","t":"sommet","bref":["La Cordillère australienne (en anglais : Great Dividing Range) est une chaîne de montagnes de l'Est de l'Australie. D'une longueur d'environ 3500 km, elle traverse trois États et un territoire : l'État de Victoria depuis les monts Grampians, la Nouvelle-Galles du Sud, le territoire de la capitale fédérale, et enfin le Queensland jusqu'au cap Melville."],"src":"https://fr.vikidia.org/wiki/Cordill%C3%A8re_australienne","sw":"v","q":"Q192583","pays":["AU"],"c":["oceanie"]},"cordillere-des-andes":{"n":"cordillère des Andes","t":"sommet","massif":"cordillère américaine","bref":["La cordillère des Andes, couramment appelée les Andes, est une chaîne de montagnes d'Amérique du Sud. C'est la plus longue de la Terre et, après avoir décrit un arc dans le Nord de l'Amérique du Sud, elle s'oriente nord-sud le long de la côte ouest du Chili. Les habitants des Andes sont les Andins.","Le mot Andes vient du quechua anti qui désigne les habitants de la montagne du Pérou. Le mot cordillère quant à lui vient de l'espagnol cordillera, qui signifie « corde »."],"src":"https://fr.vikidia.org/wiki/Cordill%C3%A8re_des_Andes","sw":"v","q":"Q5456","pays":["BO","CL","CO","EC","PE","VE","AR"],"c":["amerique-sud"]},"cordillere-du-kunlun":{"n":"Cordillère du Kunlun","t":"sommet","bref":["La cordillère du Kunlun (ou Kunlun Shan en chinois) est un système montagneux d'Asie centrale qui s'étend depuis le Pamir au Tadjikistan à l'ouest jusqu'aux chaînes adjacentes (Burhan Budai, Bayan Har et A'nyêmaqên Shan) de la province centrale de Qinghai, en Chine, à l'est. D'une longueur d'environ 2 600 kilomètres, le Kunlun a une largeur variable, sans toutefois dépasser 170 kilomètres."],"src":"https://fr.vikidia.org/wiki/Cordill%C3%A8re_du_Kunlun","sw":"v","q":"Q187871","pays":["CN"],"c":["asie"]},"cotopaxi":{"n":"Cotopaxi","t":"sommet","massif":"cordillère des Andes","bref":["Le volcan Cotopaxi (en espagnol, volcán Cotopaxi) est situé en Équateur, et plus précisément à 56 km au sud de la capitale, Quito, et à 75 km au sud de la ligne équatoriale."],"src":"https://fr.vikidia.org/wiki/Volcan_Cotopaxi","sw":"v","q":"Q181476","pays":["EC"],"c":["amerique-sud"]},"denali":{"n":"Denali","t":"sommet","massif":"chaîne d'Alaska","bref":["Le mont McKinley (auparavant Denali, de 2015 à 2025) est le point culminant de l'Amérique du Nord (définition comprenant une grande partie du Mexique jusqu'à l'isthme de Tehuantepec). Il se situe aux États-Unis, dans l'État d'Alaska, et a une altitude de 6 190 m (20 310 pieds).","La décision de changer le nom « Denali » en « mont McKinley » a été prise par le président Donald Trump et rendue effective le 24 janvier 2025."],"src":"https://fr.vikidia.org/wiki/Mont_McKinley","sw":"v","q":"Q130018","pays":["US"],"c":["amerique-nord"]},"dhaulagiri":{"n":"Dhaulagiri","t":"sommet","massif":"Himalaya","bref":["Le Dhaulagiri, ou Dhaulagiri I, est un sommet culminant à 8 167 mètres d'altitude au Népal, dans l'Himalaya. Il constitue le septième plus haut sommet du monde. Sa première ascension a été réussie le 13 mai 1960 par Albin Schelbert, Kurt Diemberger, Ernst Forrer, Peter Diener, avec Nawang Dorje et Nima Dorje, aidés d'un avion. Leur itinéraire, par l'arête nord-est, est devenu la voie normale empruntée par la grande majorité des alpinistes."],"src":"https://fr.wikipedia.org/wiki/Dhaulagiri","sw":"w","q":"Q165440","pays":["NP"],"c":["asie"]},"distaghil-sar":{"n":"Distaghil Sar","t":"sommet","massif":"Hispar Muztagh","bref":["Le Distaghil Sar est le dix-neuvième plus haut sommet du monde. Il se situe dans le Nord-Ouest du Karakoram, dans le secteur de l'Hispar Muztagh dont il est le plus haut point."],"src":"https://fr.wikipedia.org/wiki/Distaghil_Sar","sw":"w","q":"Q782496","pays":["PK"],"c":["asie"]},"dolomites":{"n":"Dolomites","t":"sommet","massif":"Préalpes orientales méridionales","bref":["Les Dolomites (en italien : Dolomiti ; en allemand : Dolomiten ; en ladin : Dolomites), anciennement appelées Monti Pallidi (« montagnes pâles »), sont un massif montagneux des Préalpes orientales méridionales réparti de façon à peu près égale entre les régions italiennes du Trentin-Haut-Adige et de la Vénétie.","Territoire aux limites imprécises, les Dolomites correspondent à un ensemble alpin incluant au sens large les Alpes de Fiemme et les Préalpes vicentines. Culminant à 3 343 mètres à la Marmolada, ce massif se caractérise par l'abondance de la dolomie, roche sédimentaire carbonatée auquel leur nom actuel est associé.","Depuis le 26 juin 2009, le site des Dolomites est inscrit au patrimoine mondial de l'UNESCO. Le territoire concerné comprend neuf zones dont certaines ne sont pas situées dans les Dolomites traditionnelles."],"src":"https://fr.wikipedia.org/wiki/Dolomites","sw":"w","q":"Q1283","pays":["IT"],"c":["europe"]},"drakensberg":{"n":"Drakensberg","t":"sommet","massif":"Great Escarpment, Australia","bref":["Le Drakensberg (en afrikaans : Drakensberge, en zoulou : uKhahlamba, en langues sotho-tswana : Maluti) est une chaîne de montagnes en Afrique australe. Situé dans l'Est de l'Afrique du Sud, au Lesotho et en Eswatini, il correspond géographiquement à la partie orientale du Grand Escarpement. Il culmine à 3 482 m d'altitude au Thabana Ntlenyana.","Un parc classé sur la liste du patrimoine mondial protège la faune, la flore et les vestiges archéologiques."],"src":"https://fr.wikipedia.org/wiki/Drakensberg_(cha%C3%AEne_de_montagnes)","sw":"w","q":"Q183295","pays":["ZA","LS"],"c":["afrique"]},"eifel":{"n":"Eifel","t":"sommet","massif":"Massif schisteux rhénan","bref":["L'Eifel est une région de collines à l'ouest de l'Allemagne et à l'est de la Belgique. Il fait partie du massif schisteux rhénan."],"src":"https://fr.vikidia.org/wiki/Eifel","sw":"v","q":"Q152356","pays":["DE"],"c":["europe"]},"eiger":{"n":"Eiger","t":"sommet","massif":"Chaîne Jungfrau-Fiescherhorn","bref":["L’Eiger est un sommet individualisé des Alpes situé en Suisse dans le massif des Alpes bernoises. Son nom, attesté en 1252, ne signifie pas « ogre », contrairement à une idée reçue, mais plus probablement « grand épieu ». La confusion est due aux alpinistes morts lors de la montée de la face nord : celle-ci, presque totalement verticale ou déversante, est considérée comme la plus impressionnante et la plus célèbre face des Alpes, si ce n'est la plus haute. Avec les faces nord du Cervin et des Grandes Jorasses, elle a constitué pour l'alpinisme l'un des « trois derniers problèmes des Alpes », et le dernier résolu.","L'Eiger est traversé par le tunnel d'un chemin de fer à crémaillère de la compagnie de la Jungfraubahn. Il existe une gare dans la paroi de la face nord, appelée Eigerwand, qui permet d'avoir une vue au sein de la face nord."],"src":"https://fr.wikipedia.org/wiki/Eiger","sw":"w","q":"Q4425","pays":["CH"],"c":["europe"]},"el-chichon":{"n":"El Chichón","t":"sommet","massif":"Sierra Madre de Chiapas","bref":["El Chichón est un volcan du Mexique situé à moins d'une vingtaine de kilomètres de la route reliant Villahermosa à Tuxtla Gutiérrez."],"src":"https://fr.wikipedia.org/wiki/El_Chich%C3%B3n","sw":"w","q":"Q841189","pays":["MX"],"c":["amerique-nord"]},"elbourz":{"n":"Elbourz","t":"sommet","bref":["L'Elbourz, en persan البرز ou Alborz, est une chaîne de montagnes située dans le Nord de l'Iran. Son versant septentrional borde la mer Caspienne. La chaîne constitue un arc montagneux de 920 kilomètres de long qui s'étend de la frontière de l'Azerbaïdjan à l'ouest à la région du Khorassan à l'est, en ne dépassant toutefois pas la ville de Machhad. La capitale du pays, Téhéran, se trouve juste au pied de la chaîne, dans une échancrure de sa partie centrale, sur le versant sud."],"src":"https://fr.vikidia.org/wiki/Elbourz","sw":"v","q":"Q484725","pays":["IR"],"c":["asie"]},"elbrouz":{"n":"Elbrouz","t":"sommet","massif":"Bokovoy Range","bref":["Le mont Elbrouz ou mont Elbrous, en russe Зльбрус, est un stratovolcan endormi situé dans le Grand Caucase, dans l'Ouest de la Russie.","De nombreuses légendes tournent autour de cette montagne, comme celle qui raconte que Prométhée y aurait été attaché par Zeus pour le punir d'avoir doté les hommes du feu. Selon cette même légende, son foie serait dévoré chaque jour par un aigle, mais repousserait la nuit."],"src":"https://fr.vikidia.org/wiki/Mont_Elbrouz","sw":"v","q":"Q43105","pays":["RU"],"c":["asie","europe"]},"everest":{"n":"Everest","t":"sommet","massif":"Mahalangur Himal","bref":["Le mont Everest, ou plus simplement l’Everest, aussi appelé Chomolangma Feng (« Déesse mère des neiges » en tibétain) ou Sagarmatha (« Mère de l'Univers » en népalais), est un mont situé au centre de la chaîne de l'Himalaya, entre le Népal et le Tibet (situé en Chine), au sud de l'Asie centrale.","Son sommet est le plus élevé du monde : il y fait si froid que la neige ne fond pas de l'année. Les dernières mesures donnent une hauteur d'environ 8 848 m, mais sont généralement reconnues celles de 1999 : environ 8 850 m. Il fait partie des quatorze sommets de plus de 8 000 m, tous répartis entre l'Himalaya et le Karakoram.","Après de nombreuses tentatives commencées dans les années 1920, son ascension jusqu'au sommet fut finalement réussie en 1953 par le néo-zélandais Edmund Hillary et le sherpa népalais Tensing Norgay. D'autres furent couronnées de succès depuis, mais de tout temps eurent lieu des disparitions dramatiques."],"src":"https://fr.vikidia.org/wiki/Mont_Everest","sw":"v","q":"Q513","pays":["NP","CN"],"c":["asie"]},"galeras":{"n":"Galeras","t":"sommet","massif":"Cordillère Centrale","bref":["Le Galeras, également appelé La Galera ou encore Volcan de Pasto, est un volcan de 4 276 mètres d'altitude de Colombie situé dans le département de Nariño, à l'ouest de sa capitale San Juan de Pasto"],"src":"https://fr.wikipedia.org/wiki/Galeras_(volcan)","sw":"w","q":"Q235062","pays":["CO"],"c":["amerique-sud"]},"gangkhar-puensum":{"n":"Gangkhar Puensum","t":"sommet","massif":"Himalaya","bref":["Le Gangkhar Puensum, Gangkar Punsum ou Gankar Punzum (« les trois frères spirituels »), est une montagne à la frontière entre le Bhoutan et la Chine culminant à 7 570 mètres d'altitude. C'est le point culminant du Bhoutan, et le plus haut sommet vierge du monde."],"src":"https://fr.wikipedia.org/wiki/Gangkhar_Puensum","sw":"w","q":"Q219986","pays":["BT"],"c":["asie"]},"gasherbrum-i":{"n":"Gasherbrum I","t":"sommet","massif":"Gasherbrum","bref":["Le Gasherbrum I, ou Hidden Peak, anciennement K5, est un sommet culminant à 8 080 mètres d'altitude, à la frontière entre la Chine et le Pakistan, dans le Karakoram. Il constitue le onzième plus haut sommet du monde. Sa première ascension a été réussie le 5 juillet 1958 par les Américains Pete Schoening et Andy Kauffman. La voie normale est depuis devenue le couloir des Japonais, grimpé pour la première fois en 1986."],"src":"https://fr.wikipedia.org/wiki/Gasherbrum_I","sw":"w","q":"Q187138","pays":["PK","CN"],"c":["asie"]},"gasherbrum-ii":{"n":"Gasherbrum II","t":"sommet","massif":"Gasherbrum","bref":["Le Gasherbrum II, anciennement K4, est un sommet culminant à 8 035 mètres d'altitude, à la frontière entre la Chine et le Pakistan, dans le Karakoram. Il constitue le treizième plus haut sommet au monde. Sa première ascension a été réussie le 7 juillet 1956 par les Autrichiens Josef Larch, Fritz Moravec et Hans Willenpart. Leur itinéraire, par l'arête sud-ouest puis le final par l'arête est, est devenu la voie normale empruntée par la quasi-totalité des alpinistes, les autres voies étant rarement répétées."],"src":"https://fr.wikipedia.org/wiki/Gasherbrum_II","sw":"w","q":"Q186853","pays":["PK","CN"],"c":["asie"]},"gasherbrum-iii":{"n":"Gasherbrum III","t":"sommet","massif":"Gasherbrum","bref":["Le Gasherbrum III (en ourdou : گاشر برم -3 ; chinois simplifié : 加舒尔布鲁木III峰 ; chinois traditionnel : 加舒爾布魯木III峰 ; pinyin : Jiāshūěrbùlǔmù III Fēng) est le quinzième plus haut sommet du monde. Situé au Pakistan entre le Gasherbrum II et le Gasherbrum IV, il appartient au massif du Gasherbrum situé dans la chaîne du Karakoram. Il fut baptisé K3a (avec le K pour Karakoram) par Thomas George Montgomerie en 1856.","Le Gasherbrum III a été, de 1964 à 1975, le plus haut sommet vierge du monde."],"src":"https://fr.wikipedia.org/wiki/Gasherbrum_III","sw":"w","q":"Q1137636","pays":["CN","PK"],"c":["asie"]},"gasherbrum-iv":{"n":"Gasherbrum IV","t":"sommet","massif":"Gasherbrum","bref":["Le Gasherbrum IV (en ourdou : گاشر برم -4 ; chinois simplifié : 加舒尔布鲁木IV峰 ; chinois traditionnel : 加舒爾布魯木IV峰 ; pinyin : Jiāshūěrbùlǔmù IV Fēng), anciennement K3, est le dix-septième plus haut sommet du monde. Appartenant au massif du Gasherbrum, il est situé à la frontière de la Chine et du Pakistan dans la chaîne du Karakoram."],"src":"https://fr.wikipedia.org/wiki/Gasherbrum_IV","sw":"w","q":"Q834454","pays":["CN","PK"],"c":["asie"]},"gerlachovsky-stit":{"n":"Gerlachovský štít","t":"sommet","massif":"Hautes Tatras","bref":["Le Gerlachovský štít, parfois Gerlach ou pic Gerlach en français, culmine à 2 654 mètres d'altitude ce qui en fait le point culminant de la Slovaquie, de la chaîne des Tatras et de toutes les Carpates. Il était le point culminant de la Hongrie jusqu'à la fin de la Première Guerre mondiale et celui de la Tchécoslovaquie jusqu'en 1992.","Longtemps considéré par erreur comme une montagne de taille moyenne du massif des Hautes Tatras, il a pris une grande importance depuis les mesures par triangulation du début du XIXe siècle qui ont établi sa prédominance au point de changer six fois de nom, dont quatre différents, au cours des XIXe et XXe siècles. D'aspect pyramidal, marqué par un important cirque, il a été gravi pour la première fois en 1834."],"src":"https://fr.wikipedia.org/wiki/Gerlachovsk%C3%BD_%C5%A1t%C3%ADt","sw":"w","q":"Q81213","pays":["SK"],"c":["europe"]},"ghats-occidentaux":{"n":"Ghâts occidentaux","t":"sommet","bref":["Les Ghats occidentaux ou Sahyadrī sont une chaîne de montagnes ; ils bordent le plateau du Deccan dans l'Ouest de l'Inde (à l'opposé des Ghats orientaux), et le séparent de l'étroite plaine côtière des mers d'Arabie et des Laquedives. De par sa richesse naturelle cette région est classée comme un point chaud de biodiversité par Conservation International."],"src":"https://fr.wikipedia.org/wiki/Ghats_occidentaux","sw":"w","q":"Q4527","pays":["IN"],"c":["asie"]},"grand-balkan":{"n":"Grand Balkan","t":"sommet","massif":"Balcanides","bref":["Le Grand Balkan (en bulgare : Стара планина, serbe en écriture cyrillique : Стара планина et serbe en écriture latine : Stara planina, soit « vieille montagne »), est une chaîne de montagnes des Balkans située en Bulgarie et Serbie. Son point culminant est le pic Botev (2 376 m)."],"src":"https://fr.wikipedia.org/wiki/Grand_Balkan","sw":"w","q":"Q170427","pays":["RS","BG"],"c":["europe"]},"grand-caucase":{"n":"Grand Caucase","t":"sommet","massif":"Caucase","bref":["Le Grand Caucase (en géorgien : დიდი კავკასიონი, en russe : Большой Кавказ, en azéri : Böyük Qafqaz Dağları) est une des deux chaînes de montagnes du Caucase. Il est séparé de l'autre chaîne, située plus au sud et appelée Petit Caucase, par la Transcaucasie."],"src":"https://fr.wikipedia.org/wiki/Grand_Caucase","sw":"w","q":"Q486986","pays":["AZ","GE","RU"],"c":["asie","europe"]},"grimsvotn":{"n":"Grímsvötn","t":"sommet","bref":["Le Grímsvötn est un volcan d'Islande situé sous la calotte glaciaire du Vatnajökull, sur les Hautes Terres d'Islande, dans une région éloignée de toute habitation et infrastructure. Il s'agit d'une caldeira n'émergeant du glacier que sous la forme d'un escarpement rocheux et abritant un lac sous-glaciaire, lui aussi appelé Grímsvötn. Le débordement de ce lac, généralement en raison d'éruptions sous-glaciaires, entraîne régulièrement des jökulhlaups, un type d'inondations brutales et dévastatrices. Le Grímsvötn est l'un des volcans les plus actifs d'Islande avec en moyenne une éruption tous les dix ans au cours du XXe siècle."],"src":"https://fr.wikipedia.org/wiki/Gr%C3%ADmsv%C3%B6tn","sw":"w","q":"Q182913","pays":["IS"],"c":["europe"]},"grossglockner":{"n":"Grossglockner","t":"sommet","massif":"Glockner Group","bref":["Le Großglockner ou Grossglockner, souvent abrégé en Glockner, est, avec 3 798 mètres d'altitude, le point culminant de l'Autriche, entre la Carinthie et le Tyrol. Ce pic marqué, en roches appartenant à un faciès à schistes verts, appartient au chaînon du Glockner situé au centre des Hohe Tauern, et est considéré comme le sommet le plus important des Alpes orientales. Depuis les premières reconnaissances au XVIIIe siècle et la première ascension par quatre alpinistes d'une grande expédition organisée par le prince-évêque Salm-Reifferscheidt-Krautheim en 1800, le Großglockner a joué un rôle important dans le développement de l'alpinisme. Il est resté très important pour le tourisme de la région et représente un but apprécié des alpinistes, avec 5 000 ascensions par an."],"src":"https://fr.wikipedia.org/wiki/Gro%C3%9Fglockner","sw":"w","q":"Q3388","pays":["AT"],"c":["europe"]},"gyachung-kang":{"n":"Gyachung Kang","t":"sommet","massif":"Mahalangur Himal","bref":["Le Gyachung Kang est le quinzième plus haut sommet du monde. C'est aussi, avec le Gasherbrum III, le plus haut sommet de moins de 8 000 mètres. Situé dans la région de Khumbu dans l'Himalaya, il est le plus haut sommet entre le Cho Oyu (8 188 mètres) et l'Everest (8 849 mètres)."],"src":"https://fr.wikipedia.org/wiki/Gyachung_Kang","sw":"w","q":"Q582128","pays":["NP","CN"],"c":["asie"]},"harz":{"n":"Harz","t":"sommet","bref":["Le Harz, également en français le Hartz, est à la fois le nom donné à une région, à un district allemand, à un massif montagneux couvrant environ 2 000 km2 au centre-nord de l'Allemagne et à la forêt qui le couvre, parfois considérée comme une relique de la forêt hercynienne décrite par les auteurs antiques et médiévaux, elle-même relique de la forêt primaire européenne.","Le massif du Harz est situé à cheval sur deux régions allemandes et est souvent divisé en deux parties d'aspects différents :","le Haut-Harz (Oberharz) au nord-ouest, en Basse-Saxe, où le massif est d'altitude plus élevée et plus riche en forêts résineuses (épicéas). Le point culminant, le Brocken, a une altitude de 1 141 mètres ;","le Bas-Harz (Unterharz) au sud-est, en Saxe-Anhalt et en Thuringe, au relief plus doux qui descend progressivement vers les terres environnantes avec une forêt tempérée décidue, aux caractéristiques climatiques presque continentales, et mêlée de prés alors qu'on s'approche des vallées et plaines périphériques."],"src":"https://fr.wikipedia.org/wiki/Harz","sw":"w","q":"Q4186","pays":["DE"],"c":["europe"]},"haut-plateau-armenien":{"n":"haut plateau arménien","t":"sommet","massif":"Petit Caucase","bref":["Le haut plateau arménien (en arménien : Հայկական լեռնաշխարհ, Haykakan lernachkharh, en turc Doğu Anadolu yaylaları, anciennement Ermeni Yaylaları) ou plateau d'Arménie est une plaine d'altitude située en Arménie, dans la partie occidentale de l'Azerbaïdjan (enclave du Nakhitchevan), le Sud de la Géorgie, le Nord-Ouest de l'Iran et la partie nord-est de la Turquie. Ce territoire se situe entre 1 000 et 2 000 mètres d'altitude, au milieu des massifs montagneux de Transcaucasie qui relient le Petit Caucase aux monts Taurus."],"src":"https://fr.wikipedia.org/wiki/Haut_plateau_arm%C3%A9nien","sw":"w","q":"Q211263","pays":["AM","GE","TR","IR","AZ"],"c":["asie","europe"]},"hekla":{"n":"Hekla","t":"sommet","bref":["L'Hekla est un volcan situé dans le sud de l'Islande, dans les Hautes Terres, et culmine à 1 488 mètres d'altitude. Il se situe à environ 50 km au nord-est du village de Hvolsvöllur. Il est l'un des volcans les plus actifs d'Islande avec plus de 20 éruptions depuis 874.","C'est l'un des volcans les plus connus d'Islande et également l'un des plus actifs. Il fait partie des stratovolcans basaltiques les plus actifs au monde. Bien qu'il soit assez facile d'accès, son sommet n'est gravi qu'en 1750 par Eggert Ólafson et Bjarni Pálsson, car la croyance locale voulait que ce soit l'entrée des Enfers.","L'Hekla fait partie d'une chaîne volcanique de 40 kilomètres de long. Toutefois, la partie la plus active de cette chaîne, une fissure d'environ 5,5 km de longueur nommée Heklugjá, est considérée comme le volcan Hekla à proprement parler. L'Hekla ressemble à un bateau renversé, dont la quille serait en fait une série de cratères, dont deux sont généralement les plus actifs. La base du volcan mesure douze kilomètres de longueur pour neuf kilomètres de largeur. Ce stratovolcan s'élève à 1 000 mètres au-dessus des terrains environnants."],"src":"https://fr.wikipedia.org/wiki/Hekla","sw":"w","q":"Q184975","pays":["IS"],"c":["europe"]},"himalaya":{"n":"Himalaya","t":"sommet","bref":["L'Himalaya, qui s'étend en Asie sur le Pakistan, l'Inde, le Népal, la Chine (Tibet) et le Bhoutan, est l'ensemble montagneux le plus haut du monde : son altitude moyenne est de plus de 4 000 m. Son point culminant, l'Everest (8 848 m), est par ailleurs le plus haut sommet du monde ; et dix des quatorze plus hauts sommets du monde — surnommés « les 8000 » — sont himalayens. Parmi eux le Kangchenjunga, deuxième sommet de l'Himalaya et point culminant de l'Inde. Les quatre autres se situent dans la chaîne du Karakoram. Aux extrémités de la chaîne, on trouve à l'ouest le Nanga Parbat et â l'est le Namcha Barwa.","L'Himalaya est également l'un des principaux « châteaux d'eau » du continent asiatique et de nombreux fleuves y prennent leur source : le Gange, le Brahmapoutre, le Mékong, le Chang Jiang, le Huang He…"],"src":"https://fr.vikidia.org/wiki/Himalaya","sw":"v","q":"Q5451","pays":["NP","MM","CN","PK","IN","AF","BT"],"c":["asie"]},"himalchuli":{"n":"Himalchuli","t":"sommet","massif":"Mansiri Himal","bref":["L'Himalchuli, qui culmine à 7 893 m, est le dix-huitième plus haut sommet du monde. Il est situé au Népal dans la chaîne de l'Himalaya, dans le Mansiri Himal, non loin du Manaslu."],"src":"https://fr.wikipedia.org/wiki/Himalchuli","sw":"w","q":"Q1145646","pays":["NP"],"c":["asie"]},"hindou-kouch":{"n":"Hindou Kouch","t":"sommet","bref":["L'Hindou Kouch (en pachto et en persan : هندوكش ; en hindi : हिन्दु कुश) est une chaîne de hautes montagnes en Afghanistan et au Pakistan. Il est le prolongement occidental de la chaîne de l'Himalaya."],"src":"https://fr.wikipedia.org/wiki/Hindou_Kouch","sw":"w","q":"Q5472","pays":["AF","PK"],"c":["asie"]},"hoggar":{"n":"Hoggar","t":"sommet","bref":["Le Hoggar (ou Ahaggar) est un massif montagneux du Sud-Est de l'Algérie dans le désert du Sahara. Le Hoggar culmine au Tahat à 2 918 m d'altitude (qui est aussi le point culminant de l'Algérie). Le Hoggar a environ 3 800 km2 de superficie.","Le massif est formé de plateaux étagés composés de granites et de gneiss. La partie centrale (Koudiat) est un massif volcanique, avec du basalte et du porphyre très démantelé par l'érosion et présente de nombreux pitons rocheux.","Du fait de son altitude le Hoggar est un peu moins sec que les régions environnantes."],"src":"https://fr.vikidia.org/wiki/Hoggar","sw":"v","q":"Q26399","pays":["DZ"],"c":["afrique"]},"hoverla":{"n":"Hoverla","t":"sommet","massif":"Chornohora","bref":["Le mont Hoverla (en ukrainien : Говерла, Hoverla, en roumain : Hovârla, en russe : Говерла, Goverla, en tchèque et en slovaque : Hoverla, en polonais : Howerla, en hongrois : Hóvár), avec 2 061 m, est la montagne la plus haute d'Ukraine. Il est situé dans les Carpates orientales, dans la région appelée Tchornohora (littéralement « montagne noire » en français). Ses pentes sont recouvertes de forêts de hêtres et d'épicéas, au-dessus desquelles se trouve l'étage des prairies subalpines, appelées polonyna en polonais et ukrainien. Sur son versant est se trouve la source principale de la rivière Prout."],"src":"https://fr.wikipedia.org/wiki/Hoverla","sw":"w","q":"Q627508","pays":["UA"],"c":["europe"]},"ile-amsterdam":{"n":"île Amsterdam","t":"sommet","bref":["L'île Amsterdam, appelée île de la Nouvelle-Amsterdam jusqu'en 1965, est une petite île française subantarctique située dans le sud de l'océan Indien, à 1 368 km au nord-nord-est des îles Kerguelen et à 2 713 km au sud-est de l'île Maurice. Elle forme avec l'île Saint-Paul, distante de 91 km plus au sud, le district des îles Saint-Paul et Amsterdam, l'un des cinq districts des Terres australes et antarctiques françaises (les quatre autres sont l'archipel Crozet, les îles Kerguelen, la terre Adélie et les îles Éparses). Elle est souvent considérée comme l'une des îles les plus isolées au monde, ce qui en fait un site d'observations atmosphériques de référence mondiale, connu notamment pour les mesures de gaz à effet de serre et autres polluants atmosphériques, où les concentrations parmi les plus basses de la planète sont enregistrées."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Amsterdam","sw":"w","q":"Q194215","pays":["FR"],"c":["europe"]},"ile-atlassov":{"n":"île Atlassov","t":"sommet","bref":["L'île Atlassov (en russe : Остров Атласова, en japonais : 阿頼度島, Araido) est une île volcanique, la plus septentrionale des îles Kouriles, dans l'oblast de Sakhaline, à l'est de la Russie. L'île figure parfois sous les noms d'Ouïakhoujatch, d'Oyakoba et d'Alaïd.","L'île porte le nom de Vladimir Atlassov, un explorateur russe du XVIIe siècle qui la rattacha à la péninsule voisine du Kamtchatka. L'île est essentiellement le cône d'un volcan sous-marin appelé Alaïd qui dépasse de la mer d'Okhotsk et culmine à une altitude de 2 339 m (point culminant des îles Kouriles). L'île a une superficie de 119 km2. Elle est actuellement inhabitée. Le volcan alterne avec les périodes actives, et les périodes calmes de repos, ce qui fait que l'île est potentiellement dangereuse à être habitée. L'île possède quelques sources d'eau chaude, non exploitées. Avec la teneur en soufre de la terre, la végétation est constituée de plantes basses, et de seulement quelques arbres."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Atlassov","sw":"w","q":"Q757314","pays":["RU"],"c":["asie","europe"]},"ile-floreana":{"n":"île Floreana","t":"sommet","bref":["L'île Floreana, en espagnol Isla Floreana, aussi appelée île Santa María, en espagnol Isla Santa María, ou encore île Charles, est une île d'Équateur située dans les îles Galápagos."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Floreana","sw":"w","q":"Q1048209","pays":["EC"],"c":["amerique-sud"]},"ile-saint-paul":{"n":"île Saint-Paul","t":"sommet","bref":["L'île Saint-Paul est une île française située dans le Sud de l'océan Indien, à 1 280 km au nord-nord-est des îles Kerguelen. Elle forme avec l'île Amsterdam, 91 km plus au nord, le district des îles Saint-Paul et Amsterdam, l'un des cinq districts des Terres australes et antarctiques françaises (les quatre autres sont les îles Crozet, les îles Kerguelen, la terre Adélie et les îles Éparses)."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Saint-Paul_(oc%C3%A9an_Indien)","sw":"w","q":"Q204821","pays":["FR"],"c":["europe"]},"iles-hanish":{"n":"îles Hanish","t":"sommet","bref":["Les îles Hanish (en arabe : جزر هانيش) sont un archipel du Yémen et d'Érythrée, baigné par la mer Rouge."],"src":"https://fr.wikipedia.org/wiki/%C3%8Eles_Hanish","sw":"w","q":"Q1417843","pays":["YE"],"c":["asie"]},"irazu":{"n":"Irazú","t":"sommet","massif":"cordillère Centrale","bref":["L'Irazú est un stratovolcan actif situé dans la cordillère Centrale (Cordillera Volcánica Central), au Costa Rica. Il culmine à 3 432 mètres d'altitude. Le cratère héberge un lac acide, qui s'est lentement évaporé en avril 2013 à la suite de la reprise de l'activité volcanique.","Il se trouve à l'intérieur du parc national qui porte son nom, le parc national du Volcán Irazú, à environ trente kilomètres à l'ouest de la ville de Cartago.","Les volcans Turrialba et Irazú sont parfois qualifiés de jumeaux car ils prennent appui sur le même socle."],"src":"https://fr.wikipedia.org/wiki/Iraz%C3%BA","sw":"w","q":"Q1672472","pays":["CR"],"c":["amerique-nord"]},"jungfrau":{"n":"Jungfrau","t":"sommet","massif":"Chaîne Jungfrau-Fiescherhorn","bref":["La Jungfrau (/ˈjʊŋfʁaʊ̯/) est un sommet individualisé des Alpes situé en Suisse dans le massif des Alpes bernoises. Il culmine à 4 158 mètres d'altitude."],"src":"https://fr.wikipedia.org/wiki/Jungfrau","sw":"w","q":"Q15312","pays":["CH"],"c":["europe"]},"k2":{"n":"K2","t":"sommet","massif":"Baltoro Muztagh","bref":["Le K2, en chinois Qogir Feng, est le point culminant de la chaîne du Karakoram. Il s'élève à 8 611 m d'altitude. La montagne fut longtemps appelée « mont Godwin-Austen », du nom d'un topographe et géographe britannique, mais celui-ci nom ne fut jamais rendu officiel. Ce toponyme apparut pourtant sur de nombreuses cartes. Aujourd'hui, un glacier proche du K2 rend hommage à cet expert-géographe."],"src":"https://fr.vikidia.org/wiki/K2","sw":"v","q":"Q43512","pays":["PK"],"c":["asie"]},"kamet":{"n":"Kamet","t":"sommet","massif":"Garhwal Himalayas","bref":["Le Kamet est par son élévation le deuxième sommet du Garhwal, derrière la Nanda Devi (7 816 m), en Inde. Il a été la première montagne de l'Himalaya de plus de 25 000 pieds (7 620 m) à être gravie.","Plus haut sommet gravi à l'époque de sa conquête (1931), et ce jusqu'à l'ascension du Nanda Devi en 1936, le Kamet fut l'une des montagnes les plus fréquentées par les grimpeurs aux débuts de l'exploration himalayenne ; le nombre de tentatives infructueuses entreprises à partir de 1855 en témoigne."],"src":"https://fr.wikipedia.org/wiki/Kamet","sw":"w","q":"Q1141272","pays":["IN"],"c":["asie"]},"kangchenjunga":{"n":"Kangchenjunga","t":"sommet","massif":"Himalaya","bref":["Le Kangchenjunga (ou Kanchenjunga ) est avec 8 586 mètres d'altitude le point culminant de l'Inde, le deuxième sommet de l'Himalaya et le troisième du monde. Sa proéminence est de 3 922 mètres, mesure qui classe la montagne ving-neuvième du monde pour cette spécialité . Au Tibet, il est nommé Sewalungma en limbou, une langue tibéto-birmane."],"src":"https://fr.vikidia.org/wiki/Kangchenjunga","sw":"v","q":"Q82019","pays":["IN","NP"],"c":["asie"]},"karakoram":{"n":"Karakoram","t":"sommet","bref":["Le Karakoram ou Karakorum est une chaîne de montagnes se trouvant dans la région montagneuse du Gilgit-Baltistan, dans le Nord du Pakistan, du Nord de l’Inde et de l'Ouest de la Chine."],"src":"https://fr.wikipedia.org/wiki/Karakoram","sw":"w","q":"Q5469","pays":["CN","TJ","IN","AF","PK"],"c":["asie"]},"katla":{"n":"Katla","t":"sommet","bref":["Le Katla est un volcan d'Islande recouvert par le Mýrdalsjökull, une calotte glaciaire du Sud du pays. Il est situé à l'est de l'Eyjafjöll, un autre volcan considéré comme lié au Katla. Il s'agit d'un des volcans les plus actifs et des plus destructeurs d'Islande, à l'origine de plusieurs jökulhlaups."],"src":"https://fr.wikipedia.org/wiki/Katla","sw":"w","q":"Q201914","pays":["IS"],"c":["europe"]},"kebnekaise":{"n":"Kebnekaise","t":"sommet","massif":"Alpes scandinaves","bref":["Le Kebnekaise, en same Giebmegáisi ou Giebnegáisi, littéralement « rebord du chaudron », est un sommet de Suède, point culminant du pays avec 2 097 mètres d'altitude. Bien que situé dans une région reculée dans le nord du pays, il constitue un but de randonnée populaire."],"src":"https://fr.wikipedia.org/wiki/Kebnekaise","sw":"w","q":"Q214011","pays":["SE"],"c":["europe"]},"kelimutu":{"n":"Kelimutu","t":"sommet","bref":["Le Kelimutu est un volcan au centre de l'île de Florès dans le Sud de l’Indonésie."],"src":"https://fr.wikipedia.org/wiki/Kelimutu","sw":"w","q":"Q1738211","pays":["ID"],"c":["asie"]},"kelud":{"n":"Kelud","t":"sommet","bref":["Le volcan Kelud est un stratovolcan actif situé dans l'Est de l'île de Java, en Indonésie. Haut de 1 731 mètres, il est proche de plusieurs villes importantes, Blitar, Kediri et Malang, ce qui en fait l'un des plus dangereux au monde."],"src":"https://fr.wikipedia.org/wiki/Kelud","sw":"w","q":"Q513216","pays":["ID"],"c":["asie"]},"khan-tengri":{"n":"Khan Tengri","t":"sommet","massif":"Tengritau","bref":["Le Khan Tengri est une montagne qui s'élève à 7 010 mètres d'altitude dans la chaîne du Tian Shan. Ce sommet est le point culminant du Kazakhstan, à la frontière avec le Kirghizistan dont il est le troisième plus haut sommet, et très proche du Xinjiang en Chine. Il est gravi pour la première fois en 1931 par Mikhail Pogrebetsky. Sommet particulièrement dangereux, son ascension est principalement tentée par des alpinistes russes et kazakhs."],"src":"https://fr.wikipedia.org/wiki/Khan_Tengri","sw":"w","q":"Q211529","pays":["KG","KZ","CN"],"c":["asie","europe"]},"klioutchevskoi":{"n":"Klioutchevskoï","t":"sommet","massif":"Groupe volcanique du Klioutchevskoï","bref":["Le Klioutchevskoï ou Klioutchevskaïa Sopka est un volcan actif situé en Russie, dans le centre du Kamtchatka. Administrativement, il fait partie du kraï du Kamtchatka, situé dans l'Extrême-Orient russe. Il se trouve à 84 kilomètres à l'ouest-nord-ouest des rives de l'océan Pacifique les plus proches et à 358 kilomètres au nord-nord-est de Petropavlovsk-Kamtchatski, la capitale du kraï.","La première ascension fut réalisée en 1788 par Daniel Gauss et deux membres de l'expédition Billings."],"src":"https://fr.vikidia.org/wiki/Klioutchevsko%C3%AF","sw":"v","q":"Q210252","pays":["RU"],"c":["asie","europe"]},"koriakski":{"n":"Koriakski","t":"sommet","massif":"chaîne Centrale","bref":["Le Koriakski, appelé également la Koriaka , Koriakskaïa sopka, Strelochnaïa sopka ou encore Strelochnaïa, en russe Корякская сопка, est un volcan actif de Russie situé dans le sud de la péninsule du Kamtchatka, dans le kraï de même nom."],"src":"https://fr.wikipedia.org/wiki/Koriakski","sw":"w","q":"Q839630","pays":["RU"],"c":["asie","europe"]},"krafla":{"n":"Krafla","t":"sommet","bref":["Le Krafla est un système volcanique dans la région du Mývatn au Nord de l'Islande. Il comprend un volcan central caractérisé par une caldeira d'une dizaine de kilomètres de large, et un champ de fissures orientées nord-sud sur une centaine de kilomètres depuis le volcan tabulaire Selfjall au sud à la mer au nord. Il est installé à l'emplacement d'une ride palagonitique qui culmine à 818 m d'altitude. Ses éruptions ont façonné la topographie des environs du Mývatn."],"src":"https://fr.wikipedia.org/wiki/Krafla","sw":"w","q":"Q752994","pays":["IS"],"c":["europe"]},"lhotse":{"n":"Lhotse","t":"sommet","massif":"Mahalangur Himal","bref":["Le Lhotse est un sommet culminant à 8 516 mètres d'altitude, à la frontière entre la Chine et le Népal, dans l'Himalaya. Il constitue par son éĺévation le quatrième sommet du monde. Sa première ascension a été réussie le 18 mai 1956 par les Suisses Fritz Luchsinger et Ernst Reiss. Leur itinéraire, par le versant nord-ouest, est devenu la voie normale empruntée par la quasi-totalité des alpinistes, les autres voies n'étant pas répétées."],"src":"https://fr.wikipedia.org/wiki/Lhotse","sw":"w","q":"Q168702","pays":["NP","CN"],"c":["asie"]},"llullaillaco":{"n":"Llullaillaco","t":"sommet","massif":"cordillère des Andes","bref":["Le Llullaillaco ou Llullay-Yacu est par son élévation le deuxième volcan actif au monde, après l'Ojos del Salado et constitue le site archéologique le plus haut du monde. Le volcan se trouve dans les Andes à la frontière entre l'Argentine (dans la province de Salta) et le Chili (dans la région d'Antofagasta)."],"src":"https://fr.wikipedia.org/wiki/Llullaillaco","sw":"w","q":"Q214916","pays":["AR","CL"],"c":["amerique-sud"]},"makalu":{"n":"Makalu","t":"sommet","massif":"Mahalangur Himal","bref":["Le Makalu (népalais : मकालु ; chinois : 马卡鲁山, en pinyin : Mǎkǎlǔ Shān ; limbu : Makalungma) est un sommet culminant à 8 485 mètres d'altitude, à la frontière entre le Tibet, en Chine, et le Népal, dans l'Himalaya. Il constitue par son élévation le cinquième sommet du monde. Sa première ascension a été réussie le 15 mai 1955, deux ans après celle de l'Everest situé à moins de vingt kilomètres, par les Français Lionel Terray et Jean Couzy. Ses versants nord et sud font respectivement partie de la réserve naturelle du Qomolangma et du parc national de Makalu Barun."],"src":"https://fr.wikipedia.org/wiki/Makalu","sw":"w","q":"Q169986","pays":["NP","CN"],"c":["asie"]},"manaslu":{"n":"Manaslu","t":"sommet","massif":"Mansiri Himal","bref":["Le Manaslu (népalais : मनास्लु) est une montagne située au Népal, dans la chaîne de l'Himalaya. Avec une altitude de 8 163 mètres, il est le huitième sommet le plus haut du monde.","Les Britanniques le représentent sur les cartes au milieu du XIXe siècle puis, à la suite de l'ouverture des frontières du Népal en 1950, ce sont les premiers à évaluer les difficultés de son relief pyramidal. Toutefois, le Japon lance cinq expéditions consécutives au cours de cette décennie et, le 9 mai 1956, Toshio Imanishi et le sherpa Gyalzen Norbu parviennent à atteindre son sommet par le versant nord-est, suivis de deux de leurs équipiers deux jours plus tard. Aucune autre expédition n'est lancée avant les années 1970. En 1971, une nouvelle expédition japonaise ouvre une voie le long de l'arête occidentale."],"src":"https://fr.wikipedia.org/wiki/Manaslu","sw":"w","q":"Q170070","pays":["NP"],"c":["asie"]},"masherbrum":{"n":"Masherbrum","t":"sommet","massif":"monts Masherbrum","bref":["Le Masherbrum, également appelé K1, est un sommet du Pakistan situé dans le Karakoram."],"src":"https://fr.wikipedia.org/wiki/Masherbrum","sw":"w","q":"Q854295","pays":["PK"],"c":["asie"]},"massif-central":{"n":"Massif central","t":"sommet","bref":["Le Massif central est un massif montagneux au centre de la France. Il s'agit des restes érodés d'une très ancienne chaîne de montagnes, abritant principalement des roches granitiques, sur lesquelles on trouve les traces d'une grande chaîne de volcans, aujourd'hui éteints.","Au sud, on trouve d'immenses plateaux calcaires : les Grands Causses. Le point culminant est le puy de Sancy (1 886 m), qui est un volcan. Par sa position centrale, les pluies et l'enneigement une partie de l'année, il donne naissance à de nombreuses rivières qui alimentent la Seine, la Loire, le Rhône, la Garonne et la Dordogne. On le surnomme le « château d'eau » de la France.","Le Massif central occupe une position centrale et un rôle de carrefour, en France et au sein de l'Europe : au cours de son histoire, il a servi de point de repère et de frontière, et a souvent été divisé entre plusieurs pays, ou provinces. Il en résulte l'existence de régions très différentes et diversifiées au sein du Massif central, tant du point de vue de l'histoire que de la culture."],"src":"https://fr.vikidia.org/wiki/Massif_central","sw":"v","q":"Q190695","pays":["FR"],"c":["europe"]},"massif-des-vosges":{"n":"massif des Vosges","t":"sommet","bref":["Le massif des Vosges (ou les Vosges) est un ensemble montagneux d'altitude moyenne et de formes arrondies (les ballons) de l'est de la France. Le point culminant des Vosges est le Grand Ballon, dit aussi ballon de Guebwiller. Son altitude est de 1 424 mètres. Les Vosges isolent le plateau lorrain de la plaine d'Alsace."],"src":"https://fr.vikidia.org/wiki/Massif_des_Vosges","sw":"v","q":"Q187843","pays":["FR"],"c":["europe"]},"massif-vinson":{"n":"massif Vinson","t":"sommet","massif":"massif Sentinel","bref":["Le massif Vinson est un massif de l'Antarctique occidental, situé dans la chaîne Sentinel, elle-même constituant une partie d'un plus grand ensemble, les monts Ellsworth. Le point le plus élevé du massif, désigné sous le nom de « mont Vinson », culmine à 4 892 mètres d'altitude. Il est le plus haut sommet du continent Antarctique, îles comprises."],"src":"https://fr.vikidia.org/wiki/Massif_Vinson","sw":"v","q":"Q163758"},"mauna-kea":{"n":"Mauna Kea","t":"sommet","massif":"chaîne sous-marine Hawaï-Empereur","bref":["Le Mauna Kea est un volcan endormi situé dans l'océan Pacifique, dans la moitié nord de l'île d'Hawaï, dans l'archipel américain de même nom. Il est l'un des cinq volcans de Hawaï, avec le Kohala, le Huhalalai, le Mauna Loa et le Kilauea.","Le volcan atteint 4 205 mètres d'altitude au Pu'u Wekiu, la plus haute cîme de l'île. Cette élévation permet à Hawaï d'obtenir le sixième rang dans le classement des plus hauts États de l'union américaine. Le sommet fut gravi pour la première fois en 1823 par un missionnaire américain , Joseph F. Goodrich."],"src":"https://fr.vikidia.org/wiki/Mauna_Kea","sw":"v","q":"Q131230","pays":["US"],"c":["amerique-nord"]},"mayon":{"n":"Mayon","t":"sommet","bref":["Le Mayon est un volcan actif des Philippines, sur l'île de Luçon, dans la province d'Albay, entre les villes de Legazpi au sud-est, Tabaco au nord-est et Ligao à l'ouest."],"src":"https://fr.wikipedia.org/wiki/Mayon","sw":"w","q":"Q1484","pays":["PH"],"c":["asie"]},"mehetia":{"n":"Mehetia","t":"sommet","bref":["Mehetia ou Me’eti’a ou encore Meetia, est une île volcanique située dans les îles du Vent, sous-ensemble insulaire dépendant des îles de la Société, en Polynésie française. Autrefois occupée de façon permanente, car située au centre des échanges commerciaux entre Tahiti et les îles Tuamotu, l'île est aujourd'hui inhabitée et son accès est réglementé."],"src":"https://fr.wikipedia.org/wiki/Mehetia","sw":"w","q":"Q1340711","pays":["FR"],"c":["europe"]},"momotombo":{"n":"Momotombo","t":"sommet","massif":"Cordillère des Maribios","bref":["Le Momotombo est un volcan de type stratovolcan situé à proximité de la ville de León au Nicaragua sur la rive du lac de Managua. Il s'élève à 1 297 mètres d'altitude. C'est un volcan relativement jeune d'environ 4 500 ans aux éruptions stromboliennes."],"src":"https://fr.wikipedia.org/wiki/Momotombo","sw":"w","q":"Q575891","pays":["NI"],"c":["amerique-nord"]},"mont-apo":{"n":"mont Apo","t":"sommet","massif":"Apo–Talomo Range","bref":["Le mont Apo est le point culminant des Philippines, avec 2954 mètres de hauteur. C'est un volcan situé sur l'île de Mindanao, à une trentaine de kilomètres de la plus grande ville, Davao.","La première personne qui l’a gravi a été Don Joaquin Rajal, en 1880. Le mont Apo est une destination très touristique car on y monte assez facilement, contrairement aux autres grandes montagnes du pays.","En mai 1936, le mont Apo est devenu un parc national. En effet, la faune y est très variée, on peut y voir 270 espèces d'oiseaux différentes."],"src":"https://fr.vikidia.org/wiki/Mont_Apo","sw":"v","q":"Q455963","pays":["PH"],"c":["asie"]},"mont-arafat":{"n":"mont Arafat","t":"sommet","massif":"monts Sarawat","bref":["Le mont Arafat (parfois appelé mont Arafah) (arabe : جبل عرفات ; Jabal 'Arafât) est une colline de granite située à une vingtaine de kilomètres à l'est de La Mecque ; elle atteint environ 70 mètres de hauteur. On le connaît également sous le nom de Jabal ar-Raḥma ou « montagne de la miséricorde ».","Cette colline est l'endroit où Mahomet aurait donné son sermon d'adieu aux musulmans qui l'avaient accompagné pour le hajj (pèlerinage) à la fin de sa vie. Les musulmans croient qu'Adam et sa femme Ève ont été réunis sur cette colline et qu'ils y ont reçu le pardon de Dieu après 200 ans de séparation due à leur désobéissance et à leur incapacité de résister à l'appel d'Iblis (Satan). ) Lorsque vous déferlez d'Arafat, invoquez Dieu auprès du monument sacré ; invoquez-le, puisqu'il vous a dirigés, alors que vous étiez, auparavant, au nombre des égarés."],"src":"https://fr.wikipedia.org/wiki/Mont_Arafat","sw":"w","q":"Q216894","pays":["SA"],"c":["asie"]},"mont-ararat":{"n":"mont Ararat","t":"sommet","massif":"haut plateau arménien","bref":["Le mont Ararat (en turc : Ağrı Dağı, en arménien : Արարատ), est le point culminant de la Turquie, situé dans le haut plateau arménien, dans l'extrême-est du pays. Il est constitué de deux sommets, le grand Ararat (qui désigne le mont Ararat, 5 137 mètres) et le petit Ararat (3 896 mètres), le plus grand constituant un glacier volcanique","C'est un volcan actif et sa dernière éruption a eu lieu en 1840. Il est situé près des frontières iranienne et arménienne, respectivement à une dizaine et une quarantaine de kilomètres de distance.","Le sommet est perçu en Arménie comme un lieu sacré, de par son association à l'arche de Noé qui d'après la Bible (Genèse, VIII, 4) s'y échoua après le Déluge . Il est représenté dans les armoiries du pays."],"src":"https://fr.vikidia.org/wiki/Mont_Ararat","sw":"v","q":"Q72303","pays":["TR"],"c":["asie","europe"]},"mont-athos":{"n":"mont Athos","t":"sommet","bref":["Le mont Athos (en grec moderne Άγιοv Όρος / Ágion Óros, la « Sainte Montagne ») est une péninsule montagneuse située à l'est de la Chalcidique, dans le nord de la Grèce.","Du point de vue administratif, la « Sainte Montagne » constitue un nome de la République de Grèce qui porte le nom de République monastique du mont Athos, formant une communauté théocratique rattachée au Patriarcat œcuménique de Constantinople, disposant d'un statut particulier où les lois sont différentes de celles appliquées sur l'ensemble du territoire grec.","La péninsule compte vingt monastères orthodoxes établis depuis le Xe siècle?, où vivent plus de 2 000 moines, pour la plupart grecs ou russes. Certains de ces moines vivent dans des villages tout autour de ces monastères."],"src":"https://fr.vikidia.org/wiki/Mont_Athos","sw":"v","q":"Q130321","pays":["GR"],"c":["europe"]},"mont-blanc":{"n":"mont Blanc","t":"sommet","massif":"massif du Mont-Blanc","bref":["Le mont Blanc est le point culminant (le sommet le plus haut) des Alpes et de l'Europe de l'Ouest, ainsi que le sixième d'Europe (derrière les sommets du Caucase). Il se situe en France, dans le massif du Mont-Blanc, à 4 808 mètres d'altitude, dans le département de la Haute-Savoie. Il domine au nord la vallée de l'Arve et au sud-est la vallée du Fiume Dora di Veny. Chamonix-Mont-Blanc se trouve à 10 kilomètres au nord du point le plus haut. Ce sommet est le plus isolé d'Eurasie et donc d'Europe. Le mont le plus proche dépassant le mont Blanc en altitude est le Kukurtlu Dome, situé à 2 866 kilomètres dans le Grand Caucase, non loin du mont Elbrouz. Sa proéminence est tout aussi impressionnante : 4 694 mètres, soit la première de la chaîne des Alpes, la onzième du monde et la troisième d'Eurasie derrière celles du mont Everest (Népal/Chine, premier) et du mont Elbrouz (Russie, deuxième)."],"src":"https://fr.vikidia.org/wiki/Mont_Blanc","sw":"v","q":"Q583","pays":["FR","IT"],"c":["europe"]},"mont-cameroun":{"n":"mont Cameroun","t":"sommet","massif":"ligne du Cameroun","bref":["Le mont Cameroun est un volcan du Cameroun, point culminant du pays à 4 040 ou 4 095 mètres d'altitude au Fako, le point le plus élevé du cratère sommital. Il fait partie d'une suite volcanique, la ligne du Cameroun. Il se situe à 68 kilomètres à l'ouest-nord-ouest de Douala."],"src":"https://fr.vikidia.org/wiki/Mont_Cameroun","sw":"v","q":"Q190562","pays":["CM"],"c":["afrique"]},"mont-damavand":{"n":"mont Damavand","t":"sommet","massif":"Elbourz","bref":["Le mont Damavand est le point culminant des monts Elbourz (ou Alborz), en Iran. Il se situe dans le Nord de l'Iran, dans la partie orientale de la chaîne et à 68 kilomètres à l'est-nord-est de Téhéran. Il est aussi un volcan éteint."],"src":"https://fr.vikidia.org/wiki/Mont_Damavand","sw":"v","q":"Q40758","pays":["IR"],"c":["asie"]},"mont-des-oliviers":{"n":"mont des Oliviers","t":"sommet","massif":"Mount of Olives ridge","bref":["Le mont des Oliviers (הר הזיתים en hébreu, جبل الزيتون en arabe) est une colline à l'est de Jérusalem ; il englobe en fait les deux collines situées immédiatement au nord de celle-ci. Le lieu est important pour les trois religions abrahamiques."],"src":"https://fr.wikipedia.org/wiki/Mont_des_Oliviers","sw":"w","q":"Q205976","pays":["IL"],"c":["asie"]},"mont-du-pain-de-sucre":{"n":"mont du Pain de Sucre","t":"sommet","bref":["Le Pain de Sucre (en portugais : Pão de Açúcar) est une montagne du Brésil de 345 m de hauteur. Elle est située à Rio de Janeiro.","La colline est constituée d'un seul bloc de granite, âgé d'au moins six cent millions d'années, issu de la séparation entre les continents sud-américain et africain et à la compression des roches qui s'ensuivit.","Son nom lui a été donné dès le XVIe siècle? par les Portugais, à qui il rappelait la forme du sucre de canne moulé tel qu'il était vendu habituellement, enveloppé d'une feuille de papier.","La face sud du Pain de Sucre est connue des botanistes pour sa très grande variété d'espèces tropicales, dont beaucoup d'orchidées et de broméliacées.","Un téléphérique conduit les touristes au sommet. Les sportifs peuvent l'atteindre à pied par un sentier."],"src":"https://fr.vikidia.org/wiki/Pain_de_Sucre","sw":"v","q":"Q210722","pays":["BR"],"c":["amerique-sud"]},"mont-emei":{"n":"mont Emei","t":"sommet","bref":["Le mont Emei (chinois simplifié : 峨嵋山 ; chinois traditionnel : 峨眉山 ; pinyin : éméishān) ou Omei, ou Emei Shan, est l'une des quatre montagnes sacrées bouddhiques de Chine, située sur le territoire de la ville d'Emeishan dans la province du Sichuan."],"src":"https://fr.wikipedia.org/wiki/Mont_Emei","sw":"w","q":"Q134927","pays":["CN"],"c":["asie"]},"mont-erciyes":{"n":"mont Erciyes","t":"sommet","massif":"monts Taurus","bref":["Le mont Erciyes, ou mont Argée (Ardjéh dagh) est un volcan endormi du Miocène, situé à 25 km au sud de Kayseri, en Turquie.","Le mont Erciyes est le point culminant d'Anatolie centrale (3 916 mètres). Il appartient à la région volcanique qui s'étend au nord du Taurus cilicien et à l’ouest de l’Anti-Taurus."],"src":"https://fr.wikipedia.org/wiki/Mont_Erciyes","sw":"w","q":"Q126804","pays":["TR"],"c":["asie","europe"]},"mont-erebus":{"n":"mont Erebus","t":"sommet","massif":"chaîne Transantarctique","bref":["Le mont Erebus est un volcan d'Antarctique. Situé sur l'île de Ross, il est le plus austral des volcans actifs du monde. Proche du continent, l'île de Ross appartient à l'océan Pacifique Sud et se trouve à 3 485 kilomètres au sud de l'île du Sud, en Nouvelle-Zélande."],"src":"https://fr.vikidia.org/wiki/Mont_Erebus","sw":"v","q":"Q188982"},"mont-fuji":{"n":"mont Fuji","t":"sommet","bref":["Le mont Fuji (en japonais : 富士山, fujisan), est un volcan japonais de type stratovolcan. C'est la montagne la plus haute du Japon avec une altitude de 3 776 m. Ses pentes sud descendent jusqu’aux rivages de la mer dans la baie de Suruga. Sa dernière éruption date de l'an 1707. Son activité a augmenté ces dernières années, une éruption serait catastrophique car la région est très peuplée ( avec Tokyo 40 millions d'habitants ). Un séisme pourrait réveiller ce volcan très dangereux, comme en 1707 selon certains, dans le Japon qui a subi plein de séismes et catastrophes, Typhons, inondations, tsunamis Raz-de-marée."],"src":"https://fr.vikidia.org/wiki/Mont_Fuji","sw":"v","q":"Q39231","pays":["JP"],"c":["asie"]},"mont-hasan":{"n":"mont Hasan","t":"sommet","massif":"monts Taurus","bref":["Le mont Hasan (turc : Hasan Dağı) est un volcan situé dans les provinces de Niğde et Aksaray, en Turquie.","C'est un stratovolcan actif, qui a connu deux éruptions durant l'Holocène et présente actuellement une activité fumerollienne à son sommet. Malgré ses dangers potentiels, il ne fait l'objet d'aucune surveillance."],"src":"https://fr.wikipedia.org/wiki/Mont_Hasan","sw":"w","q":"Q1302768","pays":["TR"],"c":["asie","europe"]},"mont-hermon":{"n":"mont Hermon","t":"sommet","massif":"Anti-Liban","bref":["Le mont Hermon (appelé en hébreu : הר חרמון, Har Hermon ; et en arabe : جبل الشيخ, Jabal ash-Shaykh, soit « montagne du cheikh » ou « mont enneigé » ou Haramoun) est une montagne de l'Anti-Liban, culminant à 2 814 mètres d'altitude. Le sommet se situe à la frontière entre la Syrie et le Liban. L'extrémité méridionale de la montagne fait partie du plateau du Golan, occupé, colonisé et annexé par Israël depuis la guerre des Six Jours en 1967, sans reconnaissance de la majorité de la communauté internationale. Depuis le 8 décembre 2024, le versant sud du mont Hermon jusqu'à son sommet, alors situé dans une zone démilitarisée, est occupé par l'armée israélienne."],"src":"https://fr.wikipedia.org/wiki/Mont_Hermon","sw":"w","q":"Q215471"},"mont-hood":{"n":"mont Hood","t":"sommet","massif":"Oregon Cascades","bref":["Le mont Hood est un stratovolcan situé dans le nord de l’État américain de l'Oregon. La montagne est localisée à environ 100 km à l’est de Portland. Ses pics couverts de neige marquent la frontière entre les comtés de Clackamas et de Hood River. C’est le plus haut sommet de l’Oregon et le quatrième de la chaîne des Cascades. On peut voir facilement la montagne depuis Portland et Vancouver, ville de l'État de Washington. La montagne se trouve dans la forêt nationale du même nom."],"src":"https://fr.wikipedia.org/wiki/Mont_Hood","sw":"w","q":"Q275662","pays":["US"],"c":["amerique-nord"]},"mont-kailash":{"n":"mont Kailash","t":"sommet","massif":"Kailas","bref":["Le mont Kailash (du sanskrit : कैलास पर्वत, IAST : Kailāsa Parvata ; translittération en tibétain kai la sha Wylie : kai la sha), également appelé en tibétain Gang Rinpoché (tibétain : གངས་རིན་པོ་ཆེ, Wylie : gangs rin po che, pinyin tibétain : Kangrinboqê, THL : gang rinpoche ; qui donne la translittération en chinois : 冈仁波齐峰 ; pinyin : gāngrénbōqí fēng ; litt. « sommet de monsieur/rinpoché gang ») et dans le jaïnisme aṣṭapāda (sanskrit : अष्टपाद, aṣṭapāda, huit pieds), est une montagne culminant à 6 638 mètres d'altitude et faisant partie de la chaîne de Gangdise ou Transhimalaya. Elle est située dans la préfecture de Ngari, dans la région autonome du Tibet, à proximité du lac Manasarovar et du lac Rakshastal. Quatre des plus grands cours d'eau d'Asie, l'Indus, le Sutlej, le Brahmapoutre et la Karnali prennent leur source à proximité du mont Kailash."],"src":"https://fr.wikipedia.org/wiki/Mont_Kailash","sw":"w","q":"Q229107","pays":["CN"],"c":["asie"]},"mont-kazbek":{"n":"mont Kazbek","t":"sommet","massif":"Grand Caucase","bref":["Le mont Kazbek (en géorgien : ყაზბეგი) est un sommet et volcan endormi culminant à 5 047 mètres d'altitude en Géorgie, près de la frontière avec la Russie. C'est la cinquième plus haute montagne du Caucase et la deuxième de Géorgie après le mont Chkhara. Il est couvert de glaciers et son ascension ne présente que des difficultés moyennes. Il a été gravi pour la première fois le 1er juillet 1868 par Douglas William Freshfield, Adolphus Warburton Moore et Charles Comyns Tucker."],"src":"https://fr.wikipedia.org/wiki/Mont_Kazbek","sw":"w","q":"Q207680","pays":["RU"],"c":["asie","europe"]},"mont-kenya":{"n":"mont Kenya","t":"sommet","massif":"Kilimanjaro","bref":["Le mont Kenya est un volcan éteint situé en Afrique. Il a donné son nom au Kenya, le pays dans lequel il est situé. Avec une altitude maximale de 5 199 mètres à la pointe Batian, il s'agit du deuxième sommet d'Afrique par l'altitude après le mont Kibo, dans le massif du Kilimandjaro.","Les différentes ethnies qui vivent dans le massif l'appellent Kirinyaga dans le cas des Kikuyus, Kirenia dans le cas des Embus ou Ol Donyo Eibor dans le cas des Masaïs. Ces différentes dénominations signifient montagne blanche. En effet, le sommet se caractérise par la présence de petits glaciers et la persistance de neige au sommet n'est pas rare.","Le volcan s'est formé entre 3,1 millions d'années et 2,6 millions d'années. Comme pour le Kilimandjaro, sa formation est due à l'ouverture du rift est-africain. Le climat du mont Kenya se caractérise par de fréquentes chutes de pluie, les saisons sèches ne sont donc pas autant marquées que dans le reste du pays. La nature volcanique du sol et cette pluviométrie rendent les pentes du mont Kenya très fertiles, ce qui en fait la zone agricole la plus importante du Kenya."],"src":"https://fr.vikidia.org/wiki/Mont_Kenya","sw":"v","q":"Q172070","pays":["KE"],"c":["afrique"]},"mont-kinabalu":{"n":"mont Kinabalu","t":"sommet","massif":"Banjaran Crocker","bref":["Le mont Kinabalu, en malais gunung Kinabalu, est le point culminant de l'île de Bornéo et de la Malaisie. Cette montagne appartient au Banjaran Crocker, un massif du Nord de Bornéo, à la pointe nord-est de l'État malaisien de Sabah. L'altitude du Kinabalu est de 4 095 mètres. Ce sommet est le plus èlevé de l'archipel malais. Il est aussi par l'altitude le troisième sommet insulaire du monde, après le Puncak Jaya (Indonésie) et le Mauna Kea (Hawaï, États-Unis). C'est donc un sommet qui compte beaucoup dans la géographie de l'Asie du Sud-Est."],"src":"https://fr.vikidia.org/wiki/Mont_Kinabalu","sw":"v","q":"Q60967","pays":["MY"],"c":["asie"]},"mont-kosciuszko":{"n":"mont Kosciuszko","t":"sommet","massif":"Snowy Mountains","bref":["Le mont Kosciuszko est le point culminant du sous-continent australien avec 2 228 mètres d'altitude, ce qui lui vaut, non sans controverses, d'être classé sur la liste de Bass des sept sommets et en fait la montagne la plus aisée à gravir parmi ceux-ci. Le sommet fut officiellement vaincu en 1840 par l'explorateur polonais Paweł Edmund Strzelecki qui en profita pour le nommer en l'honneur de son compatriote Tadeusz Kościuszko. En raison de l'exploitation de la montagne par les bergers, puis du développement touristique et enfin des travaux d'aménagement hydrographique, le milieu naturel, caractérisé par une flore alpine unique en Australie, est fragilisé. La zone est protégée en 1944 puis classée officiellement au sein du parc national du Kosciuszko en 1967."],"src":"https://fr.wikipedia.org/wiki/Mont_Kosciuszko","sw":"w","q":"Q178167","pays":["AU"],"c":["oceanie"]},"mont-liban":{"n":"mont Liban","t":"sommet","bref":["Le mont Liban (en arabe جبل لبنان et سلسلة جبال لبنان الغربية, « Montagne occidentale du Liban ») est une chaîne de montagnes du Liban et, pour une petite partie, de Syrie ; elle domine la mer Méditerranée située à l'ouest, et culmine au Qurnat as Sawda' à 3 088 mètres d'altitude. Il s'agit du plus haut relief montagneux du Proche-Orient.","Cette montagne a constitué le noyau du Grand Liban, à l'origine de la république libanaise moderne. Elle est majoritairement peuplée de chrétiens (maronites surtout), avec une minorité importante de la communauté druze (surtout dans les montagnes du Chouf)."],"src":"https://fr.wikipedia.org/wiki/Mont_Liban","sw":"w","q":"Q333711","pays":["LB"],"c":["asie"]},"mont-logan":{"n":"mont Logan","t":"sommet","massif":"chaîne Saint-Élie","bref":["Le mont Logan est un sommet d'Amérique du Nord situé dans la chaîne Saint-Élie, au Canada. La montagne s'élève à 5 959 mètres d'altitude."],"src":"https://fr.vikidia.org/wiki/Mont_Logan","sw":"v","q":"Q120306","pays":["CA"],"c":["amerique-nord"]},"mont-olympe":{"n":"mont Olympe","t":"sommet","bref":["Le mont Olympe (en grec ancien Ὄλυμπος / Ólympos, en grec moderne Όλυμπος / Ólimbos) est une montagne de Grèce située au nord de la Thessalie. C'est la plus haute du pays : elle culmine à 2 917 m."],"src":"https://fr.vikidia.org/wiki/Mont_Olympe","sw":"v","q":"Q80344","pays":["GR"],"c":["europe"]},"mont-ontake":{"n":"mont Ontake","t":"sommet","massif":"monts Hida","bref":["Le mont Ontake (御嶽山, Ontake-san) ou mont Kiso Ontake (木曽御嶽山, Kiso Ontake-san) est un stratovolcan du Japon situé dans le centre de l'île de Honshū, à la frontière entre les préfectures de Gifu et de Nagano, à une centaine de kilomètres au nord-est de Nagoya. Il s'agit du deuxième volcan le plus élevé du Japon avec 3 067 mètres d'altitude, après le mont Fuji, et du seizième sommet de l'archipel par sa hauteur de culminance. Il fait partie des 100 montagnes célèbres du Japon. Dans la culture locale, c'est une montagne sacrée importante."],"src":"https://fr.wikipedia.org/wiki/Mont_Ontake","sw":"w","q":"Q1754806","pays":["JP"],"c":["asie"]},"mont-paektu":{"n":"mont Paektu","t":"sommet","massif":"Massif du Paektu","bref":["Le mont Paektu (en coréen : 백두산, Baektu-san) ou mont Changbai (en chinois : 长白山, Chángbái shān) est la montagne la plus haute de Corée, située à la fois en Corée du Nord et en Chine. Elle culmine à 2 744 mètres d'altitude. Il s'agit d'un volcan gris dont l'éruption de 946 a été l'une des plus violentes de l'histoire.","Les Coréens et les Mandchous la considèrent comme une montagne sacrée. Les hymnes nationaux de la Corée du Nord (Aegukka) et de la Corée du Sud (Aegukga) la mentionnent. Le mont Paektu est représenté sur l'emblème de la Corée du Nord. Selon la légende coréenne, Dangun, le fondateur du premier royaume coréen Gojoseon, serait né sur le mont Paektu.","La Corée du Nord considère la partie coréenne du mont Paektu comme une réserve naturelle. La Chine considère la partie chinoise du mont Changbai comme une réserve de biosphère."],"src":"https://fr.vikidia.org/wiki/Mont_Paektu","sw":"v","q":"Q107635","pays":["KP","CN"],"c":["asie"]},"mont-parnasse":{"n":"mont Parnasse","t":"sommet","massif":"Pinde","bref":["Le mont Parnasse (ou simplement Parnasse, du grec ancien Παρνασσός / Parnassós) est une montagne du centre de la Grèce, qui surplombe la cité de Delphes, à proximité d'Aráchova. Particulièrement vénéré dans l'Antiquité, il était consacré à la fois au dieu Apollon et aux neuf Muses, dont il était l'une des deux résidences avec le mont Hélicon. Il fait partie des dix parcs nationaux de Grèce. Le Parnasse accueille le principal domaine skiable de Grèce."],"src":"https://fr.wikipedia.org/wiki/Mont_Parnasse","sw":"w","q":"Q105261","pays":["GR"],"c":["europe"]},"mont-rainier":{"n":"mont Rainier","t":"sommet","massif":"chaîne des Cascades","bref":["Le mont Rainier, en anglais Mount Rainier, est un volcan actif des États-Unis situé dans l'État de Washington, dans la région du Puget Sound et appartenant à l'arc volcanique des Hautes Cascades. Son altitude de 4 392 mètres lui permet d'être le point culminant de la chaîne des Cascades et de l'État de Washington. Ses coordonnées géographiques sont : 46° 51′ 08″ N 121° 45′ 37″ W / 46.852313, -121.760318."],"src":"https://fr.vikidia.org/wiki/Mont_Rainier","sw":"v","q":"Q194057","pays":["US"],"c":["amerique-nord"]},"mont-redoubt":{"n":"mont Redoubt","t":"sommet","massif":"Chigmit Mountains","bref":["Le mont Redoubt ou volcan Redoubt, en anglais Mount Redoubt, est un stratovolcan actif et le plus haut sommet de la chaîne aléoutienne, dans la péninsule d'Alaska en Alaska. Il est situé dans les monts Chigmit (une sous-chaîne des aléoutiennes), à l'ouest du golfe de Cook, à environ 180 kilomètres au sud-ouest d'Anchorage."],"src":"https://fr.wikipedia.org/wiki/Mont_Redoubt","sw":"w","q":"Q840735","pays":["US"],"c":["amerique-nord"]},"mont-roraima":{"n":"mont Roraima","t":"sommet","massif":"Sierra de Pacaraima","bref":["Le mont Roraima est une montagne d'Amérique du Sud partagée entre le Brésil, le Guyana et le Venezuela. Il s'agit d'un tepuy, une montagne tabulaire caractéristique du plateau des Guyanes. Délimité par des falaises d'environ 1 000 mètres de hauteur, son plateau sommital présente un environnement totalement différent de la forêt tropicale humide et de la savane qui s'étendent à ses pieds. Ainsi, la forte pluviométrie est à l'origine de formations pseudokarstiques, dont de nombreuses et grandes grottes, ainsi que du lessivage du sol."],"src":"https://fr.wikipedia.org/wiki/Mont_Roraima","sw":"w","q":"Q4777","pays":["VE","BR","GY"],"c":["amerique-sud"]},"mont-ruapehu":{"n":"mont Ruapehu","t":"sommet","massif":"massif du Tongariro","bref":["Le mont Ruapehu, ou simplement Ruapehu, est un volcan actif de Nouvelle-Zélande inclus dans le parc national de Tongariro et situé dans le centre de l'île du Nord dont il est le point culminant avec 2 797 mètres d'altitude. La montagne comporte les seuls glaciers et les plus grandes pistes de ski de l'île du Nord. Le climat alpin qui règne au sommet de la montagne permet le maintien de neiges éternelles et de petits glaciers autour du lac de cratère."],"src":"https://fr.wikipedia.org/wiki/Mont_Ruapehu","sw":"w","q":"Q207284","pays":["NZ"],"c":["oceanie"]},"mont-rushmore":{"n":"mont Rushmore","t":"sommet","massif":"Black Hills","bref":["Le mont Rushmore (en anglais : Mount Rushmore) est une montagne connue car elle comporte sur l'une de ses faces un ensemble de statues colossales. Elle est composée de granite et est située en Dakota du Sud, aux États-Unis. Ce mémorial représente la tête de quatre des présidents des États-Unis : George Washington (1732-1799), Thomas Jefferson (1743-1826), Theodore Roosevelt (1858-1919) et Abraham Lincoln (1809-1865).","Pour la construction du monument, de 1927 à 1941, d'importantes mesures de sécurité furent prises : les sculpteurs taillaient la roche avec des outils adaptés et étaient suspendus par le haut du mont. Le sculpteur qui dirigeait le chantier était Gutzon Borglum (aidé de son fils) qui a connu le sculpteur Auguste Rodin lors de ses études à Paris. Le projet de départ prévoyait de représenter aussi le tronc des quatre présidents, mais seuls les visages ont été terminés à la mort du sculpteur en 1941."],"src":"https://fr.vikidia.org/wiki/Mont_Rushmore","sw":"v","q":"Q83497","pays":["US"],"c":["amerique-nord"]},"mont-saint-helens":{"n":"mont Saint Helens","t":"sommet","massif":"chaîne des Cascades","bref":["Le mont Saint Helens est un volcan explosif actif situé dans l'État de Washington, au Nord-Ouest des États-Unis, à 150 kilomètres au sud de la ville de Seattle (Washington) et à 80 kilomètres au nord-est de la ville de Portland (Oregon).","Le mont Saint Helens n'a pas été nommé en l'honneur de sainte Hélène, mais en hommage à un diplomate anglais portant le titre de Lord St Helens. Ami de l'explorateur George Vancouver, il explora cette zone à la fin du XVIIIe siècle.","Le volcan fait partie de la chaîne des Cascades qui elle-même fait partie de la ceinture de feu du Pacifique qui rassemble environ 160 volcans actifs."],"src":"https://fr.vikidia.org/wiki/Mont_Saint_Helens","sw":"v","q":"Q4675","pays":["US"],"c":["amerique-nord"]},"mont-scenery":{"n":"mont Scenery","t":"sommet","bref":["Le mont Scenery (en anglais : Mount Scenery) est un dôme de lave situé sur Saba, une île des Antilles et commune des Pays-Bas à statut particulier."],"src":"https://fr.wikipedia.org/wiki/Mont_Scenery","sw":"w","q":"Q1301834"},"mont-sinai":{"n":"mont Sinaï","t":"sommet","massif":"Sinai mountain range","bref":["Le mont Sinaï (ou Djebel Moussa, \"la Montagne de Moïse \" ) est un mont d’Égypte, haut de plus de 2 200 mètres.","Dans la tradition biblique, le mont Sinaï est le lieu où Moïse a reçu les 10 commandements.","Sous l'empereur Justinien, un monastère chrétien a été construit au pied de la montagne, sur les « lieux du Buisson Ardent »."],"src":"https://fr.vikidia.org/wiki/Mont_Sina%C3%AF","sw":"v","q":"Q377485","pays":["EG"],"c":["afrique"]},"mont-tai":{"n":"mont Tai","t":"sommet","bref":["Le mont Tai ou Taishan (sinogrammes simplifiés : 泰山 ; hanyu pinyin : tàishān), se situe au nord de la ville de Tai'an, dans la province du Shandong en république populaire de Chine. Son point culminant, le pic de l'Empereur de jade, a une altitude de 1 545 m. Il est particulièrement important par son histoire et sa signification culturelle, car c'est l'une des cinq montagnes sacrées de la Chine. C'est le Mont de l'Est, associé à l'aurore, à la naissance et au renouveau, et la plus vénérée des cinq montagnes sacrées. Les temples qui y sont perchés sont une destination de choix pour les pèlerins depuis 3 000 ans. C'est le théâtre d'un pèlerinage unique : l'ascension nocturne vers le pic sacré de l'Empereur de jade."],"src":"https://fr.wikipedia.org/wiki/Mont_Tai","sw":"w","q":"Q216059","pays":["CN"],"c":["asie"]},"mont-thabor":{"n":"mont Thabor","t":"sommet","massif":"basse Galilée","bref":["Le mont Thabor, ou mont Tabor (en hébreu הר תבור) est une montagne isolée de 588 mètres d'altitude située au cœur de la Galilée, en Israël."],"src":"https://fr.wikipedia.org/wiki/Mont_Thabor_(Isra%C3%ABl)","sw":"w","q":"Q193785","pays":["IL"],"c":["asie"]},"mont-whitney":{"n":"mont Whitney","t":"sommet","massif":"sierra Nevada","bref":["Le mont Whitney est le point culminant de la sierra Nevada, des chaînes côtières du Pacifique, de la Californie et des États-Unis, sans l'Alaska. En effet seul cet État détient des sommets plus hauts. Ce mont californien a une altitude de 4 419 mètres. Son isolement topographique est aussi considérable : il s'élève à 2 649 kilomètres. Cette distance correspond à l'éloignement du plus proche sommet dépassant le mont Whitney en altitude, soit le pico de Aguila (4 620 mètres), situé au Mexique, dans la cordillère Néovolcanique. Enfin, la proéminence du mont est de 3 072 mètres, ce qui classe le mont Whitney septième des États-Unis pour cette spécialité. Le nom du sommet rend hommage au géologue Josiah Dwight Whitney."],"src":"https://fr.vikidia.org/wiki/Mont_Whitney","sw":"v","q":"Q235539","pays":["US"],"c":["amerique-nord"]},"montagne-de-la-table":{"n":"montagne de la Table","t":"sommet","bref":["La montagne de la Table (en afrikaans : Tafelberg, en anglais : Table Mountain) est un massif de la province du Cap-Occidental en Afrique du Sud, qui surplombe la ville du Cap.","Elle fait partie des sept nouvelles merveilles de la nature."],"src":"https://fr.wikipedia.org/wiki/Montagne_de_la_Table","sw":"w","q":"Q213360","pays":["ZA"],"c":["afrique"]},"montagne-pelee":{"n":"montagne Pelée","t":"sommet","bref":["La montagne Pelée est un volcan gris qui se situe à l'extrême nord de la Martinique. La montagne Pelée culmine à 1 397 m d’altitude. Elle a une superficie de 120 km².","C'est un stratovolcan. Un stratovolcan est un édifice volcanique formé d'un empilement de coulées de laves et de dépôts pyroclastiques résultant de multiples éruptions à partir d'un évent central ou d'évents proches). Ces volcans forment généralement des cônes pentus et peuvent être éventrés plusieurs fois au cours de leur période d'activité par la formation d'explosions ou d'avalanches.","C’est le seul volcan actif en Martinique.","La plus grande éruption, qui a eu lieu en 1902, a fait 26 000 morts pour seulement deux survivants. Lors de cette éruption, la ville de Saint-Pierre a atteint les 900 °C et les nuées ardentes 160 km/h."],"src":"https://fr.vikidia.org/wiki/Montagne_Pel%C3%A9e","sw":"v","q":"Q76309","pays":["FR"],"c":["europe"]},"montagnes-rocheuses":{"n":"montagnes Rocheuses","t":"sommet","massif":"cordillère nord-américaine","bref":["Les montagnes Rocheuses ou simplement les Rocheuses sont une chaîne de montagnes d'Amérique du Nord, située aux Canada et aux États-Unis. Orientées nord-ouest/sud-est, elles s'étendent sur environ 3 400 km de long et leur largeur atteint à son maximum 640 km."],"src":"https://fr.vikidia.org/wiki/Montagnes_Rocheuses","sw":"v","q":"Q5463","pays":["CA","US"],"c":["amerique-nord"]},"monts-huang":{"n":"monts Huang","t":"sommet","bref":["Les monts Huang, ou Huangshan ou monts Jaunes (chinois : 黄山 ; pinyin : huángshān ; litt. « montagnes jaunes ») sont un massif montagneux de l'Anhui méridional, province de l'est de la Chine. La région est connue pour sa beauté, qui repose sur la forme des pics de granite, sur celle tourmentée des conifères, et sur les nuages qui entourent fréquemment le massif. Cette montagne mythique change sans cesse de visage au gré des vents et des bruines... désespérant parfois les artistes qui désirent en fixer la beauté. La région abrite également des sources d'eau chaude, et des sources minérales qui alimentent des piscines naturelles."],"src":"https://fr.wikipedia.org/wiki/Monts_Huang","sw":"w","q":"Q36034","pays":["CN"],"c":["asie"]},"monts-saian":{"n":"monts Saïan","t":"sommet","bref":["Les monts Saïan, ou massif des Saïan (russe : Саяны, Saïany ; en mongol : Соёны нуруу (Soyonï nurû) ; en vieux-turc : 𐰚𐰇𐰏𐰢𐰤 (Kögmen)), sont une chaîne de montagnes s'étendant en Sibérie méridionale entre les sujets de Khakassie, de Krasnoïarsk, de Touva, d'Irkoutsk et de Bouriatie en Russie et l'aïmag de Khövsgöl en Mongolie. Elle consiste en deux parties, avec le Saïan oriental du Baïkal au Ienisseï sur plus de 1 000 km, et le Saïan occidental jusqu'au massif de l'Altaï sur près de 500 km. Le Mounkou Sardyk, dans le Saïan oriental, constitue le point culminant de la chaîne avec 3 491 mètres d'altitude, tandis que le Kyzyl Taïga à 3 121 mètres est le point culminant du Saïan oriental."],"src":"https://fr.wikipedia.org/wiki/Monts_Sa%C3%AFan","sw":"w","q":"Q203239","pays":["RU"],"c":["asie","europe"]},"monts-taurus":{"n":"monts Taurus","t":"sommet","bref":["Les monts Taurus (en turc : Toros Dağları ; en grec ancien : ὄρη Ταύρου), ou simplement les Taurus (en turc : Toroslar), sont une chaîne de montagnes de Turquie, formant la bordure sud-est du plateau de l'Anatolie et culminant à 3 756 m au Demirkazık."],"src":"https://fr.wikipedia.org/wiki/Monts_Taurus","sw":"w","q":"Q172556","pays":["TR"],"c":["asie","europe"]},"moussala":{"n":"Moussala","t":"sommet","massif":"Rila","bref":["Le mont Moussala (en bulgare : Мусала, translittération internationale Musala) est un ensemble de sommets des Balkans (dont il constitue le point culminant), dans le massif du Rila. Il culmine à 2 925 mètres d'altitude."],"src":"https://fr.wikipedia.org/wiki/Moussala_(montagne)","sw":"w","q":"Q209341","pays":["BG"],"c":["europe"]},"namcha-barwa":{"n":"Namcha Barwa","t":"sommet","massif":"Himalaya de l'Assam","bref":["Le Namcha Barwa est un important sommet de Chine. S'élevant à 7 782 mètres, il se situe plus précisément dans l'Himalaya de l'Assam dont il est le point culminant. En Asie, il s'agit par l'altitude du septième sommet de chaîne. Au classement mondial des sommets indépendants (c'est-à-dire ceux possédant une proéminence égale ou supérieure à 500 mètres), il occupe le vingt-septième rang."],"src":"https://fr.vikidia.org/wiki/Namcha_Barwa","sw":"v","q":"Q1050238","pays":["CN"],"c":["asie"]},"nanda-devi":{"n":"Nanda Devi","t":"sommet","massif":"Himalaya","bref":["La Nanda Devi, signifiant « déesse de la Félicité » (de devi, « déesse », et nanda, « joie »), est la plus haute montagne complètement contenue dans le territoire indien. C'est aussi le plus haut sommet de la chaîne du Garhwal. Il est protégé dans un parc national."],"src":"https://fr.wikipedia.org/wiki/Nanda_Devi","sw":"w","q":"Q213262","pays":["IN"],"c":["asie"]},"nanga-parbat":{"n":"Nanga Parbat","t":"sommet","massif":"Himalaya","bref":["Le Nanga Parbat est un sommet de l'Himalaya situé au Pakistan, dans la province du Gilgit-Batistan. Il fait partie de l'Himalaya du Pendjab dont il est le point culminant. Le sommet ne se trouve qu'à vingt-cinq kilomètres au sud-est de la vallée de l'Indus."],"src":"https://fr.vikidia.org/wiki/Nanga_Parbat","sw":"v","q":"Q130736","pays":["PK"],"c":["asie"]},"nemrut-dag":{"n":"Nemrut Dağı","t":"sommet","massif":"monts Taurus","bref":["Le mont Nemrut (en turc : Nemrut Dağı) est une montagne de l'Est de la Turquie, en Anatolie. Elle domine la vallée de l'Euphrate, dans une région très isolée, au nord de la ville d'Urfa.","La montagne porte à son sommet, à 2 150 m, un sanctuaire antique, composé d'un tumulus et de monuments cultuels, constituant le mausolée d'Antiochos Ier, roi de Commagène, issu d'une dynastie arménienne, qui a régné sur la région aux environs de 69 à 40 av. J.-C."],"src":"https://fr.vikidia.org/wiki/Mont_Nemrut","sw":"v","q":"Q207917","pays":["TR"],"c":["asie","europe"]},"nevado-de-incahuasi":{"n":"Nevado de Incahuasi","t":"sommet","massif":"cordillère des Andes","bref":["Le Nevado de Incahuasi (prononcé en espagnol : [iŋkaˈwasi] ; du quechua Inka Wasi signifiant « maison de l'Inca » est un volcan des Andes, en Amérique du Sud. Il est situé à la frontière entre la province de Catamarca (département de Tinogasta) en Argentine et la IIIe région d'Atacama au Chili. Il s’élève à une altitude de 6 638 m, ce qui en fait le septième volcan du monde (volcans actifs et éteints confondus).","Le volcan consiste en une caldeira de 3,5 km de large et deux stratovolcans. Quatre cônes pyroclastiques sont situés à 7 km au nord-est et ont produit des coulées de lave basalte-andésite ayant recouvert une superficie de 10 km2."],"src":"https://fr.wikipedia.org/wiki/Nevado_de_Incahuasi","sw":"w","q":"Q1478849","pays":["CL","AR"],"c":["amerique-sud"]},"nevado-del-ruiz":{"n":"Nevado del Ruiz","t":"sommet","massif":"Cordillère Centrale","bref":["Le Nevado del Ruiz est un volcan actif situé en Colombie, près de la ville de Manizales, dans les Andes. Son sommet se situe à 5 321 mètres d'altitude.","C'est un volcan de type explosif, l'éruption la plus meurtrière a eu lieu en 1985. Sa dernière éruption commencée le 28 novembre 2014 est toujours en cours."],"src":"https://fr.vikidia.org/wiki/Nevado_del_Ruiz","sw":"v","q":"Q233351","pays":["CO"],"c":["amerique-sud"]},"nevado-ojos-del-salado":{"n":"Nevado Ojos del Salado","t":"sommet","massif":"cordillère des Andes","bref":["Le Nevado Ojos del Salado (ce qui signifie les yeux du salé) est un volcan situé dans la cordillère des Andes. Il culmine à 6 893 mètres d'altitude.","La montagne fut vaincue pour la première fois le 26 février 1937 par deux Polonais, Justin Tymon Wojsznis et Jan Alfred Szczepanski."],"src":"https://fr.vikidia.org/wiki/Nevado_Ojos_del_Salado","sw":"v","q":"Q233836","pays":["CL","AR"],"c":["amerique-sud"]},"novarupta":{"n":"Novarupta","t":"sommet","massif":"chaîne aléoutienne","bref":["Le Novarupta est un volcan des États-Unis situé en Alaska, à proximité du mont Katmai. Il s'est formé au cours de son unique éruption en 1912 qui est une des plus puissantes du XXe siècle et qui a donné naissance à une formation volcano-sédimentaire remarquable, la vallée des Dix Mille Fumées, mise en place par une déferlante pyroclastique."],"src":"https://fr.wikipedia.org/wiki/Novarupta","sw":"w","q":"Q692922","pays":["US"],"c":["amerique-nord"]},"nowshak":{"n":"Nowshak","t":"sommet","massif":"Hindou Kouch","bref":["Le Nowshak, ou Noshaq, culminant à 7 492 m d'altitude, est une montagne entre l'Afghanistan, dont il est le point culminant, et le Pakistan, ainsi que le deuxième plus haut sommet de l’Hindou Kouch après le Tirich Mir (7 690 m)."],"src":"https://fr.wikipedia.org/wiki/Nowshak","sw":"w","q":"Q271700","pays":["AF","PK"],"c":["asie"]},"nuptse":{"n":"Nuptse","t":"sommet","massif":"Mahalangur Himal","bref":["Le Nuptse est un sommet népalais dans la région de Khumbu situé au sud-ouest de l'Everest. Son nom signifie en tibétain « Sommet de l'Ouest ». C'est l'un des plus proches satellites de l'Everest, sa face nord dominant la combe Ouest."],"src":"https://fr.wikipedia.org/wiki/Nuptse","sw":"w","q":"Q1139538","pays":["NP"],"c":["asie"]},"nyiragongo":{"n":"Nyiragongo","t":"sommet","massif":"Montagnes des Virunga","bref":["Le Nyiragongo est un volcan d'Afrique situé en république démocratique du Congo, non loin de la frontière séparant le pays du Rwanda et à 168 kilomètres au sud de la ligne équatoriale. Il se trouve sur la branche occidentale de la vallée du Grand Rift, au nord de la ville de Goma, elle-même construite sur la rive nord du lac Kivu."],"src":"https://fr.vikidia.org/wiki/Nyiragongo","sw":"v","q":"Q214696","pays":["CD"],"c":["afrique"]},"or-fajokull":{"n":"Öræfajökull","t":"sommet","bref":["L'Öræfajökull est le plus grand volcan d'Islande, situé dans le sud-est du pays. Il est constitué d'une caldeira occupée par le glacier Öræfajökull, l'extrémité méridionale du Vatnajökull, la plus grande calotte glaciaire d'Islande. L'un des rebords de cette caldeira, le Hvannadalshnjúkur, constitue le point culminant du pays."],"src":"https://fr.wikipedia.org/wiki/%C3%96r%C3%A6faj%C3%B6kull_(volcan)","sw":"w","q":"Q298119","pays":["IS"],"c":["europe"]},"osorno":{"n":"Osorno","t":"sommet","massif":"Cordillère de Patagonie","bref":["L'Osorno est un stratovolcan situé entre la province d'Osorno et celle de Llanquihue, dans la région des Lacs au Chili. D'une altitude de 2 652 mètres, il est le volcan le plus actif dans le sud des Andes chiliennes.","Il s'élève à l'est du lac Llanquihue, connu mondialement comme symbole du paysage local. Le volcan domine également le lac de Todos los Santos. Sa dernière éruption date de 1869.","Charles Darwin aperçoit l'Osorno, de loin, lors de son second voyage sur le HMS Beagle et il est témoin de son éruption en janvier 1835. Il en fait mention dans son compte-rendu sur le séisme du 20 février 1835 à Concepción.","Sa première ascension est réalisée en 1848 par Jean Renous."],"src":"https://fr.wikipedia.org/wiki/Osorno_(volcan)","sw":"w","q":"Q858808","pays":["CL"],"c":["amerique-sud"]},"oural-q35600":{"n":"Oural","t":"sommet","bref":["L'Oural est une chaîne de montagnes en Russie. Elle se développe sur 2 300 km, de la mer de Kara au fleuve Oural, qui marque la limite sud de la chaîne. La largeur de la chaîne varie de 96 kilomètres dans le nord à seulement 32 dans le Sud. On dit traditionnellement que cette chaîne est la limite entre l'Europe et l'Asie. C'est vrai. Mais il faut préciser comment les choses se sont déroulées.","En réalité, c'est le tsar Pierre le Grand qui est à l'origine de cette démarcation. Au sud de la chaîne, les monts Mughalzar sont une extension de l'Oural au Kazakhstan. Bien que distincts des monts Oural, ils appartiennent à la ceinture orogénique ouralienne (ou système ouralien). Au nord, la chaîne est prolongée par les crêtes Pay Khoy, faisant elles aussi partie de la ceinture ouralienne."],"src":"https://fr.vikidia.org/wiki/Oural","sw":"v","q":"Q35600","pays":["RU"],"c":["asie","europe"]},"pacaya":{"n":"Pacaya","t":"sommet","massif":"Sierra Madre de Chiapas","bref":["Le Pacaya est un volcan actif de 2 552 mètres d'altitude situé en périphérie de la ville d'Antigua, au Guatemala. Il entra en éruption pour la première fois il y a environ 23 000 ans et, depuis l'arrivée des Espagnols, il est entré en éruption au moins vingt-trois fois.","Après être resté endormi durant près d'un siècle, il entra violemment en éruption en 1961 ; depuis, son activité est relativement constante. Le Pacaya est entré à nouveau dans une phase éruptive du 19 juillet 2004 au 28 octobre 2010, projetant de la lave, des fumées et des cendres, qui se sont élevées jusqu'à 1 000 mètres."],"src":"https://fr.wikipedia.org/wiki/Pacaya","sw":"w","q":"Q753924","pays":["GT"],"c":["amerique-nord"]},"pamir":{"n":"Pamir","t":"sommet","bref":["Le Pamir est un ensemble de massifs de haute montagne situé en Asie centrale, plus précisément dans le centre et l’Est du Tadjikistan et qui se prolonge en Afghanistan à l’ouest-sud-ouest, au Kirghizistan au nord et en Chine au nord-est."],"src":"https://fr.vikidia.org/wiki/Pamir","sw":"v","q":"Q161750","pays":["KG","TJ","CN","AF","IN","PK"],"c":["asie"]},"paricutin":{"n":"Paricutín","t":"sommet","massif":"Cordillère néovolcanique","bref":["Le Paricutín est un volcan du Mexique situé dans l'État du Michoacán. Il est né le 20 février 1943 au cours d'une éruption qui a duré neuf ans, ce qui en fait un des volcans les plus jeunes de la Terre avec Surtsey né en 1963 et l'Ardoukôba en 1978. Il se présente sous la forme d'un cône volcanique aux pentes escarpées culminant à 3 170 mètres d'altitude, dominant des coulées de lave d'où émerge le clocher de l'ancien village de San Juan Parangaricutiro."],"src":"https://fr.wikipedia.org/wiki/Paricut%C3%ADn","sw":"w","q":"Q231620","pays":["MX"],"c":["amerique-nord"]},"parinacota":{"n":"Parinacota","t":"sommet","massif":"Cordillera Occidental","bref":["Le Parinacota est un volcan situé à la frontière bolivo-chilienne dans la région d'Arica et Parinacota au Chili et dans le département d'Oruro en Bolivie dans les Andes. Ce stratovolcan culmine à 6 348 mètres d'altitude.","Avec le Pomerape il forme les Nevados de Payachatas, anciens dieux pour les habitants de l'altiplano andin tant boliviens que chiliens.","Sa première ascension eut lieu le 12 décembre 1928 par le Bolivien Carlos Terán et l'Autrichien Joseph Prem.","Un sentier part du village de Parinacota et monte vers 5 000 mètres d'altitude sur le flanc sud-ouest du volcan. Cette randonnée fait environ 35 à 40 kilomètres aller-retour. Les abords de la frontière bolivienne étant minés côté chilien, il est fortement déconseillé de quitter le sentier et recommandé de se renseigner à la CONAF à Putre."],"src":"https://fr.wikipedia.org/wiki/Parinacota","sw":"w","q":"Q255010","pays":["CL","BO"],"c":["amerique-sud"]},"pennines":{"n":"Pennines","t":"sommet","bref":["Les Pennines sont une chaîne de montagnes du Royaume-Uni située dans le centre et le nord de l'Angleterre. De par son extension nord-sud, sa position centrale dans la Grande-Bretagne et constituant le seul relief vraiment étendu de l'Angleterre, elle est surnommée « la colonne vertébrale de l'Angleterre », en anglais the backbone of England. Son nom est issu du celtique penno qui signifie « tête » > « sommet »."],"src":"https://fr.wikipedia.org/wiki/Pennines","sw":"w","q":"Q35647","pays":["GB"],"c":["europe"]},"petit-caucase":{"n":"Petit Caucase","t":"sommet","massif":"Caucase","bref":["Le Petit Caucase (arménien : Փոքր Կովկաս ; azéri : Kiçik Qafqaz Dağları ; géorgien : მცირე კავკასიონი), ou Caucase mineur, est une des deux chaînes de montagnes du Caucase, longue de près de 600 km. La chaîne montagneuse du Petit Caucase s'étend du sud-est au nord-ouest, au sud de la chaîne du Grand Caucase et marque la limite du haut-plateau arménien.","Le Petit Caucase est relié au Grand Caucase par la chaîne de montagnes de Sourami (ou Likhi), et en est séparé par le pays de Colchide à l'ouest et la vallée du fleuve Koura à l'est. Vers l'ouest, en Turquie, le Petit Caucase trouve son prolongement dans la chaîne pontique qui longe la côte sud de la mer Noire.","Son point culminant est l'Aragats, un volcan isolé d'Arménie qui s'élève à 4 095 m et domine le haut-plateau arménien lui-même situé à plus de 1 000 m d'altitude. En Géorgie, le Petit Caucase culmine au Didi Abouli (3 300 m)."],"src":"https://fr.wikipedia.org/wiki/Petit_Caucase","sw":"w","q":"Q216593","pays":["GE","AM","AZ"],"c":["europe","asie"]},"pic-d-orizaba":{"n":"pic d'Orizaba","t":"sommet","massif":"Cordillère néovolcanique","bref":["Le pic d'Orizaba (en espagnol pico de Orizaba) est le plus haut sommet du Mexique. Il est accessoirement connu sous le nom nahuatl de Citlaltepetl (montagne de l'étoile), couramment employé lors de l'arrivée des Espagnols au Mexique. Il se situe à 99 kilomètres à l'est de Puebla, dans l'État de Puebla, et s'élève au-dessus de la sierra Madre orientale."],"src":"https://fr.vikidia.org/wiki/Pic_d'Orizaba","sw":"v","q":"Q238147","pays":["MX"],"c":["amerique-nord"]},"pic-ismail-samani":{"n":"pic Ismail Samani","t":"sommet","massif":"chaînon de l'Académie des Sciences","bref":["Le pic Ismail Samani (en russe : пик Исмои́ла Сомони́, en tadjik : Qullai Ismoili Somoni), anciennement pic Staline puis pic du Communisme, est le point culminant du Tadjikistan et de l'ancienne Union soviétique. Il s'élève à 7 495 mètres d'altitude dans le massif du Pamir. Gravi pour la première fois en 1933 par Evgeny Abalakov, il est devenu un sommet très fréquenté par les alpinistes."],"src":"https://fr.wikipedia.org/wiki/Pic_Ismail_Samani","sw":"w","q":"Q41413","pays":["TJ"],"c":["asie"]},"pic-lassen":{"n":"pic Lassen","t":"sommet","massif":"California Cascades","bref":["Le pic Lassen, en anglais : Lassen Peak, est un volcan des États-Unis situé dans le Nord de la Californie, à la limite sud de la chaîne des Cascades. Alors considéré comme éteint, il entre en éruption de 1914 à 1917, générant deux puissantes explosions latérales donnant naissance à la Devastated Area, une vallée et une plaine désolées recouvertes par des débris volcaniques. Lieu mythique pour certains Amérindiens, dont il est le centre du monde et le lieu de vie de nombreux esprits, il est inclus dans le parc national volcanique de Lassen."],"src":"https://fr.wikipedia.org/wiki/Pic_Lassen","sw":"w","q":"Q859354","pays":["US"],"c":["amerique-nord"]},"pinatubo":{"n":"Pinatubo","t":"sommet","massif":"Monts Zambales","bref":["Le Pinatubo est un stratovolcan actif situé dans l'ouest de l'île de Luçon aux Philippines, à 100 km au nord-ouest de Manille."],"src":"https://fr.vikidia.org/wiki/Pinatubo","sw":"v","q":"Q1451","pays":["PH"],"c":["asie"]},"plateau-de-siberie-centrale":{"n":"plateau de Sibérie centrale","t":"sommet","massif":"plateau de Poutorana","bref":["Le plateau de Sibérie centrale est une région de Sibérie située en Russie d'Asie, constituée principalement de plateaux peu élevés et comprise entre les cours des grands fleuves sibériens Ienisseï et Léna. Il couvre une surface de 3,5 millions de kilomètres carrés. C'est une région au climat hostile, continental et froid, éloignée des régions habitées et qui, bien que dotée de richesses minières considérables comme la majeure partie de la Sibérie, est restée jusqu'à présent presque inhabitée."],"src":"https://fr.wikipedia.org/wiki/Plateau_de_Sib%C3%A9rie_centrale","sw":"w","q":"Q155197","pays":["RU"],"c":["asie","europe"]},"plateaux-d-ethiopie":{"n":"Plateaux d'Éthiopie","t":"sommet","bref":["Les hauts plateaux abyssins, également appelés hauts plateaux éthiopiens ou trapps d'Éthiopie, forment une région montagneuse accidentée de la Corne de l'Afrique. Principalement situés en Éthiopie, ils s'étendent également partiellement en Érythrée et en Somalie (Somaliland).","Ces plateaux sont formés d'une série de trapps mis en place il y a trente millions d'années par épanchement fissural d'un magma mantellique, liée à la remontée d'un point chaud. Ces dépôts volcaniques massifs, qui ont probablement eu lieu en moins d'un million d'années, se sont accumulées sur 2 500 m d'épaisseur. Ils encadrent le graben de la vallée du Grand Rift et notamment la dépression de l'Afar ; ils se prolongent au nord par l'Itbay qui longe la rive occidentale de la mer Rouge."],"src":"https://fr.wikipedia.org/wiki/Hauts_plateaux_abyssins","sw":"w","q":"Q319288","pays":["ET"],"c":["afrique"]},"ponta-do-pico":{"n":"Ponta do Pico","t":"sommet","massif":"dorsale médio-atlantique","bref":["Le Pico (en portugais, Vulcão do Pico, Montanha do Pico ou Ponta do Pico) est un stratovolcan situé sur l'île de Pico, dans l'archipel des Açores (Portugal). Il affiche une altitude de 2 351 m, ce qui en fait le point le plus élevé du Portugal, mais aussi de la dorsale médio-atlantique."],"src":"https://fr.wikipedia.org/wiki/Pico_(volcan)","sw":"w","q":"Q928681","pays":["PT"],"c":["europe"]},"puncak-jaya":{"n":"Puncak Jaya","t":"sommet","massif":"chaîne de Sudirman","bref":["Le Puncak Jaya, anciennement pyramide Carstensz, est une montagne indonésienne située en Papouasie centrale, sur l'île de Nouvelle-Guinée. Elle se situe dans la chaîne Centrale, un système montagneux qui traverse l'île d'ouest en est, et se localise plus précisément dans la partie occidentale des monts Maoke,"],"src":"https://fr.vikidia.org/wiki/Puncak_Jaya","sw":"v","q":"Q1045888","pays":["ID"],"c":["asie"]},"puyehue":{"n":"Puyehue","t":"sommet","massif":"Cordillère de Patagonie","bref":["Le Puyehue est un volcan du Chili situé dans la cordillère des Andes. Voisin d'un autre volcan, le Cordón Caulle, il se présente sous la forme d'un stratovolcan culminant à 2 236 mètres d'altitude et couronné par une caldeira."],"src":"https://fr.wikipedia.org/wiki/Puyehue_(volcan)","sw":"w","q":"Q577700","pays":["CL"],"c":["amerique-sud"]},"pyrenees":{"n":"Pyrénées","t":"sommet","bref":["Les Pyrénées sont une chaîne de montagnes du sud-ouest de l'Europe, séparant la France et l'Espagne et abritant l'Andorre.","De direction est-ouest, elles s'étendent à peu près sur 430 km d'est en ouest, du golfe de Gascogne (Atlantique) au golfe du Lion (Méditerranée), et sur 60 à 140 km du nord au sud, entre la Gascogne et le bassin de l'Èbre. Leur point culminant est le pic d’Aneto, en Espagne (3 404 m)."],"src":"https://fr.vikidia.org/wiki/Pyr%C3%A9n%C3%A9es","sw":"v","q":"Q12431","pays":["ES","FR","AD"],"c":["europe"]},"rakaposhi":{"n":"Rakaposhi","t":"sommet","massif":"Monts Rakaposhi-Haramosh","bref":["Le Rakaposhi (littéralement « Mur brillant »), également connu sous le nom de Dumani (« La mère des brouillards »), est le 26e plus haut sommet du monde (11e du Pakistan). Il se trouve dans la vallée de Nagar, à environ 30 km au nord de Gilgit, dans le Karakoram occidental."],"src":"https://fr.wikipedia.org/wiki/Rakaposhi","sw":"w","q":"Q933778","pays":["PK"],"c":["asie"]},"rhodopes":{"n":"Rhodopes","t":"sommet","bref":["Les Rhodopes (en bulgare : Родопи / Rodopi, en général utilisé avec l’article défini pluriel, Родопите / Rodopite, parfois également appelés Родопа / Rodopa ou Родопа планина / Rodopa planina, « montagne de Rodopa » ; en grec Ροδόπη / Rodópi — en français, on trouve aussi la forme au singulier « le Rhodope », en turc Rodop dağları) sont un massif montagneux des Balkans, situé dans le Sud-Ouest de la Bulgarie ne débordant qu'en Macédoine-Orientale-et-Thrace, dans le Nord-Est de la Grèce. Avec les massifs du Rila et du Pirin, il forme un même ensemble montagneux. Son plus haut sommet, le Goljam Perelik (2 191 m), est le septième sommet de Bulgarie par son altitude."],"src":"https://fr.wikipedia.org/wiki/Rhodopes","sw":"w","q":"Q6489","pays":["GR","BG"],"c":["europe"]},"rysy":{"n":"Rysy","t":"sommet","massif":"Hautes Tatras","bref":["Le Rysy est un sommet de la chaîne des Hautes Tatras, dans l'arc extérieur des Carpates occidentales, sur la frontière entre la Pologne et la Slovaquie. Il culmine à 2 500 mètres d'altitude en Slovaquie. Sur son versant septentrional, à 2 499,1 mètres d'altitude, se trouve le point culminant de la Pologne.","La montagne est le point le plus élevé des Hautes Tatras accessible aux randonneurs par des sentiers balisés sans guide de haute montagne. Un refuge, le Chata pod Rysmi, situé 250 mètres plus bas que le sommet est à leur disposition. Depuis le début du XXe siècle, de nombreuses personnalités en ont fait l'ascension comme les époux Pierre et Marie Curie ou Lénine, dont l'ascension n'est pas prouvée mais fut largement exploitée par le pouvoir communiste dans le cadre d'une rencontre internationale pour la jeunesse."],"src":"https://fr.wikipedia.org/wiki/Rysy","sw":"w","q":"Q672936","pays":["SK","PL"],"c":["europe"]},"shishapangma":{"n":"Shishapangma","t":"sommet","massif":"Jugal Himal","bref":["Le Shishapangma ou Shisha Pangma (chinois traditionnel : 希夏邦马峰 ; pinyin : xīxiàbāngmǎ fēng), aussi appelé Gosainthan en sanskrit, est une montagne de Chine culminant à 8 027 mètres d'altitude dans la ville-préfecture de Shigatsé, au sein de la région autonome du Tibet. Il est situé dans la chaîne de l'Himalaya et constitue le quatorzième sommet le plus élevé au monde et le dernier des « 8 000 ». Il est gravi pour la première fois par une expédition chinoise en 1964, alors que les frontières du pays étaient fermées aux étrangers. La voie normale emprunte les versants nord de la montagne et présente relativement peu de difficultés."],"src":"https://fr.wikipedia.org/wiki/Shishapangma","sw":"w","q":"Q105124","pays":["CN"],"c":["asie"]},"sierra-nevada":{"n":"sierra Nevada","t":"sommet","alt":4421,"massif":"cordillère nord-américaine","bref":["La sierra Nevada (« la montagne enneigée » en espagnol) est une chaîne de montagnes située dans l'Est de la Californie, aux États-Unis."],"src":"https://fr.vikidia.org/wiki/Sierra_Nevada_(%C3%89tats-Unis)","sw":"v","q":"Q26777","pays":["US"],"c":["amerique-nord"]},"sierra-nevada-q26955":{"n":"Sierra Nevada","t":"sommet","bref":["La sierra Nevada, qui signifie \"chaîne enneigée\" en espagnol, est une chaîne de montagnes faisant partie du système pénibétique de la région espagnole d'Andalousie. C'est la chaîne de montagnes ayant la plus haute altitude dans toute l'Europe occidentale, à l'ouest des Alpes. Elle contient le point culminant de l'Espagne continentale, le Mulhacén, à 3 479 m. En 1986, elle a été déclarée réserve de biosphère par l'UNESCO et en 1999, une grande partie de son territoire a été déclarée parc national pour ses valeurs botaniques, paysagères et naturelles.","C'est une destination touristique populaire, car ses hauts sommets permettent de skier dans la station de ski la plus méridionale d'Europe, dans une zone située le long de la mer Méditerranée, connue principalement pour ses températures chaudes et son soleil abondant. À ses pieds se trouve la ville de Grenade et, un peu plus loin, Malaga et Almería."],"src":"https://fr.vikidia.org/wiki/Sierra_Nevada_(Espagne)","sw":"v","q":"Q26955","pays":["ES"],"c":["europe"]},"sn-fellsjokull":{"n":"Snæfellsjökull","t":"sommet","bref":["Le Snæfellsjökull ['snaiːfɛlsˌjœkʏtl˳] est un stratovolcan d'Islande surmonté d'une calotte glaciaire qui culmine à 1 446 mètres d'altitude. Il est situé à l'extrémité occidentale de la péninsule de Snæfellsnes."],"src":"https://fr.wikipedia.org/wiki/Sn%C3%A6fellsj%C3%B6kull","sw":"w","q":"Q1315012","pays":["IS"],"c":["europe"]},"sniejka":{"n":"Sniejka","t":"sommet","massif":"monts des Géants","bref":["Sniejka (« la neigeuse », en tchèque : Sněžka ; en polonais : Śnieżka ; en allemand : Schneekoppe) est la plus haute montagne des monts des Géants. Elle est traversée en son sommet par la frontière entre la Pologne et la Tchéquie. On peut y accéder par un télésiège depuis la ville tchèque de Pec pod Sněžkou. Le point culminant se situe à 1 602 ou 1 603 mètres d'altitude ; c'est aussi le point culminant de la Tchéquie. Le sommet a une superficie plane importante, ce qui a permis d'y construire plusieurs bâtiments. La température annuelle moyenne y est de 0,2 °C. Sniejka est le point de départ ou le but de nombreux chemins de randonnée pédestre (dont le chemin de l'Amitié tchéco-polonaise), cyclistes et de ski de fond."],"src":"https://fr.wikipedia.org/wiki/Sniejka","sw":"w","q":"Q617511","pays":["CZ","PL"],"c":["europe"]},"sudetes":{"n":"Sudètes","t":"sommet","massif":"Massif de Bohême","bref":["Les Sudètes (en allemand : Sudeten ; en tchèque et en polonais : Sudety ; nom complet dans la littérature tchèque : Krkonošsko-jesenická subprovincie) sont une chaîne de montagnes d'Europe centrale, qui représente la partie nord-est du large massif de Bohême. S'étendant du massif gréseux de l'Elbe à la porte de Moravie, les Sudètes sont à cheval sur l'Allemagne à l'ouest, la Pologne au nord et la Tchéquie au sud, et forment la frontière entre ces deux derniers pays.","Moyennes montagnes, elles culminent à 1 603 mètres d'altitude au mont Sniejka, sur la frontière polono-tchèque. Elles comprennent plusieurs massifs, dont les monts des Géants et le Hrubý Jeseník, qui forment la zone frontalière entre les régions historiques de la Bohême, la Moravie, la Silésie et la Haute-Lusace."],"src":"https://fr.wikipedia.org/wiki/Sud%C3%A8tes_(montagne)","sw":"w","q":"Q152131","pays":["CZ","PL","DE"],"c":["europe"]},"taal":{"n":"Taal","t":"sommet","bref":["Le volcan Taal est situé dans les îles des Calabarzons en Phillipines, en Batangas. Il fait partie d´un chaîne de volcans qui ligne la partie sud de l'île de Luçon. Le volcan Taal et les autres volcans ont été formés par la subduction de la plaque d´Eurasie.","La partie intéressante de ce volcan est qu'il est sur une île dans l’océan, dans le cratère du volcan il y a un lac (le lac Taal), et dans ce lac il y a une autre île qui contient elle aussi un lac et ce lac contient une toute petite île. Le volcan est encore actif."],"src":"https://fr.vikidia.org/wiki/Taal_(volcan)","sw":"v","q":"Q818475","pays":["PH"],"c":["asie"]},"tambora":{"n":"Tambora","t":"sommet","bref":["Le Tambora, en indonésien Gunung Tambora, est un stratovolcan actif qui forme la péninsule de Sanggar de l'île de Sumbawa, dans l'archipel des Petites îles de la Sonde, en Indonésie. Il culmine à 2 850 m d'altitude, mais, avant l'éruption de 1815 qui a formé une caldeira de près de 6 km de diamètre et 1 110 m de profondeur, il s'élevait à une altitude d'environ 4 300 m. Le volcan se situe à 340 kilomètres au nord de la fosse de la Sonde, une des zones sismiques les plus actives de la planète, et constitue un des éléments de la chaîne volcanique de la Sonde, qui compte des dizaines de volcans actifs tels que le Krakatoa. Le Tambora est âgé d'environ 50 000 ans."],"src":"https://fr.wikipedia.org/wiki/Tambora","sw":"w","q":"Q168714","pays":["ID"],"c":["asie"]},"tassili-n-ajjer":{"n":"Tassili n'Ajjer","t":"sommet","bref":["Le tassili n’Ajjer (en berbère : tasili n Ajer, en tifinagh : ⵜⴰⵙⵉⵍⵉ ⵏ ⴰⵣⴶⵔ, Tasili n Azjer ; en arabe : طاسيلي ناجر) est un massif de montagnes situé au centre du Sahara, dans le Sud-Est de l'Algérie et dont la frange orientale se trouve en territoire libyen."],"src":"https://fr.wikipedia.org/wiki/Tassili_n'Ajjer","sw":"w","q":"Q190048","pays":["DZ"],"c":["afrique"]},"tatras":{"n":"Tatras","t":"sommet","massif":"Fatra-Tatra Area","bref":["Les Tatras sont une chaîne de montagnes à cheval sur la frontière entre la Pologne et la Slovaquie. Il s'agit de la partie la plus élevée de la chaîne des Carpates et dont le point culminant est le Gerlachovský štít (ou pic Gerlach), à 2 654 mètres d'altitude, en Slovaquie. Elles font plus précisément partie des Carpates occidentales.","La réserve de biosphère des Tatras a été reconnue par l'Unesco en 1993. Elle est transfrontière entre la Slovaquie et la Pologne."],"src":"https://fr.wikipedia.org/wiki/Tatras","sw":"w","q":"Q194263","pays":["SK","PL"],"c":["europe"]},"teide":{"n":"Teide","t":"sommet","bref":["Le Teide encore appelé pic de Teide, anciennement pic de Tenerife, est le point culminant de Tenerife et de l'Espagne. C'est un volcan d'environ 3 718 mètres d'altitude.","Il possède des coulées de lave très fluides et son activité d'éruption est très active. Par sa taille, il est le troisième volcan au monde.","Sa dernière éruption eut lieu du 18 au 27 novembre 1909. Le pic de Teide est inscrit sur la liste des volcans de la Dècennie, une liste conçue pour mettre en relief une activité éruptive particulière et les risques pour les populations concernées.","Avec une base de diamètre 8 km et un volume vaiant entre 150 et 200 km3, le Teide fait partie du Parc national du Teide qui est le plus visité des parcs nationaux d'Espagne et d'Europe."],"src":"https://fr.vikidia.org/wiki/Teide","sw":"v","q":"Q38954","pays":["ES"],"c":["europe"]},"tian-shan":{"n":"Tian Shan","t":"sommet","bref":["Le Tian Shan (montagnes célestes) est un système montagneux situé en Asie centrale et se répartissant en Ouzbekistan, au Tadjikistan, au Kirghizistan, au Kazakhstan et en Chine. Il s'étend sur 2 500 kilomètres de longueur selon une direction ouest-sud-ouest / est-nord-est. La chaîne est large de 500 kilomètres aux extrémités et de 350 kilomètres au centre. Il existe dans ces montagnes 15 953 glaciers occupant une surface de 15 416 kilomètres carrés."],"src":"https://fr.vikidia.org/wiki/Tian_Shan","sw":"v","q":"Q5474","pays":["KG","KZ","CN","UZ"],"c":["asie","europe"]},"tirich-mir":{"n":"Tirich Mir","t":"sommet","massif":"Hindou Kouch","bref":["Le Tirich Mir est un sommet du Pakistan s'élevant à 7 708 mètres d'altitude dans la province de Khyber Pakhtunkhwa et constituant le point culminant de l'Hindou Kouch. Il est entouré de glaciers. Des alpinistes norvégiens ont réalisé les premières ascensions de la cime principale et de la cime orientale, la deuxième par l'altitude, respectivement en 1950 et en 1964."],"src":"https://fr.wikipedia.org/wiki/Tirich_Mir","sw":"w","q":"Q207132","pays":["PK"],"c":["asie"]},"triglav":{"n":"Triglav","t":"sommet","massif":"Triglav Group","bref":["Le Triglav (ou Monte Tricorno en italien) est un sommet des Alpes. Avec ses 2 864 m, il est le sommet le plus haut de la Slovénie. Le nom de Triglav veut dire Trois Têtes. Il se situe à l'intérieur de l'unique parc national de Slovénie dont il a donné le nom, le Parc national du Triglav","Il est un des symboles du pays, c'est-à-dire qu'il évoque la Slovénie par lui-même. En effet, on retrouve le Triglav dessiné sur le blason et le drapeau slovène ainsi que sur la pièce de 0.50 euro (autrement dit la pièce de 50 centimes) depuis que la Slovénie a adopté l'euro comme monnaie nationale. Le nom de Triglav (Trois Têtes) fait référence à la forme que prend le sommet qui est visible à plus de 100 km, notamment dans le land de Carinthie, en Autriche."],"src":"https://fr.vikidia.org/wiki/Triglav","sw":"v","q":"Q1024","pays":["SI"],"c":["europe"]},"vesuve":{"n":"Vésuve","t":"sommet","massif":"Somma-Vesuvius complex","bref":["Le Vésuve est un volcan italien situé en Campanie, à quinze kilomètres à l'est de Naples, et qui culmine à 1 281 mètres.","C'est l'un des grands volcans encore en activité de nos jours. Ses émanations peuvent se propager à plus de 35 km alentour. Sa dernière éruption importante remonte à mars 1944."],"src":"https://fr.vikidia.org/wiki/V%C3%A9suve","sw":"v","q":"Q524","pays":["IT"],"c":["europe"]},"volcan-de-fuego":{"n":"Volcán de Fuego","t":"sommet","massif":"Sierra Madre de Chiapas","bref":["Le Volcán de Fuego (toponyme espagnol signifiant littéralement « volcan de feu » en français) est un volcan du Guatemala."],"src":"https://fr.wikipedia.org/wiki/Volc%C3%A1n_de_Fuego","sw":"w","q":"Q859376","pays":["GT"],"c":["amerique-nord"]},"vulcano":{"n":"Vulcano","t":"sommet","bref":["Vulcano (en latin Vulcanus, nom du dieu romain du feu Vulcain) est une île volcanique et un archipel volcanique (en latin Vulcani Insulae) d'Italie situées dans les îles Éoliennes, au nord de la Sicile, dans la mer Tyrrhénienne. Elle fait administrativement partie de la commune de Lipari, du nom de l'île principale voisine."],"src":"https://fr.wikipedia.org/wiki/Vulcano","sw":"w","q":"Q207323","pays":["IT"],"c":["europe"]},"wolf":{"n":"Wolf","t":"sommet","bref":["Le Wolf, en espagnol volcán Wolf, ou mont Whiton, en anglais Mount Whiton, est un volcan d'Équateur situé sur l'île Isabela, dans les îles Galápagos. Avec 1 710 mètres d'altitude, il constitue le point culminant de l'archipel. Il est nommé en l'honneur de Theodor Wolf, un géologue, géographe et botaniste allemand qui a étudié les îles Galápagos au XIXe siècle. L'île Wolf, dans le Nord de ce même archipel, tient également son nom de ce scientifique."],"src":"https://fr.wikipedia.org/wiki/Wolf_(volcan)","sw":"w","q":"Q1376373","pays":["EC"],"c":["amerique-sud"]},"zagros":{"n":"Zagros","t":"sommet","bref":["Les monts Zagros forment la plus longue chaîne de montagnes d'Iran. Ils prennent naissance entre Bandar Khamir et Bandar Abbas, sur le détroit d'Ormuz (golfe Persique). Ils s'étendent sur environ 1 540 km du nord du détroit jusqu'au Cheekha Dar, point culminant de l'Irak et proche du lac salé Orumieh (Iran). Au-delà débutent les monts Hakkiari, qui se poursuivent jusqu'à la frontière turque où ils constituent une charnière avec le Sud du haut plateau arménien. Côté iranien s'étend la province de l'Azerbaïdjan occidental. La chaîne forme la limite sud-ouest du plateau iranien."],"src":"https://fr.vikidia.org/wiki/Monts_Zagros","sw":"v","q":"Q167021","pays":["IR","IQ","TR"],"c":["asie","europe"]},"zugspitze":{"n":"Zugspitze","t":"sommet","massif":"Wetterstein","bref":["La Zugspitze, qui signifie en allemand le « pic des traînées de neige » (laissées par les avalanches), est le point culminant de l'Allemagne (2 962 m). Situé à l'extrême sud de la Bavière, dans les Alpes, ce sommet fait partie du Wetterstein, un massif calcaire germano-autrichien."],"src":"https://fr.vikidia.org/wiki/Zugspitze","sw":"v","q":"Q3375","pays":["DE","AT"],"c":["europe"]}},
"iles":{"anglesey":{"n":"Anglesey","t":"île","km2":749,"pop":70043,"bref":["Anglesey (appellation en anglais), ou ynys Môn (appellation en gallois), est une île de la mer d’Irlande, séparée de la Grande-Bretagne par le détroit de Menai et de Holy Island par celui de Cymyran (en).","Plus grande île du pays de Galles (Royaume-Uni), elle est rattachée au comté d’Anglesey, dont le chef-lieu, Llangefni, est également la principale ville de l’île. Ses autres agglomérations sont Amlwch, Llanfair Mathafarn Eithaf, Menai Bridge, Llanfairpwllgwyngyll, Valley et Beaumaris, ancienne capitale du comté. Le littoral insulaire est partiellement classé comme Area of Outstanding Natural Beauty depuis 1967."],"src":"https://fr.wikipedia.org/wiki/Anglesey_(%C3%AEle)","sw":"w","q":"Q168159","pays":["GB"],"c":["europe"]},"bali":{"n":"Bali","t":"île","km2":5633,"pop":4404300,"bref":["Bali est une île d'Indonésie, en mer de Bali. Elle est l'une des petites îles de la Sonde et est située entre les îles de Java et de Lombok. Sa population s'élève à 4 400 000 habitants et sa superficie est de 5 637 km2. La capitale est Denpasar, dans le Sud de l'île.","Les habitants de Bali sont appelés les Balinais(es).","Source : cette page a été partiellement adaptée de la page Bali de Wikipédia."],"src":"https://fr.vikidia.org/wiki/Bali","sw":"v","q":"Q4648","pays":["ID"],"c":["asie"]},"borneo":{"n":"Bornéo","t":"île","km2":748168,"pop":18590000,"bref":["Bornéo est une grande île du sud-est asiatique (Insulinde), la quatrième île au monde par sa superficie (736 000 km2), après l'Australie, le Groenland et la Nouvelle-Guinée.","Elle est baignée par la mer de Chine méridionale au nord-ouest et à l'ouest, par la mer de Sulu à l'extrême nord-est, par la mer de Célèbes au nord-est, par le détroit de Makassar à l'est et par la mer de Java au sud.","L'île de Bornéo compte environ 20 millions d'habitants."],"src":"https://fr.vikidia.org/wiki/Born%C3%A9o","sw":"v","q":"Q36117","pays":["ID","MY","BN"],"c":["asie"]},"bornholm":{"n":"Bornholm","t":"île","km2":588,"pop":39632,"bref":["Bornholm est une île du Danemark située dans la mer Baltique à 36 km au sud-est de la province suédoise de Scanie et à 137 km à l'est des premières côtes danoises. D'une superficie de 589 km2 et peuplée par environ 39 545 habitants (2022), elle dépend de la région de Hovedstaden. Son chef-lieu est Rønne. Son Borgmester est Jacob Trøst (da).","L'archipel danois d'Ertholmene, situé au nord-est de l'île de Bornholm, ne fait pas partie d'une région ou d'une commune."],"src":"https://fr.wikipedia.org/wiki/Bornholm","sw":"w","q":"Q769680","pays":["DK"],"c":["europe"]},"buru":{"n":"Buru","t":"île","km2":8473,"pop":124000,"bref":["Buru (jadis écrit Boeroe) est la troisième plus grande île de l'archipel indonésien des Moluques, avec 9 505 km2. Elle est située en mer de Banda, à 68 km à l'ouest des îles d'Ambon et de Céram, ainsi qu'à 71 km au sud de Sanana, la plus méridionale des îles Sula. Sa rive nord borde la mer de Céram. L'île est montagneuse et couverte de forêts, et possède une étroite plaine côtière. La ville principale est Namlea, qui possède un port et un aéroport militaire. Directement au sud-est se trouve l'île d'Ambelau.","Administrativement, Buru et les îles voisines appartiennent à la province des Moluques (en indonésien Provinsi Maluku) ; elles sont divisées entre le kabupaten de Buru, dont le chef-lieu est Namlea, et le kabupaten de Buru du Sud, dont le chef-lieu est Namrole, la deuxième ville de l'île."],"src":"https://fr.wikipedia.org/wiki/Buru","sw":"w","q":"Q271030","pays":["ID"],"c":["asie"]},"capri":{"n":"Capri","t":"île","km2":10,"pop":12903,"bref":["Capri est une île située dans dans l'archipel Campanian Archipelago, sur la baie de Naples en Italie. Elle s'étend sur 10 km carrés. Capri est une île située dans la baie de Naples en mer Tyrrhénienne (mer Méditerranée). Elle n’est pas d’origine volcanique mais sédimentaire, elle est formée de terrains calcaires datant du Crétacé.","Elle est divisée en deux communes : 4 km carrés appartiennent à Capri et 6 km carrés appartiennent à Anacapri. Capri est connue pour sa beauté, Capri possède de nombreux centre d'intérêts comme La Marina Piccola, le belvédère de Tragara,la plus connue: la grotte bleue (Grotta Azzurra) une caverne sombre ou la mer prend une teinte bleu électrique éclatante grâce à la lumière du soleil, la Villa San Michele, la Villa Malaparte ainsi que les ruines des villas impériales romaines surtout construites par l'empereur romain Tibère, la plus connue étant la villa Jovis . Tibère y passe sans interruption les dix dernières années de son règne entre 27 et 37."],"src":"https://fr.vikidia.org/wiki/Capri","sw":"v","q":"Q173292","pays":["IT"],"c":["europe"]},"celebes":{"n":"Célèbes","t":"île","km2":174600,"pop":18455058,"bref":["Célèbes est une île majeure d´Indonésie. Elle fait partie des grandes îles de la Sonde, et en est la troisième par la superficie, avec une aire de 189 035 km2 qui la classe aussi onzième île du monde. Elle se situe à 120 kilomètres à l'est-sud-est de Bornéo, à 423 kilomètres au sud de Mindanao, aux Philippines, à 290 kilomètres au nord-nord-ouest de l'île de Florès et à 243 kilomètres à l'ouest d'Halmahera.."],"src":"https://fr.vikidia.org/wiki/C%C3%A9l%C3%A8bes","sw":"v","q":"Q3812","pays":["ID"],"c":["asie"]},"ceram":{"n":"Céram","t":"île","km2":70370,"pop":218993,"bref":["Céram, en indonésien Seram ou Pulau Seram, est une île d'Indonésie située dans l'archipel des Moluques en mer de Banda. C'est la plus grande et principale île de la province des Moluques en Indonésie. Elle est située juste au nord de la petite île d’Ambon et de quelques autres îles voisines, telles que Saparua, Haruku et les îles Banda."],"src":"https://fr.wikipedia.org/wiki/C%C3%A9ram","sw":"w","q":"Q185532","pays":["ID"],"c":["asie"]},"chios":{"n":"Chíos","t":"île","km2":843,"pop":51930,"bref":["Chios (en grec moderne Χίος / Chíos, en grec ancien Χίος / Khíos), ou anciennement Chio (en italien Chio), est une île et municipalité grecque de la mer Égée, proche de la Turquie dont elle est séparée par le détroit de Chios, d'une largeur moyenne de 11 kilomètres.","Avec les îles de Psará et d'Inousses, elle forme le district régional de Chios, dont la capitale, également appelée Chios ou Chora, compte en 2011 52 674 habitants.","Ses principaux revenus proviennent du tourisme, surtout culturel : elle compte de nombreux vestiges antiques comme le temple d'Apollon à Phana, ainsi que des monuments byzantins, comme le monastère de Néa Moni. Le sud produit également du mastic, gomme naturelle tirée de la résine du lentisque, ce qui vaut à Chios son surnom de « l'île du mastic »."],"src":"https://fr.wikipedia.org/wiki/Chios","sw":"w","q":"Q160483","pays":["GR"],"c":["europe"]},"corfou":{"n":"Corfou","t":"île","km2":626,"pop":100854,"bref":["Corfou, aussi appelé Corcyre, (en grec : Κέρκυρα / Kérkyra) est une île grecque dans l'archipel des îles Ioniennes, en mer Ionienne. Elle se trouve dans le Nord-Ouest de la Grèce, près de sa frontière avec l'Albanie.","Peuplée de plus de 100 000 habitants, Corfou est la plus grande île de l'archipel des îles Ioniennes et l'une des îles grecques les plus visitées. Les principales richesses de Corfou sont le tourisme et l'agriculture."],"src":"https://fr.vikidia.org/wiki/Corfou","sw":"v","q":"Q121378","pays":["GR"],"c":["europe"]},"crete":{"n":"Crète","t":"île","km2":8336,"pop":623065,"bref":["La Crète (en grec moderne : Κρήτη / Kríti ; en grec ancien : Κρήτη / Krḗtē), historiquement également appelée Candie (en latin, italien et vénitien: Candia), est la plus grande et la plus peuplée des îles de Grèce, et la cinquième plus grande île de la mer Méditerranée. Située à environ 100 km au sud du Péloponnèse et 300 km au sud-ouest de l'Anatolie, elle s'étend sur 8 450 km2 et son littoral de 1 046 km de long borde la mer Égée et sépare la mer de Crète, au nord, de la mer de Libye, au sud. Très allongée d'ouest en est (260 km) mais beaucoup plus étroite du nord au sud, elle s'étend sur trois unités de longitude différentes mais seulement sur une demi-latitude.","Avec toutes les petites îles et îlots qui l'entourent, elle forme la périphérie de Crète (Περιφέρεια Κρήτης), la plus méridionale des treize régions grecques et la cinquième plus peuplée. Sa capitale et plus grande ville est Héraklion, située sur la côte nord de l'île. Selon le recensement de la population de 2021, la périphérie comptait 624 408 habitants. Les régions voisines, de l'autre côté de la mer de Crète, sont le Dodécanèse au nord-est, les Cyclades au nord et le Péloponnèse au nord-ouest."],"src":"https://fr.wikipedia.org/wiki/Cr%C3%A8te","sw":"w","q":"Q34374","pays":["GR"],"c":["europe"]},"delos":{"n":"Délos","t":"île","km2":4,"pop":24,"bref":["Délos (en grec Δήλος) est une île des Cyclades, à proximité de Mykonos, dans la mer Égée, en Grèce.","Selon la mythologie grecque, Délos est le lieu de naissance des jumeaux Apollon et Artémis.","C'est une petite île inhabitée, manquant d'eau, et dépourvue de port, inaccessible dès que le vent se lève."],"src":"https://fr.vikidia.org/wiki/D%C3%A9los","sw":"v","q":"Q173148","pays":["GR"],"c":["europe"]},"fionie":{"n":"Fionie","t":"île","km2":2985,"pop":469724,"bref":["L'île de Fionie (en danois : Fyn) est en superficie la troisième île du Danemark métropolitain. Elle fait partie de la région du Danemark-du-Sud.","De nombreux manoirs et châteaux y sont situés. Ceux-ci possédant souvent des parcs et jardins bien entretenus, la Fionie est régulièrement désignée comme le Jardin du Danemark."],"src":"https://fr.wikipedia.org/wiki/Fionie","sw":"w","q":"Q26503","pays":["DK"],"c":["europe"]},"flores":{"n":"Florès","t":"île","km2":13540,"pop":1831000,"bref":["Florès, en indonésien Pulau Flores, est une île du sud de l'Indonésie faisant partie des Petites îles de la Sonde et située à 767 km au nord-ouest de l'Australie. L'île est longue de 360 kilomètres et fait 14 300 km2. Elle se trouve à 0,32 km à l'est de l'île de Rinca, à 0,7 km à l'ouest de l'île d'Adonara, dans les îles Solor, et à 45 km au nord de l'île de Sumba. À 25 km à l'ouest se situe l'île de Komodo. Son nom vient du portugais Flores qui signifie en français « fleurs ». Florès borde la mer homonyme au nord et la mer de Savu au sud."],"src":"https://fr.wikipedia.org/wiki/Flor%C3%A8s","sw":"w","q":"Q148440","pays":["ID"],"c":["asie"]},"fuerteventura":{"n":"Fuerteventura","t":"île","km2":1633,"pop":127043,"bref":["Fuerteventura, jadis appelée Fortaventure en français, est une île d'Espagne située dans l'océan Atlantique et faisant partie des îles Canaries. Deuxième île de cet archipel par sa taille, elle est celle qui est la plus proche du continent africain, à 97 kilomètres au nord-ouest des côtes du Sud marocain. L'île fait partie de la province de Las Palmas et sa capitale est Puerto del Rosario.","Peuplée depuis le Ier millénaire av. J.-C. par des populations berbères guanches venus d'Afrique, l'île a une population de 107 367 habitants en 2015, ce qui en fait la quatrième île la plus peuplée des îles Canaries. L'activité économique principale de Fuerteventura repose, depuis les années 1960, sur le secteur touristique dominé par l'exploitation des stations balnéaires."],"src":"https://fr.wikipedia.org/wiki/Fuerteventura","sw":"w","q":"Q192534","pays":["ES"],"c":["europe"]},"gotland":{"n":"Gotland","t":"île","km2":2968,"pop":60124,"bref":["Gotland est une île de Suède située en mer Baltique. Il s'agit de la plus grande île du pays. Le Gotland est aussi le nom du comté et de la commune présente sur l'île.","Autour de l'île de Gotland se trouvent plusieurs îles plus petites dont les plus importantes sont Fårö, Gotska Sandön, Stora Karlsö et Lilla Karlsö.","La seule ville de Gotland est Visby, ancienne ville hanséatique située sur la côte ouest, dont la vieille ville est inscrite au patrimoine mondial de l'UNESCO."],"src":"https://fr.wikipedia.org/wiki/Gotland","sw":"w","q":"Q1027830","pays":["SE"],"c":["europe"]},"gozo":{"n":"Gozo","t":"île","km2":67,"pop":31446,"bref":["Gozo (en maltais : Għawdex), appelé dans l'Antiquité Gaulos, est l'île secondaire de l'archipel maltais. Rabat, la ville la plus importante, siège du ministre de Gozo, se trouve au centre de l'île."],"src":"https://fr.wikipedia.org/wiki/Gozo","sw":"w","q":"Q170488","pays":["MT"],"c":["europe"]},"grande-canarie":{"n":"Grande Canarie","t":"île","km2":1560,"pop":863943,"bref":["La Grande Canarie (espagnol : Gran Canaria) est une île dans l'océan Atlantique faisant partie des îles Canaries, en Espagne. Deuxième île la plus peuplée de cet archipel, la plus grande ville, Las Palmas de Grande Canarie, est aussi la capitale de la province de Las Palmas et cocapitale avec Santa Cruz de Tenerife de la communauté autonome des îles Canaries. En outre, Las Palmas de Gran Canaria est la plus grande ville des îles Canaries et forme l'une des dix zones métropolitaines les plus peuplées d'Espagne.","La Grande Canarie est parfois comparée à un continent en miniature en raison de la diversité de ses paysages et de ses climats. La Grande Canarie, avec une superficie de 1 560 km2 et une altitude maximum de 1 961 m avec le Morro de la Agujereada, est la troisième plus grande île de l'archipel en étendue et en altitude."],"src":"https://fr.wikipedia.org/wiki/Grande_Canarie","sw":"w","q":"Q178925","pays":["ES"],"c":["europe"]},"grande-ile-de-terre-de-feu":{"n":"Grande Île de Terre de Feu","t":"île","km2":47992,"pop":200000,"bref":["La grande île de la Terre de Feu (en espagnol : Isla Grande de Tierra del Fuego, en français : Île grande de Terre du Feu), anciennement nommée Isla de Xativa, est une île de l'océan Pacifique, proche de l'extrémité sud de l'Amérique du Sud continentale dont elle est séparée par le détroit de Magellan et qui constitue la plus grande partie de l'archipel de la Terre de Feu.","Elle est partagée en deux par la frontière entre l'Argentine et le Chili qui court le long du 70e méridien ouest. Sa partie occidentale, 29 484,7 km2, soit 61,43 % de la superficie de l'île, appartient au Chili (région de Magallanes et de l'Antarctique chilien) ; tandis que sa partie orientale, 18 507,3 km2, soit 38,57 % de la superficie de l'île, appartient à l'Argentine (province de Terre de Feu)."],"src":"https://fr.wikipedia.org/wiki/Grande_%C3%AEle_de_la_Terre_de_Feu","sw":"w","q":"Q1674067","pays":["CL","AR"],"c":["amerique-sud"]},"grande-bretagne":{"n":"Grande-Bretagne","t":"île","km2":228938,"pop":65121000,"bref":["La Grande-Bretagne (en anglais : Great Britain ou plus rarement Britain ; en gallois : Prydain Fawr ; en scots : Great Breetain ; en cornique : Breten Veur, en gaélique écossais : Breatainn Mhòr ; en breton : Breizh-Veur) est une île au large du littoral nord-ouest de l'Europe continentale. Elle représente la majorité du territoire du Royaume-Uni. En son acception politique, ce toponyme désigne l'Angleterre, le pays de Galles et l'Écosse ainsi que la plupart des territoires insulaires contigus à l'exclusion de l'île de Man et des îles Anglo-Normandes.","Située à la jonction de l'Atlantique et de la mer du Nord, elle est séparée de l'Irlande par la mer d'Irlande et du continent par la Manche. C'est la plus grande île et la plus peuplée du continent européen."],"src":"https://fr.wikipedia.org/wiki/Grande-Bretagne","sw":"w","q":"Q23666","pays":["GB"],"c":["europe"]},"guam":{"n":"Guam","t":"île","km2":544,"pop":153836,"bref":["L’île de Guam est située dans le Sud-Est de la mer des Philippines, dans l’archipel des Mariannes, en Micronésie.","Sa superficie est de 549 km2. Sa capitale est Hagåtña (Agana en anglais , qui est avec le chamorro l'une des deux langues officielles de l'île)."],"src":"https://fr.vikidia.org/wiki/Guam","sw":"v","q":"Q16635","pays":["US"],"c":["amerique-nord"]},"hispaniola":{"n":"Hispaniola","t":"île","km2":76420,"pop":22261005,"bref":["Hispaniola, aussi appelée Haïti ou Saint-Domingue, est une île de l'archipel des Antilles, aujourd'hui partagée entre la République d'Haïti et la République dominicaine."],"src":"https://fr.vikidia.org/wiki/Hispaniola","sw":"v","q":"Q25277","pays":["DO","HT"],"c":["amerique-nord"]},"ibiza":{"n":"Ibiza","t":"île","km2":577,"pop":161485,"bref":["Ibiza est une des cinq îles Baléares, îles de la mer Méditerranée situées à l'est de la côte espagnole.","Souvent nommée « l’île aux deux visages », Ibiza, tranquille le jour, se métamorphose dès le coucher du soleil jusqu’au lever du jour en une discothèque géante.","Sa vie nocturne et les célébrités qui la fréquentent ont d'ailleurs fait sa notoriété.","Dans les années 1960, alors que le dictateur Franco était à la tête du pays, l’île fut un refuge pour les artistes, chanteurs, écrivains et accueillit de nombreux hippies.","Le tourisme a commencé à s'y développer dans les années 1960 et 1970 et n'a cessé ensuite de s'accroître : Ibiza accueille chaque année 2.4 millions de touristes et est l’une des principales destinations touristiques des sportifs professionnels, DJ, voyageurs, actrices et clubbers."],"src":"https://fr.vikidia.org/wiki/Ibiza","sw":"v","q":"Q52631","pays":["ES"],"c":["europe"]},"ile-alexandre-ier":{"n":"île Alexandre-Ier","t":"île","km2":49070,"pop":0,"bref":["L'île Alexandre-Ier, aussi appelée île Alexandre, terre Alexandre Ier, terre Alexandre, archipel Alexandre Ier ou archipel Alexandre, est une île de l'Antarctique d'une superficie de 49 069,9 km2 (378 kilomètres sur 200 environ et un littoral de 2 185 kilomètres) et située à l'ouest de la péninsule Antarctique, au niveau de la terre de Palmer. Plus grande île au sud du cercle antarctique et du continent et deuxième île la plus grande la moins peuplée au monde après l'île Devon au Canada, localisée au sud du Cône Sud et à l'ouest de la péninsule Antarctique, entre les plateformes de glace Georges VI au nord et Wilkins et Bach au sud, l'île Alexandre-Ier s'avance dans la mer de Bellingshausen et est reliée au continent et à différentes îles dont celles de Latady et de Charcot par les plateformes de glace. Au nord-est, on retrouve la baie de Marguerite."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Alexandre-Ier","sw":"w","q":"Q200223"},"ile-axel-heiberg":{"n":"île Axel Heiberg","t":"île","km2":43178,"pop":8,"bref":["L'île Axel Heiberg est une île du Canada située dans le passage du Nord-Ouest, à l'ouest de l'île d'Ellesmere, et fait partie de l'archipel Arctique. Elle est la 32e plus grande île du monde en superficie[réf. souhaitée], et la 7e du Canada. Elle fait 43 178 km2, soit l'équivalent du Danemark.","L'île est une composante des îles Sverdrup et des îles de la Reine-Élisabeth. L'île est connue pour ses fossiles datant de la période Éocène. En raison de l'absence de minéralisation dans de nombreux spécimens forestiers, la caractérisation traditionnelle de « fossilisation » est inopérante pour ces forêts et la « momification » pourrait constituer une description plus précise. Les archives fossiles fournissent des preuves solides que la forêt d'Axel Heiberg était une forêt humide de haute latitude. Un holotype de l'ammonite Otoceras gracile a été découvert dans les dépôts griesbachiens (Trias inférieur) de cette île."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Axel_Heiberg","sw":"w","q":"Q207666","pays":["CA"],"c":["amerique-nord"]},"ile-banks":{"n":"île Banks","t":"île","km2":70028,"pop":122,"bref":["L'île Banks, également appelée Terre de Banks (Banks Land), est une île de l'archipel Arctique, située dans le passage du Nord-Ouest. Elle est localisée à l'extrémité ouest de l'archipel des Territoires du Nord-Ouest.","Elle a été nommée ainsi par Sir William Edward Parry en 1820 lors de son voyage à la recherche du passage du Nord-Ouest en l'honneur de Sir Joseph Banks qui dirigeait la Royal Society.","Le parc national Aulavik a été créé au Nord de l'île dans le bassin de la rivière Thomsen, avec une faune particulièrement riche : bœufs musqués, loups arctiques, caribous (caribou de Peary et caribou des bois) ainsi que de nombreux oiseaux."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Banks","sw":"w","q":"Q200226","pays":["CA"],"c":["amerique-nord"]},"ile-bouvet":{"n":"île Bouvet","t":"île","km2":49,"pop":0,"bref":["L'île Bouvet (en norvégien Bouvetøya) est une île volcanique norvégienne inhabitée de l'océan Atlantique sud située à la limite nord de la plaque antarctique, à 1 695 km au nord du continent antarctique, à 1 859 km à l'est de l'île Montagu, dans l'archipel des îles Sandwich du Sud, et à 2 518 km au sud-sud-ouest du cap de Bonne-Espérance. Nommée d'après son découvreur français Jean-Baptiste Charles Bouvet de Lozier, elle est possession norvégienne depuis 1927."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Bouvet","sw":"w","q":"Q23408","pays":["NO"],"c":["europe"]},"ile-christmas":{"n":"île Christmas","t":"île","km2":135,"pop":1692,"bref":["L'île Christmas, en anglais Christmas Island et Territory of Christmas Island, littéralement en français « île de Noël », est un territoire extérieur australien situé dans l'est de l'océan Indien, à 345 km au sud-sud-ouest de la province de Java occidental (Indonésie), à 958 km à l'est-nord-est des îles Cocos et à 1 540 km des côtes nord-ouest de l'État d'Australie-Occidentale (North West Cape). L'île est longue de 21 km, large de 18 km (cette dernière dimension descendant à 5 km dans le centre de l'île) et couvre une superficie de 136 km2. La capitale est Flying Fish Cove.","L'Australie en a la souveraineté depuis 1958. Près des deux tiers de la superficie de l'île ont été déclarés parc national.","L'île abrite depuis 2001, avec une fermeture d'un an en 2018, un centre de rétention pour immigrés."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Christmas_(Australie)","sw":"w","q":"Q31063","pays":["AU"],"c":["oceanie"]},"ile-d-elbe":{"n":"île d'Elbe","t":"île","km2":223,"pop":32000,"bref":["L'île d'Elbe (en italien : isola d'Elba) est une île de la mer Méditerranée appartenant à l'archipel toscan et à la province de Livourne, en région Toscane (Italie). Elle est située près de 10 kilomètres à l'ouest des côtes de la péninsule italienne.","En hiver, environ 32 000 personnes vivent sur l'île dans sept communes différentes : Portoferraio, Campo nell'Elba (inclut l'île de Pianosa), Capoliveri, Marciana, Marciana Marina, Porto Azzuro et Rio."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_d'Elbe","sw":"v","q":"Q45328","pays":["IT"],"c":["europe"]},"ile-d-ellesmere":{"n":"île d'Ellesmere","t":"île","km2":196235,"pop":146,"bref":["L’Île d’Ellesmere (en anglais Ellesmere Island) est une île qui se situe au Canada, dans le territoire du Nunavut. L’île fait partie de l’archipel de la Reine-Élisabeth (en anglais Queen Élisabeth Islands). Elle est baignée par l’océan Arctique, le passage du Nord-Ouest, la mer de Lincoln et la baie de Baffin ; sa superficie est de 196 235 km2. C'est par la superficie la troisième île canadienne (après l'île de Baffin et l'île Victoria)."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_d'Ellesmere","sw":"v","q":"Q146841","pays":["CA"],"c":["amerique-nord"]},"ile-de-baffin":{"n":"île de Baffin","t":"île","km2":507451,"pop":13148,"bref":["L'île de Baffin, aussi nommée terre de Baffin (en inuktitut : ᕿᑭᖅᑖᓗᒃ, Qikiqtaaluk ; en vieux norrois : Helluland, « terre de la pierre plate ») est une des îles de l'archipel Arctique dans le passage du Nord-Ouest.","Elle dépend administrativement du territoire du Nunavut. C’est la plus grande île du Canada et la cinquième du monde, avec une superficie de 507 451 km2, soit une surface très légèrement supérieure à celle de l'Espagne. L'île a été nommée par le navigateur et explorateur William Edward Parry en hommage à l'explorateur William Baffin."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_de_Baffin","sw":"w","q":"Q81178","pays":["CA"],"c":["amerique-nord"]},"ile-de-jeju":{"n":"île de Jeju","t":"île","km2":1848,"pop":583284,"bref":["L’île de Jeju (Jeju-do) est une île sud-coréenne située en mer du Japon. Une distance de 84 km la sépare des côtes continentales rattachées à la province du Jeolla du Sud."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_de_Jeju","sw":"v","q":"Q29151","pays":["KR"],"c":["asie"]},"ile-de-l-ascension":{"n":"île de l'Ascension","t":"île","km2":88,"pop":806,"bref":["L'île d' Ascension est une île de l' océan Atlantique dans l' hémisphère sud. Elle s'étend sur environ 90 km2.","L'île est située sur la dorsale médio-atlantique, c'est une île volcanique dont la base, par 3 200 m de fond, fait 60 km de diamètre. Le volcan culmine à 859 mètres au-dessus du niveau de la mer, à la Green Mountain également ou The Peak. Ce sommet date d'1,2 million d'années.","Ascension a été découverte en 1501, par le navigateur portugais Joao da Nova. Elle est « redécouverte » le jour de l'Ascension de 1503 par le navigateur portugais Alfonso d'Albuquerque, qui donne alors le nom actuel.","Pour surveiller l'ex-empereur Napoléon Ier qu'ils retiennent comme prisonnier dans l'île \"voisine\" de Sainte-Hélène les Britanniques y établissent une garnison."],"src":"https://fr.vikidia.org/wiki/Ascension_(%C3%8Ele)","sw":"v","q":"Q46197"},"ile-de-la-navasse":{"n":"île de la Navasse","t":"île","km2":5,"pop":0,"bref":["L'île de la Navasse (en anglais : Navassa Island ; en créole haïtien : Zilè Lanavaz) est un îlot inhabité des Antilles situé en mer des Caraïbes, dans le passage de la Jamaïque, à 57 kilomètres à l'ouest d'Haïti. L'île de la Navasse fait partie des îles mineures éloignées des États-Unis mais est revendiquée par Haïti."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_de_la_Navasse","sw":"w","q":"Q25359","pays":["US"],"c":["amerique-nord"]},"ile-de-marajo":{"n":"île de Marajó","t":"île","km2":40100,"pop":419744,"bref":["L'île de Marajó, en portugais Ilha de Marajó, est une île côtière située au Brésil, dans l'État du Pará, entre l'Amazone, le Rio Tocantins et l'océan Atlantique. Elle est considérée comme la plus grande île côtière au Brésil et l'une des plus grandes îles fluviales du monde."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_de_Maraj%C3%B3","sw":"w","q":"Q193264","pays":["BR"],"c":["amerique-sud"]},"ile-de-paques":{"n":"île de Pâques","t":"île","km2":164,"pop":4800,"bref":["L'île de Pâques, ou Rapa Nui, est une île du Sud-Est de l'océan Pacifique, abordée et peuplée par des Polynésiens vers 1200. Elle est ainsi nommée car elle fut découverte par des Européens pour la première fois le jour de Pâques, en l'an 1722. Ses habitants s'appellent les Pascuans. Elle est célèbre pour ses statues impressionnantes, les moais. Appartenant au Chili, l'île est un territoire spécial rattaché à la région de Valparaiso et sa population est d'environ 7 750 habitants. Le chef-lieu est Hanga Roa."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_de_P%C3%A2ques","sw":"v","q":"Q14452","pays":["CL"],"c":["amerique-sud"]},"ile-de-taiwan":{"n":"île de Taïwan","t":"île","km2":35883,"pop":23894394,"bref":["Taïwan ou Formose est une île de 35 801 km² située en mer de Chine méridionale, au sud-est de la Chine continentale, au sud-ouest de la Corée et du Japon et au nord des Philippines. L'île borde à l'ouest le détroit de Taïwan et à l'est la mer des Philippines. L'île est très montagneuse et son point culminant atteint 3 952 m au Yu Shan. Elle constitue la majeure partie de la république de Chine, ce qui explique que celle-ci soit appelée de façon usuelle Taïwan."],"src":"https://fr.vikidia.org/wiki/Ta%C3%AFwan_(%C3%AEle)","sw":"v","q":"Q22502","pays":["TW"],"c":["asie"]},"ile-de-vancouver":{"n":"île de Vancouver","t":"île","km2":32134,"pop":864864,"bref":["L’île de Vancouver (en anglais : Vancouver Island) est une grande île côtière du Nord-Ouest Pacifique d'Amérique du Nord. Elle fait partie de la Colombie-Britannique (Canada). Séparée du Canada continental par trois détroits, c'est la plus grande île de la côte ouest de l'Amérique avec 32 134 km2, soit, à titre de comparaison, une superficie légèrement supérieure à celle de la Belgique."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_de_Vancouver","sw":"w","q":"Q170479","pays":["CA"],"c":["amerique-nord"]},"ile-de-wight":{"n":"île de Wight","t":"île","km2":380,"pop":140459,"bref":["L'île de Wight est une île qui se situe sur la côte sud de l'Angleterre (Royaume-Uni) sur la Manche.","Son nombre d'habitants est de 136 252. Sa densité est de 358,6 hab/km². Sa capitale, Newport, se trouve au milieu de l'île. Sa superficie est de 381 km².","C'est une île magnifique, avec ses plages et son beau paysage.","50°40′51″N 1°16′51″O / 50.68083, -1.28083"],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_de_Wight","sw":"v","q":"Q9679","pays":["GB"],"c":["europe"]},"ile-devon":{"n":"île Devon","t":"île","km2":55247,"pop":0,"bref":["L'île Devon est une île du Canada située dans le passage du Nord-Ouest et est par conséquent une des composantes de l'archipel Arctique."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Devon","sw":"w","q":"Q186841","pays":["CA"],"c":["amerique-nord"]},"ile-du-nord":{"n":"île du Nord","t":"île","km2":113729,"pop":3519800,"bref":["L'île du Nord (en anglais : North Island et en maori de Nouvelle-Zélande : Te Ika-a-Maui ce qui signifie « Le poisson de Maui ») est une des deux principales îles de la Nouvelle-Zélande, l'autre étant l'île du Sud dont elle est séparée par le détroit de Cook. Elle se situe en mer de Tasman, mais ses rivages septentrionaux et orientaux sont baignés par l'océan Pacifique. Plusieurs villes importantes sont situées sur cette île, notamment Auckland, la ville la plus peuplée du pays, et Wellington, la capitale. Environ 76 % de la population de la Nouvelle-Zélande, soit 3 148 400 habitants, réside sur l'île du Nord. On la connait également sous le nom d'île Fumante."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_du_Nord","sw":"w","q":"Q118863","pays":["NZ"],"c":["oceanie"]},"ile-du-prince-de-galles":{"n":"île du Prince-de-Galles","t":"île","km2":33339,"pop":0,"bref":["L'île du Prince-de-Galles, située dans le Nunavut, est une île de l'archipel Arctique située dans le passage du Nord-Ouest. Elle est localisée au sud des îles de la Reine-Élisabeth, entre l'île Victoria à l'ouest et l'île Somerset à l'est."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_du_Prince-de-Galles_(Canada)","sw":"w","q":"Q207925","pays":["CA"],"c":["amerique-nord"]},"ile-du-sud":{"n":"île du Sud","t":"île","km2":150437,"pop":1115800,"bref":["L'île du Sud (en anglais : South Island et en maori de Nouvelle-Zélande : Te Waipounamu) est l'une des deux îles principales de la Nouvelle-Zélande, l'autre étant l'île du Nord dont elle est séparée par le détroit de Cook.","Son nom maori est Te Waipounamu, qui signifie : « La rivière des pierres vertes », en raison de la néphrite que les Maoris y avaient découverte. Au XIXe siècle, plusieurs cartes la désignaient sous le nom de Middle Island ou New Munster, le nom île du Sud ou New Leinster étant attribué à ce qui est aujourd'hui l'île Stewart.","On la connait également sous le nom d'île de Jade.","L'île du Sud est la douzième plus grande île au monde. Située en mer de Tasman, elle a ses rives orientales qui ouvrent sur l'océan Pacifique. Le long de sa côte occidentale se trouvent les Alpes du Sud dont le mont Cook est le point culminant avec 3 724 m d'altitude. Elle est sujette à de nombreux et importants séismes, notamment le séisme de 2010 et celui de 2011 ayant partiellement détruit la ville de Christchurch."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_du_Sud","sw":"w","q":"Q120755","pays":["NZ"],"c":["oceanie"]},"ile-howland":{"n":"île Howland","t":"île","km2":3,"pop":0,"bref":["L'île Howland, en anglais Howland Island, est une île inhabitée des États-Unis située dans l'océan Pacifique et constituant un territoire non organisé et non incorporé. Elle est protégée depuis 1974 sous le nom de refuge faunique national de l'Île-Howland géré par l'United States Fish and Wildlife Service. L'exploitation de son guano, une tentative de colonisation et une brève occupation militaire constituent les seules présences humaines sur cette île. Sa végétation herbacée est le lieu de vie et de nidification de nombreux oiseaux marins et ses fonds marins comportent une barrière de corail."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Howland","sw":"w","q":"Q131305","pays":["US"],"c":["amerique-nord"]},"ile-ioujny":{"n":"île Ioujny","t":"île","km2":33275,"pop":2716,"bref":["L'île Ioujny (en russe : Южный остров) est l'île du sud de l'archipel de Nouvelle-Zemble, au nord de la Russie. L'île se trouve en mer de Kara, mais sa côte occidentale ouvre sur la mer de Barents. Sa superficie est de 33 275 km2, équivalente à la taille de la Moldavie. Elle est donc la troisième plus grande île de la Russie, les autres étant Sakhaline et l'île Severny, de laquelle elle est séparée par le détroit de Matotchkine.","Originellement terre des Nénètses, l'île a été évacuée dans les années 1950 pour y faire des essais nucléaires.","Elle est connue pour ses grandes colonies d'oiseaux de mer. Ses paysages sont surtout de type toundra.","Elle fait politiquement partie de l'oblast d'Arkhangelsk, comme le reste de l'archipel."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Ioujny","sw":"w","q":"Q212806","pays":["RU"],"c":["asie","europe"]},"ile-jan-mayen":{"n":"île Jan Mayen","t":"île","km2":377,"pop":18,"bref":["Jan Mayen ou île Jan Mayen est une île norvégienne située en mer de Norvège à sa limite avec la mer du Groenland. Une distance de 459 kilomètres à travers la mer du Groenland sépare l'île des côtes orientales du Groenland. L'Islande (phare de Fontur) se trouve à 543 kilomètres en direction du sud-ouest et la côte continentale la plus proche est à 954 kilomètres vers l'est. (Nordskot, comté de Nordland, Norvège).","L'île est intégrée au royaume de Norvège depuis février 1930 et a le statut de territoire."],"src":"https://fr.vikidia.org/wiki/Jan_Mayen","sw":"v","q":"Q14056","pays":["NO"],"c":["europe"]},"ile-jarvis":{"n":"île Jarvis","t":"île","km2":6,"pop":0,"bref":["L'île Jarvis, en anglais Jarvis Island, est une île corallienne inhabitée appartenant aux États-Unis et située dans le centre de l’océan Pacifique à 382 km au sud-ouest de London, sur l'île Christmas (Kiribati), et à 2 409 km au sud d'Honolulu (Hawaï). Elle fait partie des îles de la Ligne et se situe à 40 km au sud de l'équateur. Pour les enquêtes statistiques, elle fait partie des îles mineures éloignées des États-Unis.","L'île Jarvis est un territoire non incorporé et non organisé des États-Unis. Elle est administrée par le United States Fish and Wildlife Service par sa qualité de National Wildlife Refuge."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Jarvis","sw":"w","q":"Q62218","pays":["US"],"c":["amerique-nord"]},"ile-kotelny":{"n":"île Kotelny","t":"île","km2":23200,"pop":0,"bref":["L'île Kotelny (en russe : остров Котельный, ostrov Kotelny), fait partie des îles de Nouvelle-Sibérie (groupe d'Anjou) situé dans l'océan Arctique, au nord des côtes de la Sibérie orientale entre la mer des Laptev et la mer de Sibérie orientale. Sur le plan administratif, elle est rattachée à la république de Sakha en Russie.","Kotelny (11 665 km²) est reliée à l'île Faddeïev voisine (5 300 km²) par un pont de sable qui s'est formé au cours des siècles précédents : la Terre de Bunge (6 100 km²). L'ensemble, d'une surface de 23 200 km2, fait partie des 50 plus grandes îles de la planète. La Terre de Bunge est peu élevée (8 m maximum) et est périodiquement submergée. Le point culminant de l'île est le Malakatyne-Tas (374 mètres)."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Kotelny","sw":"w","q":"Q648391","pays":["RU"],"c":["asie","europe"]},"ile-melville":{"n":"île Melville","t":"île","km2":42149,"pop":0,"bref":["L'île Melville est une île située dans le passage du Nord-Ouest, au nord des îles Victoria et Banks, à l'ouest de l'île Bathurst et à l'est-sud-est de l'île du Prince-Patrick. L'île fait partie des îles de la Reine-Élisabeth. Sa superficie est de 42 149 km², soit une taille légèrement plus élevée que la Suisse.","L'île, comme l'ensemble de l'archipel Arctique, est réputée pour ses diverses formations géologiques. Il n'y a aucune communauté humaine établie en permanence sur l'île."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Melville_(Nunavut_et_les_Territoires_du_Nord-Ouest)","sw":"w","q":"Q134116","pays":["CA"],"c":["amerique-nord"]},"ile-severny":{"n":"île Severny","t":"île","km2":47079,"pop":0,"bref":["L'île Severny (en russe : Северный остров) est l'île du Nord de l'archipel de Nouvelle-Zemble, au nord de la Russie. L'île se trouve en mer de Kara, la mer de Barents baignant sa côte occidentale. Elle a une superficie de 46 904 km2, ce qui en fait la deuxième île de la Russie, après Sakhaline et devant Ioujny ainsi que la 29e plus grande île de la planète. Sa taille est équivalente à celle de la République dominicaine."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Severny","sw":"w","q":"Q217362","pays":["RU"],"c":["asie","europe"]},"ile-somerset":{"n":"île Somerset","t":"île","km2":24786,"pop":0,"bref":["L'île Somerset est une île de l'archipel Arctique située dans le passage du Nord-Ouest, au nord de la péninsule Boothia dont elle n'est séparée que par le détroit de Bellot. Ce dernier a une largeur variant de un à deux kilomètres. Dépendant administrativement du Nunavut (région de Qikiqtaaluk), l'île a une superficie de 24 786 km², ce qui fait d'elle la 46e plus grande île au monde et la 12e au Canada. L'île est inhabitée."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Somerset_(Canada)","sw":"w","q":"Q212219","pays":["CA"],"c":["amerique-nord"]},"ile-southampton":{"n":"île Southampton","t":"île","km2":41214,"pop":834,"bref":["L'île Southampton est une île située dans le passage du Nord-Ouest. Ses rives méridionales et occidentales bordent la baie d'Hudson. L'île fait partie du territoire du Nunavut et de l'archipel Arctique. Elle est appelée Salliq par les Inuits.","Sa superficie est de 41 214 km2, quasiment équivalente à la taille de la Suisse. C'est la 34e île plus grande du monde et la 9e île canadienne. Le seul habitat de l'île est Coral Harbour, 712 habitants (recensement 2001), appelé en Inuit Salliq.","Les deux sanctuaires ornithologiques, East Bay Bird Sanctuary et Harry Gibbons Bird Sanctuary, situés sur l'île sont des sites importants de reproduction pour l'Oie des neiges (Anser caerulescens caerulescens).","Historiquement, l'île Southampton est connue pour son ancienne population, désormais éteinte, les Sadlermiuts, qui étaient les derniers représentants du Tuniit, la culture de Dorset. Le Tuniit est une pré-culture inuite, officiellement ethniquement et culturellement éteinte quand, en 1902, une épidémie occidentale balaya les Sallirmiut en quelques semaines."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Southampton","sw":"w","q":"Q207751","pays":["CA"],"c":["amerique-nord"]},"ile-victoria":{"n":"île Victoria","t":"île","km2":217291,"pop":1875,"bref":["L'île Victoria (en anglais : Victoria Island) est une île du Canada située dans le passage du Nord-Ouest, au-delà du cercle arctique, à cheval entre le Nunavut et les Territoires du Nord-Ouest (tiers ouest de l'île). Par sa superficie de 217 291 kilomètres carrés, l'île se classe deuxième du Canada, troisième d'Amérique et neuvième du monde, juste après la Grande-Bretagne.","L’île a été nommée ainsi en 1839 en l'honneur de la reine Victoria."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Victoria","sw":"w","q":"Q158129","pays":["CA"],"c":["amerique-nord"]},"irlande":{"n":"Irlande","t":"île","km2":84421,"pop":7185600,"bref":["L'Irlande, aussi surnommée l'île d'Émeraude, est une île située à l'ouest de la Grande-Bretagne, entre la mer d'Irlande (qui la sépare de la Grande-Bretagne et, plus précisément, de l'Angleterre) et l'océan Atlantique.","L'un des lieux les plus beaux d'Irlande est constitué des îles d'Aran. Cet archipel est constitué de trois îles: Inishmore, Inishmaan et Inisheer. Ce petit archipel est marqué par l'océan, tant du point de vue de la géographie physique que de l'aspect culturel et traditionnel. Autrefois les marins d'Aran affrontaient les eaux dangereuses sur de fragiles esquifs d'osier doublés de toile bitumée. La pêche est l'activité économique principale. Le nom même d'Aran vient du poisson le Hareng qui constitue encore de nos jours l'alimentation principale des habitants de ces îles."],"src":"https://fr.vikidia.org/wiki/Irlande_(%C3%AEle)","sw":"v","q":"Q22890","pays":["IE","GB"],"c":["europe"]},"java":{"n":"Java","t":"île","km2":128297,"pop":160293748,"bref":["Java est une île d'Indonésie de la mer de Java située entre Sumatra, Bornéo et Bali. Elle baigne au sud l'océan Indien, et à l'est la mer de Bali."],"src":"https://fr.vikidia.org/wiki/Java_(%C3%AEle)","sw":"v","q":"Q3757","pays":["ID"],"c":["asie"]},"kyushu":{"n":"Kyushu","t":"île","km2":36782,"pop":13061879,"bref":["Kyūshū est une île du Japon située dans le Sud-Ouest du pays. Elle est la plus méridionale des quatre grandes îles japonaises. L'île est orientée nord-sud et mesure 331 kilomètres de son extrémité septentrionale à son extrémité méridionale. Sa plus longue dimension ouest-est s'élève à 257 kilomètres. L'île est bordée au sud-est par la mer des Philippines, à l'ouest par la mer de Chine orientale et au nord-ouest par la mer du Japon. La côte nord-est borde la mer intérieure de Seto. L'île s'étend sur une superficie de 35 640 kilomètres carrés pour une population de 12,48 millions d'habitants."],"src":"https://fr.vikidia.org/wiki/Ky%C5%ABsh%C5%AB","sw":"v","q":"Q13987","pays":["JP"],"c":["asie"]},"la-passion-clipperton":{"n":"La Passion–Clipperton","t":"île","km2":9,"pop":0,"bref":["L'île de Clipperton, aussi appelée île Clipperton, Clipperton ou encore île de la Passion, est une possession française composée d'un unique atoll et située dans l'océan Pacifique, à 10 667 kilomètres à l'ouest-nord-ouest de Paris, à 5 408 kilomètres à l'est-nord-est de Papeete (Tahiti) et à 1 081 kilomètres au sud-ouest du Mexique.","L'îlot, composé d'un récif corallien couvert de guano, est difficile d'accès et inhabité (c'est une île déserte). L'atoll a la particularité d'abriter l'unique lagon d'eau douce du monde."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_de_Clipperton","sw":"v","q":"Q161258","pays":["FR"],"c":["europe"]},"la-reunion":{"n":"La Réunion","t":"île","km2":2512,"pop":889679,"bref":["La Réunion est une île française de 2 512 km2 située dans l'Ouest de l'océan Indien, à l'est de l'Afrique : plus précisément dans l'archipel des Mascareignes, à près de 700 kilomètres à l'est de Madagascar et à un peu plus de 200 kilomètres au sud-ouest de l'île Maurice, terre la plus proche. Son climat est tropical.","Ancienne colonie française, sa devise (issue de cette période de son histoire) est Florebo quocumque ferar, qui est traduisible par \"je fleurirai partout où je serai plantée/portée\".","Cette île est un département français d'outre-mer (DOM) depuis 1946 et également une région administrative française (à département unique) depuis 2003, dont le chef-lieu est Saint-Denis. Ses habitants, au nombre de 911 682 (en 2022), sont les Réunionnais. Sa densité de population est de 325 hab./km2."],"src":"https://fr.vikidia.org/wiki/La_R%C3%A9union","sw":"v","q":"Q17070","pays":["FR"],"c":["europe"]},"lanzarote":{"n":"Lanzarote","t":"île","km2":791,"pop":163467,"bref":["Lanzarote, autrefois appelée en français Lancerotte, en guanche Titerogakat, est une île d'Espagne située dans l'océan Atlantique ; elle est l'une des sept îles principales des îles Canaries. Administrativement, l'île fait partie de la province de Las Palmas dans la communauté autonome des îles Canaries. Peuplée de 142 517 habitants, elle est la troisième île des Canaries par la population, après Tenerife et Grande Canarie. Couvrant 845,94 km2, elle est la quatrième île de l'archipel par la superficie. Arrecife est le siège du cabildo insulaire.","Depuis 1993, l'île est reconnue réserve mondiale de biosphère par l'Unesco. Dans le centre-ouest de l'île se trouve le parc national de Timanfaya, l'une des principales attractions de l'île."],"src":"https://fr.wikipedia.org/wiki/Lanzarote","sw":"w","q":"Q182432","pays":["ES"],"c":["europe"]},"lesbos":{"n":"Lesbos","t":"île","km2":1641,"pop":83800,"bref":["La mer Égée désigne la partie orientale de la Méditerranée comprise entre la Grèce à l'ouest et la Turquie à l'est. Elle est reliée à la mer Noire par la mer de Marmara et ses détroits : les Dardanelles et le Bosphore. La mer Égée comprend de grandes îles et de nombreux archipels.","Son nom lui vient d'Égée, roi légendaire d'Athènes qui s'est jeté à l'eau, croyant son fils Thésée mort.","La mer Égée a été le cadre du développement de la civilisation égéenne du deuxième millénaire av. J-C, c'est-à-dire de la civilisation mycénienne et de celle de Troie."],"src":"https://fr.vikidia.org/wiki/Mer_%C3%89g%C3%A9e","sw":"v","q":"Q128087","pays":["GR"],"c":["europe"]},"lombok":{"n":"Lombok","t":"île","km2":5435,"pop":3352988,"bref":["Lombok est une île volcanique d'Indonésie, située en mer de Bali entre les îles de Bali et de Sumbawa. Elle fait partie des Petites îles de la Sonde. Sa superficie est de 4 739 km2.","Sa ville principale est Mataram, qui est aussi la capitale de la province des Petites îles de la Sonde occidentales.","Comme en témoigne le cratère sur la moitié nord de Lombok, l'île fut le foyer d'un volcan géant qui entra en éruption en 1257.","L'île fait partie de la réserve de biosphère de Rinjani-Lombok, reconnue par l'Unesco en 2018."],"src":"https://fr.wikipedia.org/wiki/Lombok","sw":"w","q":"Q7564","pays":["ID"],"c":["asie"]},"long-island":{"n":"Long Island","t":"île","km2":3566,"pop":7804968,"bref":["Long Island est une très grande île de 3 600 km2, située au large des côtes du Connecticut, qui appartient en partie à la ville de New York. C’est une île résidentielle, commerciale et touristique."],"src":"https://fr.vikidia.org/wiki/Long_Island","sw":"v","q":"Q18438","pays":["US"],"c":["amerique-nord"]},"lucon":{"n":"Luçon","t":"île","km2":109965,"pop":53336134,"bref":["Luçon est la plus grande île des Philippines. Située au nord de l'archipel, elle compte environ 50 millions d'habitants, soit plus d'un tiers de la population totale du pays. C'est aussi là que se trouve la capitale, Manille.","Luçon est divisée en huit régions, elles-mêmes divisées en 38 provinces."],"src":"https://fr.vikidia.org/wiki/Lu%C3%A7on_(Philippines)","sw":"v","q":"Q125384","pays":["PH"],"c":["asie"]},"maduraenne":{"n":"Maduraenne","t":"île","km2":4429,"pop":3630000,"bref":["Madura (gentilé : Madurais) est une île d'Indonésie, située en mer de Java au large de l'île éponyme, à moins de trois kilomètres de Surabaya, capitale de la province de Java oriental.","Sa superficie est de 5 250 km2 et sa population d'environ 4 millions d'habitants."],"src":"https://fr.wikipedia.org/wiki/Madura","sw":"w","q":"Q208134","pays":["ID"],"c":["asie"]},"majorque":{"n":"Majorque","t":"île","km2":3620,"pop":949047,"bref":["Majorque se situe en Espagne, c'est une île espagnole. 873 400 habitants y habitent. Sa superficie est de 3 625.75 km2. Cette île se situe dans la mer Méditerranée. La plus grande ville sur Majorque est Palma de Majorque. Majorque se trouve à 550 km de Madrid."],"src":"https://fr.vikidia.org/wiki/Majorque","sw":"v","q":"Q8828","pays":["ES"],"c":["europe"]},"mindanao":{"n":"Mindanao","t":"île","km2":97530,"pop":27021036,"bref":["Mindanao est une île de la mer des Philippines située dans le Sud de l'archipel des Philippines. Elle baigne au nord, à l'est et au sud-est la mer des Philippines, au nord-ouest la mer de Sulu et au sud la mer de Célèbes. C'est en surface la deuxième île du pays. En 2020, elle comptait environ 26 252 442 habitants, dont environ un quart de musulmans.","Mindanao est divisée en six régions, elles-mêmes divisées en 27 provinces. Sa plus grande ville est Davao."],"src":"https://fr.vikidia.org/wiki/Mindanao","sw":"v","q":"Q124873","pays":["PH"],"c":["asie"]},"minorque":{"n":"Minorque","t":"île","km2":692,"pop":100323,"bref":["Minorque (en catalan : Menorca /məˈnɔɾkə/ ; en espagnol : Menorca ; du latin Balearis Minor) est l'une des quatre îles Baléares habitées, en mer Méditerranée, qui fut appelée Nura (îlot du feu) par les Phéniciens en l'honneur de leur dieu Baal.","Plus petite que sa voisine Majorque, au nord-est, d'où son nom, rocailleuse, battue par les vents, culminant à El Toro, à 358 m d'altitude et haut lieu de randonnée dans les îles de Méditerranée, c'est la plus préservée des quatre îles Baléares.","Située entre 39° 47' N et 40° 00' N, 3° 52' E et 4° 24' E, voisine de l'Île de l'Air, Minorque a été reconnue en tant que réserve de biosphère par l'UNESCO le 8 octobre 1993 et possède de nombreux monuments mégalithiques : navetes, taulas et talaiots."],"src":"https://fr.wikipedia.org/wiki/Minorque","sw":"w","q":"Q52636","pays":["ES"],"c":["europe"]},"montserrat":{"n":"Montserrat","t":"île","km2":102,"pop":5440,"bref":["Montserrat est une île volcanique des Petites Antilles, située à environ 60 km au nord-ouest de la Guadeloupe.","Montserrat est un territoire d'outre-mer du Royaume-Uni. Elle a pour capitale Plymouth.","Sa superficie est de 102 km2 et sa population d'environ 5 000 habitants."],"src":"https://fr.vikidia.org/wiki/Montserrat_(Antilles)","sw":"v","q":"Q13353","pays":["GB"],"c":["europe"]},"morotai":{"n":"Morotai","t":"île","km2":20270,"pop":54876,"bref":["Morotai est une île de la mer de Halmahera, faisant partie de la province indonésienne des Moluques du Nord. Elle est située au nord-est de Halmahera, à 2° 19′ N, 128° 32′ E, ce qui en fait l'île la plus septentrionale de l'archipel des Moluques du Nord. Administrativement, Morotai constitue un kabupaten."],"src":"https://fr.wikipedia.org/wiki/Morotai","sw":"w","q":"Q19146","pays":["ID"],"c":["asie"]},"naxos":{"n":"Naxos","t":"île","km2":428,"pop":17930,"bref":["Naxos est une île grecque de l'archipel des Cyclades, en mer Égée.","C'est la plus grande des Cyclades (428 km²). Elle compte 18 000 habitants.","Le chef-lieu est la petite ville portuaire de Naxos (6 500 habitants). Le reste de la population est réparti dans la campagne et les villages environnants."],"src":"https://fr.vikidia.org/wiki/Naxos","sw":"v","q":"Q188527","pays":["GR"],"c":["europe"]},"north-uist":{"n":"North Uist","t":"île","km2":303,"pop":1254,"bref":["North Uist (en gaélique écossais : Uibhist a Tuath) est une île appartenant aux Hébrides extérieures en Écosse. Sa population est de 1 271 habitants d'après le recensement de 2001. Elle est reliée par une chaussée surélevée à Benbecula via Grimsay, à Berneray, et à Baleshare. À l'exception du sud-est, l'île est très plate, plus de sa moitié étant submergée."],"src":"https://fr.wikipedia.org/wiki/North_Uist","sw":"w","q":"Q662158","pays":["GB"],"c":["europe"]},"nouvelle-bretagne":{"n":"Nouvelle-Bretagne","t":"île","km2":36520,"pop":513926,"bref":["La Nouvelle-Bretagne (en anglais : New Britain ; en tok pisin : Niu Briten) autrefois nommée Nouvelle-Poméranie, est une île de la mer des Salomon, située dans l'archipel Bismarck dont elle est la plus grande terre. Elle fait partie de la Papouasie-Nouvelle-Guinée."],"src":"https://fr.wikipedia.org/wiki/Nouvelle-Bretagne","sw":"w","q":"Q59771","pays":["PG"],"c":["oceanie"]},"nouvelle-guinee":{"n":"Nouvelle-Guinée","t":"île","km2":785753,"pop":11300000,"bref":["La Nouvelle-Guinée est une île d'Océanie, située au nord de l'Australie. Une moitié de l'île fait partie de l'Indonésie et l'autre moitié (celle orientale) représente la plus grande partie de la Papouasie-Nouvelle-Guinée (qui inclut aussi l'archipel Bismarck, l'île Bougainville, et beaucoup d'autres petites îles)."],"src":"https://fr.vikidia.org/wiki/Nouvelle-Guin%C3%A9e","sw":"v","q":"Q40285","pays":["ID","PG"],"c":["asie","oceanie"]},"oahu":{"n":"Oahu","t":"île","km2":1545,"pop":976372,"bref":["Oahu, en hawaïen Oʻahu, est la troisième île par la taille de l’archipel d'Hawaï et la plus peuplée des îles formant l’État d'Hawaï. Elle se situe à 42 km à l'ouest-nord-ouest de Molokai et à 117 km à l'est-sud-est de Kauai. Elle couvre une superficie de 1 545,34 km2, en incluant l’île de Ford et les îlots de la baie de Kaneohe et de la côte est. Elle a 336 kilomètres de côtes.","L’île s’est formée sous l’action conjointe des volcans Wai’anae et Ko’olau, laissant une grande vallée entre les deux. Le plus haut sommet est le mont Ka’ala qui culmine à 1 225 mètres au-dessus du niveau de la mer.","L’île est la résidence de près d'un million de personnes, soit environ 75 % de la population de l’État d'Hawaï. En partie à cause de cela, O’ahu a été surnommée « The Gathering Place » (« le point de rassemblement »)."],"src":"https://fr.vikidia.org/wiki/Oahu","sw":"v","q":"Q131347","pays":["US"],"c":["amerique-nord"]},"okinawa":{"n":"Okinawa","t":"île","km2":1208,"pop":1224726,"bref":["L'île Okinawa (en japonais 沖縄本島, Okinawa hontō, littéralement « île principale Okinawa » ; en okinawaïen 沖縄, Uchinā) est l'île principale de l'archipel Okinawa, de la préfecture d'Okinawa et de l'archipel des Îles Ryūkyū.","Sa ville principale est Naha, capitale de la préfecture. Elle est située à 1 554 km à vol d'oiseau au sud-ouest de Tokyo."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Okinawa","sw":"w","q":"Q600614","pays":["JP"],"c":["asie"]},"rennell-est":{"n":"Rennell Est","t":"île","km2":370,"pop":800,"bref":["Rennell Est est la section méridionale de l'île de Rennell, aux Salomon dans l'océan Pacifique.","Cet espace, dont le lac Tegano fait partie, couvre 37 000 hectares et 3000 lieux nautiques. Cet ancien lagon est le plus grand du Pacifique, il possède de nombreuses îles de calcaire et abrite plusieurs espèces animales et végétales endémiques.","La végétation y est dense et peut atteindre les 20 mètres de hauteur.","En 1998, Rennell Est est inscrit au patrimoine mondial de l'UNESCO."],"src":"https://fr.wikipedia.org/wiki/Rennell_Est","sw":"w","q":"Q852433","pays":["SB"],"c":["oceanie"]},"rhodes":{"n":"Rhodes","t":"île","km2":1400,"pop":127613,"bref":["Rhodes (en grec ancien Ῥόδος / Rhódos) est une île grecque, la plus grande de l'archipel du Dodécanèse (les « Douze îles »). Elle est située au sud-est de la mer Égée, à moins de 20 km de Bodrum (ancienne Halicarnasse), en Turquie.","L'île compte environ 100 000 habitants."],"src":"https://fr.vikidia.org/wiki/Rhodes","sw":"v","q":"Q43048","pays":["GR"],"c":["europe"]},"rugen":{"n":"Rügen","t":"île","km2":926,"pop":67526,"bref":["Rügen est la plus grande île allemande. Elle est située au large de la côte du Mecklembourg-Poméranie-Occidentale dans la mer Baltique. Sa superficie est de 926 km2 et sa population était de 64 376 habitants en 2021. Avec ses îles avoisinantes plus petites, Hiddensee et Ummanz, elle est administrée par l'arrondissement de Poméranie-Occidentale-Rügen.","Les villes principales sont Bergen avec 20 000 habitants et la ville portuaire de Sassnitz avec 11 000 habitants.","Dans le sud-est de l'île, se trouvent les trois stations balnéaires les plus connues, Binz, Sellin et Göhren."],"src":"https://fr.wikipedia.org/wiki/R%C3%BCgen","sw":"w","q":"Q3237","pays":["DE"],"c":["europe"]},"saaremaa":{"n":"Saaremaa","t":"île","km2":2672,"pop":29753,"bref":["Saaremaa est une île estonienne située dans la mer Baltique.","Elle est au nord du golfe de Riga et au sud de la deuxième plus grande île estonienne, Hiiumaa. D'une superficie de 2673 km², Saaremaa est la plus grande île d'Estonie. On y compte plus de 36 000 habitants. La plus grande ville de l'île est Kuressaare."],"src":"https://fr.vikidia.org/wiki/Saaremaa","sw":"v","q":"Q951302","pays":["EE"],"c":["europe"]},"saba":{"n":"Saba","t":"île","km2":13,"pop":2270,"bref":["Saba est une île néerlandaise de la mer des Caraïbes qui se situe dans le nord des Petites Antilles, à l’est de Porto Rico. Surnommée la Reine immaculée (anglais : The Unspoiled Queen), son chef-lieu est The Bottom.","Saba forme une municipalité néerlandaise à statut particulier depuis le 10 octobre 2010 (Îles BES), à la suite de la dissolution de l’ancien État autonome de la fédération des Antilles néerlandaises dont elle faisait partie."],"src":"https://fr.wikipedia.org/wiki/Saba","sw":"w","q":"Q25528"},"saint-eustache":{"n":"Saint-Eustache","t":"île","km2":21,"pop":3293,"bref":["Saint-Eustache est une île de la mer des Caraïbes et un territoire néerlandais d'outre-mer, faisant partie des Petites Antilles. Située entre Saba (au nord-ouest), Saint-Christophe (au sud-est) et Saint-Martin (au nord) ; son chef-lieu est Oranjestad.","Saint-Eustache est depuis le 10 octobre 2010 une des trois municipalités néerlandaises à statut particulier (néerlandais : openbare lichamen), avec Bonaire et Saba, formant ensemble les Pays-Bas caribéens (néerlandais : Caribisch Nederland) ou îles BES (îles de Bonaire, Saint-Eustache et Saba - néerlandais : BES-eilanden), à la suite de la dissolution de l’ancien État autonome de la Fédération des Antilles néerlandaises dont elle faisait partie."],"src":"https://fr.wikipedia.org/wiki/Saint-Eustache_(Antilles)","sw":"w","q":"Q26180"},"saint-martin":{"n":"Saint-Martin","t":"île","km2":87,"pop":72239,"bref":["Saint-Martin est une île des Antilles (Amérique), à 250 km au nord de la Guadeloupe.","La moitié nord est française et la moitié sud est néerlandaise.","Saint-Martin compte environ 75 000 habitants."],"src":"https://fr.vikidia.org/wiki/Saint-Martin_(%C3%AEle)","sw":"v","q":"Q25596","pays":["FR","SX"],"c":["europe","amerique-nord"]},"sainte-helene":{"n":"Sainte-Hélène","t":"île","km2":121,"pop":3924,"bref":["L'île de Sainte-Hélène est une île britannique située dans l'océan Atlantique Sud, à 1 283 km au sud-est de l'île d'Ascension et à 1 859 km à l'ouest des côtes de l'Angola méridional. C'est ici que Napoléon est mort en 1821.","Avec deux autres îles de l'océan Atlantique Sud, elle constitue un territoire britannique d'outre-mer appelé Sainte-Hélène, Ascension et Tristan da Cunha."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_de_Sainte-H%C3%A9l%C3%A8ne","sw":"v","q":"Q34497"},"saipan":{"n":"Saïpan","t":"île","pop":48220,"bref":["Saipan, parfois francisé en Saïpan (Code International : MP.SA), est la plus grande des îles du Commonwealth des îles Mariannes du Nord rattachées aux États-Unis depuis 1944, une chaîne de 15 îles faisant partie de l’archipel des îles Mariannes dans la mer des Philippines."],"src":"https://fr.wikipedia.org/wiki/Saipan","sw":"w","q":"Q51679","pays":["US"],"c":["amerique-nord"]},"sakhaline":{"n":"Sakhaline","t":"île","km2":72492,"pop":673100,"bref":["Sakhaline est la plus grande île de la mer d'Okhotsk et de Russie. Elle borde à l'ouest la mer du Japon. Située à l'extrême est de la Russie, Sakhaline se trouve à environ 6 400 km au nord-est de Moscou."],"src":"https://fr.vikidia.org/wiki/Sakhaline","sw":"v","q":"Q7792","pays":["RU"],"c":["asie","europe"]},"samos":{"n":"Samos","t":"île","km2":476,"pop":32642,"bref":["Sámos (en grec moderne : Σάμος) est une île grecque de la mer Égée, proche de l'Asie mineure et située à 70 kilomètres au sud-ouest d'Izmir en Turquie. Depuis la réforme du programme Clisthène I, de 2019, l'île est composée de deux dèmes (municipalités) et fait partie du district régional de la périphérie d'Égée-Septentrionale. Son chef-lieu est la ville de Sámos. Elle compte 32,977 habitants (2011 ; Samiens ou Samiotes) pour 476 km2 de superficie.","L'île est célèbre pour ses poteries rouges, réputées dans l'Antiquité ; son artisanat d'art avec ses bronzes et ses bijoux, son bois de construction, son tabac, son vin (cépage malvoisie), ses fruits, ses roses et son huile d'olive.","Elle est aussi le siège d'un évêché du patriarcat œcuménique de Constantinople : la Métropole de Samos et Icarie."],"src":"https://fr.wikipedia.org/wiki/S%C3%A1mos","sw":"w","q":"Q156882","pays":["GR"],"c":["europe"]},"santorin":{"n":"Santorin","t":"île","km2":79,"pop":17430,"bref":["Santorin (en grec : Σαντορίνη, prononcé \"sa(n)dorini\", officiellement Θήρα, ou Théra, prononcé \"thira\" avec \"th\" prononcé comme un \"s\" avec le bout de la langue sur les deux dents du dessus, comme en anglais) est une île du sud de la mer Égée, située à 233 km au sud-est d'Athènes, la capitale de la Grèce. C'est la plus grande île du petit archipel qui porte son nom (archipel de Santorin) et qui est occupée par une caldeira (ancien volcan). Elle est l'île habitée la plus méridionale des Cyclades, et mesure environ 73 km² de superficie pour une population de 15 550 habitants d'après le recensement de 2011. Cependant l'île la plus au sud des Cyclades est Pacheiá, mais elle ne compte aucun habitant."],"src":"https://fr.vikidia.org/wiki/Santorin","sw":"v","q":"Q129296","pays":["GR"],"c":["europe"]},"seeland":{"n":"Seeland","t":"île","km2":7031,"pop":2302074,"bref":["L'île de Seeland, ou Zeeland, est la plus grande île du Danemark et où se concentre la majorité de la population. C'est dans l'est de cette île habitée par 2 625 206 habitants (chiffres de 2024) qu'est située Copenhague, la capitale du Danemark.","L'île forme la majorité du territoire de la région de Sjælland, à laquelle elle donne son nom. La région de la capitale se trouve aussi (en grande partie) sur l'île, mais constitue une entité administrative séparée."],"src":"https://fr.wikipedia.org/wiki/Seeland_(Danemark)","sw":"w","q":"Q25535","pays":["DK"],"c":["europe"]},"sercq":{"n":"Sercq","t":"île","km2":6,"pop":562,"bref":["Sercq est une petite île Anglo-Normande, de 5,4 km2, située dans la Manche, très proche de Guernesey.","Sercq est l'une des seigneuries normandes du bailliage de Guernesey, État dépendant de la Couronne britannique."],"src":"https://fr.wikipedia.org/wiki/Sercq","sw":"w","q":"Q3405693","pays":["GG"],"c":["europe"]},"shikoku":{"n":"Shikoku","t":"île","km2":18297,"pop":3845534,"bref":["Shikoku est une île japonaise située au sud de Honshū. C'est la plus petite des quatre principales îles japonaises et sa particularité est de n'avoir aucun volcan, contrairement aux trois autres îles. Shikoku la seule région à ne pas posséder le Shinkansen ."],"src":"https://fr.vikidia.org/wiki/Shikoku","sw":"v","q":"Q13991","pays":["JP"],"c":["asie"]},"siberut":{"n":"Siberut","t":"île","km2":3829,"pop":30000,"bref":["Siberut est l'île la plus grande et la plus septentrionale de l'archipel des îles Mentawaï, à 150 km au large de la côte ouest de Sumatra, dans l'océan Indien, en Indonésie. Elle a été reconnue réserve de biosphère par l'UNESCO en 1981 et est habitée par l'ethnie Mentawaï dite des « hommes-fleurs »."],"src":"https://fr.wikipedia.org/wiki/Siberut","sw":"w","q":"Q826041","pays":["ID"],"c":["asie"]},"socotra":{"n":"Socotra","t":"île","km2":3796,"pop":42842,"bref":["Socotra est une île au large du Yémen située dans l'océan indien, connue pour ses paysages qui ressemblent à un monde extraterrestre, en raison de sa biodiversité, l'archipel est classé au patrimoine."],"src":"https://fr.vikidia.org/wiki/Socotra","sw":"v","q":"Q82859","pays":["YE"],"c":["asie"]},"south-uist":{"n":"South Uist","t":"île","km2":320,"pop":1754,"bref":["South Uist (en gaélique écossais : Uibhist a' Deas) est une île de l'archipel des Hébrides extérieures en Écosse. Sa population, au recensement de 2001, était de 1 818 habitants, majoritairement catholiques.","L'ouest de l'île est surtout formé de machair, avec une plage continue de sable, alors que la côte est est montagneuse avec les pics de Beinn Mhor (620 m) et Hecla (606 m).","Au nord-ouest se trouve depuis 1957 une zone d'essai pour les missiles, Deep Sea Range."],"src":"https://fr.wikipedia.org/wiki/South_Uist","sw":"w","q":"Q841059","pays":["GB"],"c":["europe"]},"spitzberg":{"n":"Spitzberg","t":"île","km2":39044,"pop":2642,"bref":["Spitzberg (en norvégien : Spitsbergen) est la plus grande île de l'archipel de Svalbard, en Norvège. Elle est située en mer du Groenland, qui baigne les côtes ouest et nord de l'île, tandis que le littoral oriental est bordé par la mer de Barents.","Elle a pour superficie 39 044 km2 et pour population 2 921 habitants. Sa capitale est Longyearbyen et son point culminant est Newtontoppen, à 1 717 m. Avec l'île aux Ours, elle est la seule île habitée du Svalbard. Seuls 2% du territoire sont occupés humainement.","L'île a été découverte en 1596 par le néerlandais Willem Barentsz qui partait pour la Chine via le passage du Nord-Est.","Au Spitzberg, le soleil de minuit, est visible du 19 avril au 23 août. Par contre la nuit polaire règne du 28 octobre au 14 février. En été seule une mince bande côtière est libérée de la neige et de la glace. Même en été les coups de blizzard et les tempêtes de neige sont fréquents."],"src":"https://fr.vikidia.org/wiki/Spitzberg","sw":"v","q":"Q21162","pays":["NO"],"c":["europe"]},"stromboli":{"n":"Stromboli","t":"île","km2":13,"pop":450,"bref":["Le Stromboli est un volcan d'Italie situé dans les îles Éoliennes, en mer Thyrénienne. L'île Stromboli se trouve à 56 km au nord de la côte septentrionale de la Sicile. Le volcan atteint une altitude de 924 mètres. Ses éruptions nocturnes très lumineuses lui ont valu le surnom de « phare de la Méditerranée ». Administrativement, l'île dépend de la commune de Lipari."],"src":"https://fr.vikidia.org/wiki/Stromboli","sw":"v","q":"Q131148","pays":["IT"],"c":["europe"]},"sumatra":{"n":"Sumatra","t":"île","km2":473481,"pop":60000000,"bref":["Sumatra est une île de l'Ouest de l'Indonésie située sur l'équateur. Son nom vient de Samudra, la capitale du sultanat de Pasai dans le nord de l'île (en langue malaise, samudera signifie « océan »). Avec ses 473 481 km2, elle est la sixième plus grande île du monde, tout en étant légèrement supérieure à la Papouasie-Nouvelle-Guinée et à la Suède. En 2021, le recensement comptait 59 185 500 habitants.","Les principales langues parlées sont : aceh, batak, malais, minangkabau. La majorité des habitants sont musulmans, mais Sumatra compte aussi des protestants, des catholiques, des bouddhistes, des hindous.","Sur un territoire qui s'étend des marais de la côte est de l'île jusqu'au piémont de la chaîne des Bukit Barisan vivent des populations dispersées en petits groupes qui se désignent elles-mêmes sous le nom d'Orang Darat, c'est-à-dire « peuples de la terre ». chasseurs-cueilleurs semi-nomades, ces populations cultivent le sagou et troquent des produits de la forêt contre du sel et des métaux fournis par leurs voisins paysans sédentaires, Batak, Minangkabau et Malais."],"src":"https://fr.wikipedia.org/wiki/Sumatra","sw":"w","q":"Q3492","pays":["ID"],"c":["asie"]},"tahiti":{"n":"Tahiti","t":"île","km2":1042,"pop":178133,"bref":["Tahiti est une île de la Polynésie française (collectivité d'outre-mer) située dans l'océan Pacifique Sud. Elle fait partie de l’archipel de la Société et du groupe des îles du Vent. L'île se trouve à 3 811 kilomètres à l'est-nord-est de la Nouvelle-Zélande, à 4 083 km au sud de Hawaï et à 7 334 km à l'ouest du point le plus proche du continent américain et situé dans le Chili méridional (péninsule Taitao, région d'Aysén).","C'est une île haute et montagneuse, d'origine volcanique, entourée d'un récif de corail. Son point culminant est le mont Orohena avec une altitude de 2 241 mètres. Ce sommet est aussi le plus haut de la Polynésie française et même de l'océan Pacifique Sud (hors mers bordières). Il est aussi l'un des sommets les plus isolés du monde et le plus isolé de l'océan Pacifique."],"src":"https://fr.vikidia.org/wiki/Tahiti","sw":"v","q":"Q42000","pays":["FR"],"c":["europe"]},"terre-neuve":{"n":"Terre-Neuve","t":"île","km2":108860,"pop":479538,"bref":["Terre-Neuve est une île du golfe du Saint-Laurent au large du Canada. Sa côte nord-est baigne la mer du Labrador. Avec une partie de la péninsule du Labrador, elle forme la province canadienne de Terre-Neuve-et-Labrador."],"src":"https://fr.vikidia.org/wiki/Terre-Neuve","sw":"v","q":"Q48335","pays":["CA"],"c":["amerique-nord"]},"timor":{"n":"Timor","t":"île","km2":30777,"pop":3368735,"bref":["Timor est une île de l'archipel indonésien, dans l'est des Petites îles de la Sonde. Elle est bordée à l'ouest par la mer de Savu, au nord-est par la mer de Banda, et au sud-est par la mer de Timor. En malais, timur signifie « orient », mais ce n'est pas nécessairement l'étymologie du nom de l'île.","La moitié orientale de Timor forme la république du Timor oriental, tandis que la moitié occidentale fait partie de la province indonésienne des Petites îles de la Sonde orientales couvrant quatre circonscriptions (appelées kabupaten) ,(Belu, Kupang, Timor central Sud et Timor central Nord), ainsi qu'une division administrative appelée kota (Kupang)."],"src":"https://fr.wikipedia.org/wiki/Timor","sw":"w","q":"Q83067","pays":["ID","TL"],"c":["asie"]},"trinite":{"n":"Trinité","t":"île","km2":4768,"pop":1267145,"bref":["La Trinité, ou Trinidad, est une île du sud-est des Antilles, à proximité de la côte vénézuélienne. Avec l'île voisine de Tobago, elle forme depuis 1962 la république de Trinité-et-Tobago. Plus grande île du pays, elle héberge aussi la capitale nationale, Port-d'Espagne. D’une superficie de 4 748 km2, elle se situe à 15 km au nord-est de la punta Sabaneta (es), au Venezuela.","Espagnole depuis sa découverte en 1498 — lors du 3e voyage de Christophe Colomb — jusqu'à 1797 (elle formait une province à part entière du royaume d’Espagne), elle est envahie (es) par un escadron britannique commandé par Henry Harvey qui en fait une colonie britannique. La perte de l'île au profit du Royaume-Uni est actée par le traité d'Amiens en 1802."],"src":"https://fr.wikipedia.org/wiki/Trinit%C3%A9_(%C3%AEle)","sw":"w","q":"Q128323","pays":["TT"],"c":["amerique-nord"]},"wetar":{"n":"Wetar","t":"île","km2":2600,"pop":6127,"bref":["Wetar est une île d'Indonésie située en mer de Banda et faisant partie de la province des Moluques. C'est la plus grande des îles Barat Daya. L'île fait 130 km d'est en ouest et 45 km du nord au sud. Sa superficie est de 3600 km². Le point culminant de l'île est à 1 412 m. C'est une île frontalière d'Indonésie.","Les principales villes de Wetar sont Lioppa dans le nord-ouest, Wasiri dans le nord, Arwala dans le nord-est, Masapun dans l'est et Ilwaki dans le sud.","Administrativement, Wetar fait partie du kabupaten des Moluques du Sud-Ouest."],"src":"https://fr.wikipedia.org/wiki/Wetar","sw":"w","q":"Q615657","pays":["ID"],"c":["asie"]}},
"deserts":{"ad-dahna":{"n":"Ad-Dahna","t":"désert","bref":["Le désert d’ad-Dahna est la partie centrale du désert d'Arabie, un couloir de terrain sablonneux formant une sorte d'arc, qui relie le désert du Nefoud (Al Jawf), au Rub al-Khali (al-Hassa), sur plus de 1 000 km de long, pour 40 à 80 km de large, sur une superficie d'environ 65 000 km2.","Ad-Dahna est formé de hautes dunes de sable s'étalant horizontalement, appelées veines (en arabe : عروق), surtout de couleur rouge, car contenant des oxydes de fer.","Dans une partie karstique, à l'est, au plateau calcaire de Summan, dans une zone d'exploitation des sables, sous la surface, se trouvent de dahls, trous, cavités souterraines, labyrinthes complexes, remplis de structures cristallines, de stalactites et de stalagmites. Certaines grottes ont des entrées minuscules conduisant dans un dédale de passages parfois de plusieurs kilomètres."],"src":"https://fr.wikipedia.org/wiki/Ad-Dahna","sw":"w","q":"Q1973934","pays":["SA"],"c":["asie"]},"arabah":{"n":"Arabah","t":"désert","bref":["L’Arabah, ou Arava (en arabe : وادي عربة translittéré Wādī ʻAraba, en hébreu : הָֽעֲרָבָה, translittéré Ha'Arava) est une partie de la vallée du rift du Jourdain située entre la mer Morte au nord et le golfe d'Aqaba au sud. Elle forme une partie de la frontière terrestre entre Israël à l'ouest, et la Jordanie à l'est."],"src":"https://fr.wikipedia.org/wiki/Arabah","sw":"w","q":"Q626682","pays":["IL","JO"],"c":["asie"]},"aralkum":{"n":"Aralkum","t":"désert","km2":38000,"bref":["L'Aralkum (mot composé d'Aral (russe : Ара́л) et du turc kum (кум), sable) est un nouveau désert, qui s'est formé là où la mer d'Aral a été asséchée. Ce désert de sable et de sel s'étend sur le Kazakhstan et sur l'Ouzbékistan, au Nord-Ouest des déserts du Karakoum et du Kyzylkoum. Le désert est aussi appelé Akkoum (russe : Аккум) (Désert blanc).","L'équilibre des flux d'eau de la Mer d'Aral a été rompu en raison de grands projets d'irrigation menés du temps de l'URSS. Après la construction du barrage de Kokaral en 2005, la petite mer d'Aral a été restaurée, mais la grande Aral reste à sec, ce qui accroit la superficie d'Aralkum.","À la suite de la désertification, la biodiversité de la région a chuté à 200 espèces de plantes et d'animaux. La flore poussant actuellement sur le lit desséché de la mer a commencé à se développer à partir de 1960. Elle compte 34 familles de plantes, de 134 genres et de 300 variétés. Les représentants les plus répandus sont : le Salicornia europaea, le Suaeda crassifolia, le Tripolium vulgare dans les sols limoneux, ainsi que le Suaeda acuminata et l'Atriplex fominii dans les sols sableux."],"src":"https://fr.wikipedia.org/wiki/Aralkum","sw":"w","q":"Q280158","pays":["UZ","KZ"],"c":["asie","europe"]},"desert-arabique":{"n":"Désert Arabique","t":"désert","km2":221900,"bref":["Le désert Arabique ou désert oriental d'Égypte est un désert de l’Est de l’Égypte situé à l’extrémité Nord-Est du Sahara. Il est délimité par le delta du Nil au nord, le canal de Suez et la mer Rouge à l’est, la vallée du Nil à l’ouest et le désert de Nubie au sud, au-delà du lac Nasser.","En Égypte, la région est qualifiée de désert oriental par opposition au désert occidental d'Égypte (désert Libyque), tandis que le désert du Sud peut être qualifié de désert méridional d'Égypte."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_Arabique","sw":"w","q":"Q624170","pays":["EG","ER","SD","ET"],"c":["afrique"]},"desert-d-arabie":{"n":"désert d'Arabie","t":"désert","km2":2330000,"bref":["Le désert d'Arabie s'étend sur la plus grande partie de la péninsule arabique. Son climat extrêmement sec a longtemps freiné le développement de sa population. L'exploitation du pétrole a entrainé un développement important des pays de la région depuis le milieu du XXIe siècle."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_d'Arabie","sw":"v","q":"Q208299","pays":["SA","OM","YE","IQ","JO","AE"],"c":["asie"]},"desert-d-atacama":{"n":"désert d'Atacama","t":"désert","km2":1813005,"bref":["Le désert d'Atacama est un désert situé dans les régions d'Antofagasta et d'Atacama, dans le Nord du Chili, en Amérique du sud. Cette zone couvre entre environ 100 000 et 130 000 km², selon les frontières choisies. Cette barrière naturelle est composée notamment de volcans, de lagunes turquoises, de geysers et de vallées encaissées. On trouve aussi dans ce désert le plus grand dépôt salin du Chili, le salar d'Atacama. Celui-ci abrite un des plus importants gisements de lithium au monde.","Beaucoup d’observations spatiales et de recherches astronomiques ont lieu dans ce désert. On y a même construit un des plus gros observatoires du monde","C'est le principal désert du Chili et, par la superficie, le vingtième désert de la planète."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_d'Atacama","sw":"v","q":"Q47141","pays":["CL"],"c":["amerique-sud"]},"desert-danakil":{"n":"désert Danakil","t":"désert","km2":136956,"bref":["Le désert Danakil est un désert situé dans la Corne de l'Afrique, au nord-est de l'Éthiopie et au sud de l'Érythrée, dans le district du sud de la mer Rouge."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_Danakil","sw":"w","q":"Q141513","pays":["ER","DJ","ET"],"c":["afrique"]},"desert-de-badain-jaran":{"n":"désert de Badain Jaran","t":"désert","km2":50000,"bref":["Le désert de Badain Jaran (chinois simplifié : 巴丹吉林沙漠 ; pinyin : Bādānjílín Shāmò) est un désert de Chine qui s'étend sur les provinces du Gansu, de Ningxia et de Mongolie Intérieure et couvre une surface de 49 000 kilomètres carrés.","Le désert détient les dunes les plus hautes du monde, s'élevant jusqu'à 500 mètres. Ces dunes se maintiennent dans cette région ventée grâce à la présence de sources souterraines, alimentées par des eaux de fonte qui parcourent des centaines de kilomètres à travers des failles rocheuses.","Entre ces dunes, il existe une centaine de lacs, qui sont à l'origine du nom en mongol, le désert des « lacs mystérieux ».","Le 26 juillet 2024, le « désert de Badain Jaran – tours de sable et lacs » est inscrit sur la liste du patrimoine mondial par l'UNESCO."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Badain_Jaran","sw":"w","q":"Q939033","pays":["CN"],"c":["asie"]},"desert-de-b-edow":{"n":"désert de Błędów","t":"désert","km2":32,"bref":["Le désert de Błędów (Pustynia Błędowska en polonais) est une zone sableuse entre Błędów (pl) (partie de la ville de Dąbrowa Górnicza, Haute-Silésie) et le village de Klucze (ville d'Olkusz), en Pologne."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_B%C5%82%C4%99d%C3%B3w","sw":"w","q":"Q117750","pays":["PL"],"c":["europe"]},"desert-de-chalbi":{"n":"Désert de Chalbi","t":"désert","bref":["Le désert de Chalbi est un petit désert du nord du Kenya, près de la frontière avec l'Éthiopie. Il est situé à l'est du Lac Turkana. La ville de Marsabit en est le centre urbain le plus proche.","Le désert de Chalbi résulte de l'assèchement du lac Chalbi il y a environ 10 000 ans."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Chalbi","sw":"w","q":"Q1774690","pays":["KE"],"c":["afrique"]},"desert-de-chihuahua":{"n":"désert de Chihuahua","t":"désert","km2":362600,"bref":["Le désert de Chihuahua (en anglais : Chihuahuan Desert, en espagnol : Desierto Chihuahuense) est l’un des déserts les plus riches du point de vue de la diversité biologique. Il s’étend sur 647 000 km2 à travers le nord du Mexique (Chihuahua, Coahuila, Nuevo León, Durango, Zacatecas et San Luís Potosí) et le sud-ouest des États-Unis (Arizona, Nouveau-Mexique et Texas). C'est le deuxième plus grand désert des Amériques et le plus grand d'Amérique du Nord.","Le désert de Chihuahua est bordé à l'ouest par le désert de Sonora, le plateau du Colorado et la vaste chaîne de la Sierra Madre occidentale, ainsi que par les basses terres du nord-ouest de la Sierra Madre orientale. Près de 90 % de sa surface est située au Mexique. Ce désert est relativement jeune, puisqu'il n'existe que depuis 8 000 ans."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Chihuahua","sw":"w","q":"Q855658","pays":["US","MX"],"c":["amerique-nord"]},"desert-de-gibson":{"n":"désert de Gibson","t":"désert","km2":155000,"bref":["Le désert de Gibson (en anglais Gibson Desert) est un désert d'Australie-Occidentale formant une écorégion terrestre définie par le WWF. Il fait partie de l'écozone australasienne et du biome des déserts et terres arbustives xériques.","Il couvre une zone de plus 155 000 km2 de collines couvertes d'herbes sèches. Il est situé au sud du Grand Désert de Sable et au nord du grand désert de Victoria. Son altitude moyenne est de 500 m. Il n'est habité que par des aborigènes qui vivent dans les régions les plus élevées. On y trouve des kangourous et des émeus. Il forme une partie du plateau de l'Australie occidentale et s'étend, entre le lac Disappointment et le lac Macdonald (en), le long du Tropique du Capricorne. Il doit son nom à l'explorateur Alfred Gibson qui mourut en essayant de le traverser en 1874 en compagnie de l'explorateur Ernest Giles."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Gibson","sw":"w","q":"Q272577","pays":["AU"],"c":["oceanie"]},"desert-de-gobi":{"n":"désert de Gobi","t":"désert","km2":2354460,"bref":["Le désert de Gobi est une vaste étendue désertique située entre la Chine et la Mongolie. Sa superficie est de 1 300 000 km². C'est l'un des plus vastes déserts au monde.","Il est essentiellement composé de pierres.","Les températures y sont extrêmes : environ +38 °C en été et −25 °C en hiver.","Les Mongols forment un peuple qui vit dans le désert de Gobi. Ils pratiquent l'élevage nomade et vivent dans des yourtes. Ils se sédentarisent de plus en plus près des villes.","Le désert de Gobi est également connu dans les légendes mongoles pour l'Olgoï-Khorkhoï, un animal fictif ressemblant à un ver géant."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_de_Gobi","sw":"v","q":"Q42070","pays":["CN","MN"],"c":["asie"]},"desert-de-judee":{"n":"désert de Judée","t":"désert","bref":["Le désert de Judée ou désert de Juda (en hébreu : מִדְבַּר יְהוּדָה, Midbar Yəhūdā, en arabe : صحراء يهودا, Saḥrāʔ Yahūdan) est également connu en hébreu sous le nom de Yeshimon (יְשִׁימוֹן) signifiant « désert » ou « terre sauvage ». C'est un désert situé à l'est de la Palestine, entre la crête des monts de Judée (à l'est de Jérusalem) jusqu'à la mer Morte, soit partiellement en Israël (District Sud) et en Cisjordanie (territoires palestiniens)."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Jud%C3%A9e","sw":"w","q":"Q2046004","pays":["IL","PS"],"c":["asie"]},"desert-de-nubie":{"n":"désert de Nubie","t":"désert","km2":400000,"bref":["Le désert de Nubie, en arabe صحراء النوبة, Şaḩrā’ an Nūbyah, est la partie orientale du désert du Sahara, au nord-est du Soudan et au sud-est de l'Égypte mesurant 407 000 km2 de superficie. Il est délimité par le Nil à l'ouest, l'Itbay bordant la mer Rouge à l'est, le désert Arabique au nord et des savanes au sud."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Nubie","sw":"w","q":"Q464909","pays":["SD"],"c":["afrique"]},"desert-de-simpson":{"n":"désert de Simpson","t":"désert","km2":176500,"bref":["Le désert de Simpson forme une écorégion terrestre définie par le WWF occupant le centre de l'Australie. Il fait partie du biome des déserts et terres arbustives xériques et de l'écozone australasienne.","Il s'étend à la limite de trois des États australiens occupant le sud-est du Territoire du Nord ainsi que les espaces limitrophes du Queensland et de l'Australie-Méridionale. Sa superficie est évaluée selon les sources de 143 000 km² à 300 000 km². Ses contours incertains sont fixés à l'ouest par le cours du fleuve Finke, au nord par la chaine de montagnes des MacDonnell Ranges, à l'est par les fleuves Georgina et Diamantina et au sud par le Lac Eyre. Dans ce désert, les précipitations annuelles sont faibles (comprises entre 150 et 200 mm) et il peut s'écouler plusieurs années sans pluie."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Simpson","sw":"w","q":"Q211839","pays":["AU"],"c":["oceanie"]},"desert-de-sonora":{"n":"désert de Sonora","t":"désert","km2":310800,"bref":["Le désert de Sonora aussi appelé désert de Gila est une vaste zone désertique située entre le Sud-Ouest des États-Unis et le Nord-Ouest du Mexique, en Amérique du Nord.","C'est le plus grand désert d'Amérique du Nord. Il est connu pour la flore exceptionnelle qu'il abrite et ses paysages. Beaucoup de touristes le visitent entre mars et avril.","Divers peuples habitent dans le désert de Sonora : les Yaquis en Arizona et les Tarahumaras dans l'État mexicain de Sonora."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_de_Sonora","sw":"v","q":"Q189429","pays":["US","MX"],"c":["amerique-nord"]},"desert-de-syrie":{"n":"désert de Syrie","t":"désert","km2":518000,"bref":["Le désert de Syrie (arabe : بادية الشام, Bādiyat al-Shām) appelé aussi simplement la Badiya est une zone de désert chaud, de semi-désert et de steppe située dans le nord du désert d'Arabie et de la péninsule arabique, s'étendant de la Jordanie à l’Irak en passant par la Syrie. Ce grand arc steppique parcouru par les nomades, d'une superficie d'environ 520 000 km2, est très rocailleux et compte peu de reliefs.","Par abus de langage, le désert de Syrie est également appelé la Chamiyé, terme qui désigne le domaine steppique sur la rive droite de l’Euphrate, limité au sud par la ligne joignant Damas à Anah, dans la vallée de l’Euphrate au sud d’Abu Kamal."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Syrie","sw":"w","q":"Q339162","pays":["SY","JO","IQ","SA"],"c":["asie"]},"desert-de-tanami":{"n":"désert de Tanami","t":"désert","km2":184500,"bref":["Le désert de Tanami est un désert du nord de l’Australie. C’est un terrain rocailleux avec de petites collines.","Le désert de Tanami est l’un des plus isolés et des plus arides endroits de la Terre. Il était la frontière nord du Territoire du Nord et n’a pas été exploré avant le XXe siècle. Il est traversé par la Tanami Track (ou Tanami Road).","Tanami, est aussi le nom d’une des régions de l’Interim Biogeographic Regionalisation for Australia (IBRA)."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Tanami","sw":"w","q":"Q674262","pays":["AU"],"c":["oceanie"]},"desert-des-mojaves":{"n":"désert des Mojaves","t":"désert","km2":124000,"bref":["Le désert des Mojaves, de Mojave, ou simplement désert Mojave, est une grande étendue désertique d'environ 40 000 km2. Il est situé dans l'ouest des États-Unis, dans le sud de la Californie essentiellement, mais il déborde sur les états voisins du Nevada au nord, et de l'Arizona à l'est. Ce désert appartient au même ensemble géologique que le Grand Bassin ou que le désert de Sonora. Son nom est emprunté à un peuple amérindien, les Mohaves. C'est un désert d'abri, bordé par les montagnes Tehachapi, San Gabriel et San Bernadino.","La rivière Mojave (Mojave River) est une source d'eau importante pour l'irrigation. En outre, une partie du fleuve Colorado traverse l'est du désert de Mojave."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_des_Mojaves","sw":"w","q":"Q184355","pays":["US"],"c":["amerique-nord"]},"desert-du-cholistan":{"n":"désert du Cholistan","t":"désert","km2":26300,"bref":["Le désert du Cholistan est situé dans le Pendjab pakistanais. Il est la continuation du désert du Thar situé au Rajasthan indien.","Le lit à sec de la rivière Ghaggar-Hakra qui se trouve dans cette zone, est bordé de nombreux sites de la civilisation de la vallée de l'Indus."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_du_Cholistan","sw":"w","q":"Q797491","pays":["PK"],"c":["asie"]},"desert-du-grand-bassin":{"n":"Désert du Grand Bassin","t":"désert","km2":492000,"bref":["Le Grand Bassin des États-Unis (Great Basin en anglais) est un désert de l'Ouest des États-Unis. C'est une région de montagnes, de bassins sédimentaires et de hauts plateaux. La région offre une grande variété de paysages : ceux du parc national du Grand Bassin sont protégés. Faune et flore sont présentes, bien que discrètes, surtout autour des lacs dont la salinité généralement assez élevée est due à l'endoréisme. Couvrant quelque 10 % des États-Unis, le Grand Bassin est la région la plus sèche du pays."],"src":"https://fr.wikipedia.org/wiki/Grand_Bassin_des_%C3%89tats-Unis","sw":"w","q":"Q273446","pays":["US"],"c":["amerique-nord"]},"desert-du-kalahari":{"n":"désert du Kalahari","t":"désert","km2":930000,"bref":["Le désert du Kalahari est une zone semi-aride située dans une immense cuvette du plateau intérieur de l'Afrique australe et s'étendant sur 930 000 kilomètres carrés depuis la rivière Auab, située en Namibie et affluent de l'Orange, à l'ouest, jusqu'à la rivière Shashi, affluent du Limpopo, à l'est, et depuis le delta de l'Okavango, au Botswana, au nord, jusqu'au fleuve Orange et à son affluent le Vaal au sud, dans la province du Cap-Nord en Afrique du Sud."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_du_Kalahari","sw":"v","q":"Q47700","pays":["BW","NA","AO","ZA"],"c":["afrique"]},"desert-du-karakoum":{"n":"désert du Karakoum","t":"désert","km2":400000,"bref":["Le désert du Karakoum, ou du Kara-Koum (en turkmène : Garagum, en ouzbek : Qoraqum, en russe : Каракумы, ce qui veut dire « Sables noirs »), s'étend en Asie centrale, essentiellement au Turkménistan dont il occupe plus de la moitié du territoire (350 000 km2)."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_du_Karakoum","sw":"w","q":"Q172702","pays":["TM"],"c":["asie"]},"desert-du-kyzylkoum":{"n":"désert du Kyzylkoum","t":"désert","km2":298000,"bref":["Le désert du Kyzylkoum ou désert du Kyzyl-Koum (en ouzbek : Qizilqum ; en russe : Кызылкум, Kyzylkoum ; en kazakh : Қызылқұм, Qyzylqum, litt. « sable rouge ») est un désert partagé entre le Kazakhstan, l'Ouzbékistan et, pour une petite partie, le Turkménistan."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_du_Kyzylkoum","sw":"w","q":"Q184364","pays":["TM","KZ","UZ"],"c":["asie","europe"]},"desert-du-namib":{"n":"Désert du Namib","t":"désert","km2":81000,"bref":["Le désert du Namib est un désert situé dans le sud-ouest de la Namibie. C'est le plus vieux désert du monde, il est aride depuis 80 millions d'années."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_du_Namib","sw":"v","q":"Q131377","pays":["NA"],"c":["afrique"]},"desert-du-taklamakan":{"n":"désert du Taklamakan","t":"désert","km2":337000,"bref":["Le désert du Taklamakan — en chinois Taklimakan shamo, aussi écrit simplement Takla Makan — est le plus grand désert de Chine : il mesure 1 000 km d'est en ouest pour 500 km du nord au sud. C'est en surface le troisième désert de sable au monde, après le Sahara et le Kalahari. Il occupe la plus grande partie du bassin du Tarim, dans le Nord-Ouest de la Chine. Il se trouve dans la région autonome du Xinjiang où la population ouïgoure (peuple d'Asie centrale) est très importante. Il est en position d'abri entre les montagnes du Kunlun et du Tian Shan, si bien que les précipitations y sont très faibles. Sa superficie est d'environ 340 000 km2, c'est-à-dire presque la taille de l'Allemagne.","Divers peuples vivent dans le désert du Takla Makan : les Ouïgours, les Kirghizes et les Kazakhs. Ce sont des nomades élevant des moutons."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_du_Taklamakan","sw":"v","q":"Q132956","pays":["CN"],"c":["asie"]},"desert-du-thar":{"n":"désert du Thar","t":"désert","km2":200000,"bref":["Le désert du Thar (rajasthani : थार मरुधर (thār marudhar) ; hindi : थार मरुस्थल (thār marusthal) ou थार रेगिस्तान (thār rēgistān)) — appelé aussi le Grand Désert indien ou Mârusthali, le Pays de la mort — est un désert qui s'étend sur 200 000 km2 dans l'État du Rajasthan, dans le nord-ouest de l'Inde et au Pakistan où il est appelé désert du Cholistan."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_du_Thar","sw":"w","q":"Q172691","pays":["IN","PK"],"c":["asie"]},"desert-libyque":{"n":"désert Libyque","t":"désert","km2":1100000,"bref":["Le désert Libyque ou désert de Libye est un désert, d'environ 700 000 km2, situé dans la partie ouest de l'Égypte, la partie est de la Libye et au nord-ouest du Soudan. Ce désert est une partie du Sahara. Une partie de sa surface constituée de calcaire est appelée désert blanc.","En Égypte, le désert est aussi appelé désert occidental par opposition au désert oriental (désert arabique)."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_Libyque","sw":"w","q":"Q181528","pays":["LY","EG","SD"],"c":["afrique"]},"grand-desert-de-sable":{"n":"Grand désert de sable","t":"désert","km2":284993,"bref":["Le Grand Désert de Sable (en anglais : Great Sandy Desert) est une vaste plaine désertique de 360 000 km2 dans le nord-ouest de l'Australie. Région très peu peuplée, sans aucune localité notable, elle est partagée entre les chaînes du Pilbara et le Kimberley. Au sud-est, elle se prolonge par le désert de Gibson et à l'est par le désert de Tanami. Seule la région côtière à l'ouest compte quelques élevages de moutons."],"src":"https://fr.wikipedia.org/wiki/Grand_D%C3%A9sert_de_Sable","sw":"w","q":"Q326896","pays":["AU"],"c":["oceanie"]},"grand-desert-de-victoria":{"n":"Grand désert de Victoria","t":"désert","km2":348750,"bref":["Le grand désert de Victoria (en anglais : The Great Victoria Desert) est une écorégion désertique du sud de l'Australie, à cheval sur l'Australie-Occidentale et l'Australie-Méridionale. Elle fait partie de l'écozone australasienne et du biome des déserts et terres arbustives xériques. On y trouve des dunes de sable, des zones d'herbes sèches et des lacs de sel. Il s'étale, d'est en ouest, sur 700 km de large et couvre une superficie de 424 400 km2.","Les moyennes de précipitations annuelles se situent autour de 200 à 250 mm par an et les orages n'y sont pas rares (15 à 20 par an). Les températures oscillent entre 32 et 40 °C en été et 18 et 23 °C en hiver.","Le grand désert de Victoria fut traversé pour la première fois en 1875, par l'explorateur britannique Ernest Giles qui lui donna le nom de la reine d'Angleterre de l'époque, Victoria du Royaume-Uni."],"src":"https://fr.wikipedia.org/wiki/Grand_d%C3%A9sert_de_Victoria","sw":"w","q":"Q145165","pays":["AU"],"c":["oceanie"]},"neguev":{"n":"Néguev","t":"désert","km2":13000,"bref":["Le Néguev (de l'hébreu : נֶגֶב ; en arabe : النقب - Naqab) est une région désertique du sud d'Israël. En hébreu biblique, Néguev signifie « sud ». Le Néguev couvre la plus grande part du district sud d’Israël."],"src":"https://fr.wikipedia.org/wiki/N%C3%A9guev","sw":"w","q":"Q162843","pays":["IL"],"c":["asie"]},"painted-desert":{"n":"Painted Desert","t":"désert","km2":19400,"bref":["Le Painted Desert (désert peint) occupe une partie du Petrified Forest National Park dans l'Arizona, à l'ouest des États-Unis. Constitué de badlands, il est renommé pour ses couleurs brillantes et variées qui lui donnent son nom. Le Painted Desert continue vers le nord dans la nation Navajo, où les déplacements hors route ne sont possibles que sur autorisation.","Le désert mesure environ 120 km de long sur 190 km de large, ce qui en fait une superficie d’environ 378 km2 au total."],"src":"https://fr.wikipedia.org/wiki/Painted_Desert","sw":"w","q":"Q936252","pays":["US"],"c":["amerique-nord"]},"petit-desert-de-sable":{"n":"Petit désert de sable","t":"désert","km2":111500,"bref":["Le Petit Désert de Sable est un désert situé en Australie-Occidentale au sud-ouest du Grand Désert de Sable et à l'ouest du désert de Gibson. Il doit son nom à sa proximité et à sa similitude (sauf pour la taille) avec le Grand Désert de Sable. Ses paysages, sa faune et sa flore sont comparables en tout point avec ceux de son voisin. Les deux déserts sont traversés par le chemin pour le bétail de Canning (Canning cattle route en anglais), un chemin de 1800 kilomètres qui relie Halls Creek à Wiluna à travers le désert, découvert par Alfred Canning (en), qui repéra 52 puits sur le trajet."],"src":"https://fr.wikipedia.org/wiki/Petit_D%C3%A9sert_de_Sable","sw":"w","q":"Q4076","pays":["AU"],"c":["oceanie"]},"rub-al-khali":{"n":"Rub al-Khali","t":"désert","km2":680000,"bref":["Le Rub al Khali (en arabe الربع الخالي, littéralement le « Quart Vide ») est l'un des plus grands déserts et la plus grande étendue ininterrompue de sable au monde. Il occupe environ 650 000 km2 dans le tiers le plus méridional de la péninsule Arabique.","Il a approximativement la forme d'un rectangle de 1 000 kilomètres de longueur et 500 kilomètres de largeur. Il est situé pour l'essentiel sur le territoire de l'Arabie saoudite et pour une bien moindre part sur les territoires du Yémen, d'Oman et des Émirats arabes unis. Son altitude varie du niveau de la mer dans son nord-est, à environ 800 m d'altitude dans son sud-ouest.","Certaines dunes atteignent 250 mètres de haut. Sous l'effet des vents, elles se déplacent en quelques heures. Elles sont parfois entrecoupées de plaines de gravier et de gypse. Le sable est d'une couleur orange rougeâtre due à la présence de feldspath. On rencontre également des marais salants saumâtres dans certaines zones, comme Umm al Samim."],"src":"https://fr.wikipedia.org/wiki/Rub_al-Khali","sw":"w","q":"Q229269","pays":["AE","SA","YE","OM"],"c":["asie"]},"sahara":{"n":"Sahara","t":"désert","km2":9200000,"bref":["Le Sahara, au nord de l'Afrique, est le plus grand désert du monde (plus de 8 millions de km²) ; en arabe, le mot صحر (Sahara) signifie désert.","Cette vaste région chaude s'étend sur 10 pays : la Tunisie, l'Algérie, le Maroc, la Libye, l'Égypte, le Soudan, le Tchad, le Niger, le Mali et la Mauritanie. La température la plus chaude est de +55 °C.","La température la plus chaude jamais enregistrée a été enregistrée en Libye en 1923 et la température était de +57 °C."],"src":"https://fr.vikidia.org/wiki/Sahara","sw":"v","q":"Q6583","pays":["DZ","TD","EG","MA","TN","MR","NE","ML","SD"],"c":["afrique"]},"sinai":{"n":"Sinaï","t":"désert","km2":60000,"bref":["Le Sinaï est une péninsule égyptienne triangulaire, célèbre pour son importance historique, géographique et religieuse."],"src":"https://fr.vikidia.org/wiki/Sina%C3%AF","sw":"v","q":"Q36755","pays":["EG"],"c":["afrique"]},"steppe-de-la-faim":{"n":"Steppe de la Faim","t":"désert","km2":75000,"bref":["La steppe de la Faim, Bet-Pak-Dala ou Betpak-Dala, est un désert du Kazakhstan situé à l'ouest du lac Balkhach, entre le fleuve Tchou et la rivière Saryssou. Sa superficie est d'environ 75 000 km2[réf. nécessaire].","En mai 2015, une mystérieuse épidémie décime les troupeaux de saïgas présents dans le désert, si bien qu'en novembre 2015 il ne reste plus que 12 % de la population initialement présente."],"src":"https://fr.wikipedia.org/wiki/Steppe_de_la_Faim_(Kazakhstan)","sw":"w","q":"Q1359850","pays":["KZ"],"c":["asie","europe"]},"tenere":{"n":"Ténéré","t":"désert","km2":400000,"bref":["Le Ténéré, surnommé aussi le « désert des déserts », est une région hyper-aride de plaines sableuses située dans la partie centre-sud du Sahara qui s'étend au Niger. Délimité par le massif de l'Aïr à l'ouest, le Hoggar au nord, le plateau du Djado au nord-est et le bassin du lac Tchad au sud, le Ténéré couvre 400 000 km2. Ce terme vient de l'expression tamasheq (la langue des Touareg) tin ere, « celle qui rend », en référence aux dunes de sable formés par le vent (l'erg), et signifie simplement « désert »."],"src":"https://fr.wikipedia.org/wiki/T%C3%A9n%C3%A9r%C3%A9","sw":"w","q":"Q272521","pays":["NE"],"c":["afrique"]},"vallee-de-la-mort":{"n":"vallée de la Mort","t":"désert","bref":["La vallée de la Mort (en anglais, Death Valley) est une vallée désertique du sud-ouest des États-Unis, à proximité du Mexique ; plus précisément au sud-est de l'État de Californie, entre deux chaînes de montagnes : la chaîne de Panamint à l'ouest et la chaîne d'Amargosa à l'est.","Ce désert est le cœur du plus grand parc naturel national des États-Unis après celui de l'Alaska : le parc national de la vallée de la Mort (Death Valley National Park), dont le territoire, essentiellement californien, déborde un peu sur l'État du Nevada.","La température est très élevée et a déjà atteint 56,7°."],"src":"https://fr.vikidia.org/wiki/Vall%C3%A9e_de_la_Mort","sw":"v","q":"Q118388","pays":["US"],"c":["amerique-nord"]}},
"continents":{"afrique":{"n":"Afrique","id":"afrique","t":"continent","km2":29648481,"pop":1549862036,"npays":60,"bref":["L'Afrique est l'un des six continents de la Terre. Il regroupe cinquante-quatre pays. Avec une superficie de 30 415 873 km2, il recouvre près de 20 % de la surface des terres émergées. Le Nil, son plus long fleuve (dont une partie coule en Égypte), est aussi le deuxième fleuve de la planète, derrière l'Amazone. En 2026, sa population dépassait les 1,59 milliard d'habitants ; c'est par la population le deuxième continent du monde après l'Asie. C'est aussi en Afrique que se produit le plus important rift continental du monde. Il s'agit du rift est-africain ou vallée du Grand Rift. Ce dernier nom a été donné par l'explorateur John Walter Gregory.","On distingue l'Afrique du Nord et l'Afrique subsaharienne, c'est-à-dire celle située sous le désert du Sahara, le plus vaste du monde après les étendues glacées de l'Antarctique. L'Afrique subsaharienne peut être divisée en Afrique de l'Ouest, Afrique centrale, Afrique orientale et Afrique australe."],"src":"https://fr.vikidia.org/wiki/Afrique","sw":"v","q":"Q15"},"amerique-du-nord":{"n":"Amérique du Nord","id":"amerique-nord","t":"continent","km2":21329947,"pop":617280500,"npays":40,"bref":["L'Amérique du Nord est la partie du continent américain qui se trouve au nord de l'Amérique centrale. Elle comprend le Groenland (sur les plans géographique et géologique, le plan politique n'intervenant pas dans la définition des continents), le Canada, les États-Unis et le Mexique.","Il est à noter que les géologues, géographes et historiens sont partagés sur leur façon de concevoir l'Amérique, et donc, l'Amérique du Nord : y a-t-il un ou deux continents américains ? L'Amérique centrale pourrait poser question, mais tous les géographes sont d'accord pour l'inclure dans l'Amérique du Nord dont elle constitue une région.","Nombreuses sont les interrogations et les définitions d'un continent, de l'Amérique, des Amériques... Aussi, selon les cas, l’Amérique du Nord est considérée soit comme un continent à part entière, soit comme la partie nord du continent américain. Mais, dans tous les cas, elle se positionne à l’est de l’océan Pacifique, à l’ouest de l’océan Atlantique, au sud de l’océan Arctique et au nord de l’Amérique du Sud."],"src":"https://fr.vikidia.org/wiki/Am%C3%A9rique_du_Nord","sw":"v","q":"Q49"},"amerique-du-sud":{"n":"Amérique du Sud","id":"amerique-sud","t":"continent","km2":17461112,"pop":438104941,"npays":15,"bref":["L'Amérique du Sud est la partie sud du continent américain, au sud de l'Amérique centrale, mais elle est souvent considérée comme un continent à part entière."],"src":"https://fr.vikidia.org/wiki/Am%C3%A9rique_du_Sud","sw":"v","q":"Q18"},"antarctique":{"n":"Antarctique","id":"antarctique","t":"continent","km2":14106900,"pop":5000,"npays":1,"bref":["L'Antarctique est le continent le plus austral du monde et abrite le pôle Sud. La mer la plus proche du pôle est la banquise de Ross, une dèpendance de l'océan Pacifique. Avec une superficie de 14,1 millions de kilomètres carrés, il est presque entièrement couvert de glace et comprend les régions les plus froides de la planète. Contrairement à l'Arctique qui est un océan recouvert de glace (la banquise), l'Antarctique est un continent. Entièrement entouré par les océans Atlantique, Indien et Pacifique, il est très isolé par rapport aux autres continents, se situant en effet à 3 850 km de l'Afrique du Sud et 970 km de l'Amérique du Sud. Consistant en un immense plateau d'une altitude moyenne de 2 355 mètres d'altitude, on y trouve aussi de véritables montagnes comme la chaîne Sentinel qui culmine au mont Vinson à 4 892 mètres d'altitude."],"src":"https://fr.vikidia.org/wiki/Antarctique","sw":"v","q":"Q51"},"asie":{"n":"Asie","id":"asie","t":"continent","km2":44614500,"pop":4977954915,"npays":52,"bref":["L'Asie est le continent le plus étendu avec une superficie de 43 810 582 km2 (soit 29,4 % des terres émergées). Il dépasse l'étendue du continent américain de 3,84 %. C'est aussi le plus peuplé avec environ 58,46% des humains, appelés Asiatiques.","Sa forme est massive, l'Asie forme un bloc d'un seul tenant. Elle est liée à l'Europe au niveau des monts Oural et limitée par le fleuve Oural au sud de la chaîne. C'est en Asie que se trouve le point terrestre le plus éloigné des étendues maritimes (à 2 750 km). L'Asie est presque entièrement située dans l'hémisphère nord, à l'exception des Petites îles de la Sonde, des Moluques méridionales et d'une partie des Grandes îles de la Sonde situées en Insulinde. L'Asie est enfin le continent des hautes montagnes, et même celui des plus élevées du monde."],"src":"https://fr.vikidia.org/wiki/Asie","sw":"v","q":"Q48"},"europe":{"n":"Europe","id":"europe","t":"continent","km2":10186000,"pop":744094971,"npays":54,"bref":["L'Europe est un continent. L'usage traditionnel définit le continent comme étant l'une des cinq parties du monde. Elle est bordée par l'océan Atlantique à l'ouest, par l'océan Arctique au nord, par la mer Méditerranée et la mer Noire au sud et par le massif ancien de l'Oural (qui la sépare de l'Asie) et la mer Caspienne à l'est. Dans un sens plus géographique et plus rigoureux, le continent est entendu comme une « vaste étendue de terres émergées d'un seul tenant entourée d'océans ». D'où l'on déduit que cet ensemble géographique n'est pas un continent puisqu'il fait partie, tout comme l'Asie, d'un ensemble plus vaste : l'Eurasie, appelée aussi parfois « continent eurasiatique ».","Dans les limites telles que les a déterminées le tsar Pierre Ier, l'Europe n'est pas une péninsule. Elle est soudée à l'Asie non par un seul côté mais sur deux côtés : à l'est, les monts Oural puis le fleuve Oural jusqu'à la mer Caspienne et au sud-est la chaîne du Caucase entre la mer Noire et la mer Caspienne."],"src":"https://fr.vikidia.org/wiki/Europe","sw":"v","q":"Q46"},"oceanie":{"n":"Océanie","id":"oceanie","t":"continent","km2":1260000,"pop":12355695,"npays":26,"bref":["L'Océanie est une région ou, selon certaines classifications, l’un des continents du monde ; elle est située dans l'océan Pacifique, s'étend sur 8 525 989 km2 et compte 46,089 millions d'habitants en 2024, répartis entre seize États indépendants et quinze territoires","Souvent assimilée à un continent par les géographes, l’Océanie peut être considérée comme le moins étendu des continents émergés de la Terre. Elle englobe toutes les terres situées entre l'Asie de l'Est et l'Asie du Sud-Est à l'ouest et l'Amérique à l'est. Elle comprend aussi une petite partie de l'archipel malais (Îles Raja Ampat et archipel Aru). Elle est divisée en quatre régions : l'Australasie, la Micronésie, la Mélanésie et la Polynésie, bien que cette distinction soit controversée."],"src":"https://fr.wikipedia.org/wiki/Oc%C3%A9anie","sw":"w","q":"Q538"}}
});
